    const genericMods=(p.skillModifiers||[]).filter(m=>!(m.source==='maestria'||(!m.source&&Number(m.delta)===1&&Number(m.remaining)<=3)));
    for(const m of genericMods)push(modifierCauseLabel(m.source,m.delta),compactFloatModifier(m.delta,'APTIDÃO',m.remaining));
