    editorAccess:false, soundMuted:false, soundtrackMuted:false, hideDiceRolls:false, combatMode:'action', quickCombatBusy:false, quickCombatTimer:null, musicPlaying:false, musicVideoId:null, currentMusicUrl:null, activeMusicUrl:null, musicFallback:false, musicMode:null, musicNoticeShown:false, musicFadeTimer:null, musicFadeToken:0, musicFadeLevel:1, musicRandomStart:0, ambientTimer:null, ambientNodes:[], ambientMaster:null, audioPrimed:false, transientAudio:[], editorNav:[], inventorySelection:null, craftingIngredientKey:null, craftingBusy:false, temporalQueue:[], temporalBusy:false, bookmarked:false, activeClimate:'normal', activeTerrain:'neutro', activeTerrainDescription:'', climateTimer:null, climateThunderTimer:null, climateNodes:[], climateMaster:null, sleepPromptPending:false, sleepBusy:false, hungerPromptPending:false, hungerBusy:false, marketPreviousClimate:null, pageTurning:false, latestSectionId:null, premonition:null, tutorialActive:false, tutorialPendingStart:false, tutorialStep:0, forceTutorial:false, adventureStarted:false, adventureCoverActive:false, bookmarkUnlocked:false, bookProgressPercent:1, bookSubpageIndex:0, bookSubpageCount:1, bookPaginationSourceHtml:'', bookPaginationSourceSectionId:null, bookPaginationPages:[], bookPaginationTimer:null, bookPaginationViewportKey:'', difficulty:'heroic', sectionCheckpoint:null, easyDeathPromptActive:false, deathPresentationPending:false, deathFlowActive:false, visitedSectionIds:[], sectionMemory:{}, karmaDraft:{skill:0,stamina:0,magic:0,luck:0}, creationMode:false, creationHeroSetup:false, reloadRecovery:null, readingAssistReady:false, readingAssistEnabled:false, voiceEnabled:false, voiceSpeaking:false, voiceListening:false, voiceContextKey:'', voiceLastSpeech:'', voiceRecognition:null, voiceFollowupSectionId:null, voiceLastNarratedStoryKey:'', voiceLastNarratedPromptKey:'', voiceInventoryDiscardMode:false, voiceAnswerContext:null, terrainDisplayedUrl:'', terrainDisplayedKey:'neutro', terrainLoadingUrl:'', terrainTransitionTimer:null, terrainImageRequestToken:0, sanityRuntime:null, bookPlayerFocus:null, lastPlayerMomentText:'', faerieMarketMode:'', faerieDebtCollecting:false, combatTensionAudio:null, combatTensionMusicDucked:false, inventoryDescriptionNonce:0, heroPortraitCreationSeed:null, editorReapplySectionEffects:false, adventureId:'', journal:[], journalMuted:false
