  function esc(s=''){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
  function cleanText(s=''){ return String(s).trim(); }
  function openSamsaraDB(){
    if(samsaraDbPromise)return samsaraDbPromise;
    samsaraDbPromise=new Promise((resolve,reject)=>{try{const request=indexedDB.open(SAMSARA_DB_NAME,SAMSARA_DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(SAMSARA_DB_ADVENTURES))db.createObjectStore(SAMSARA_DB_ADVENTURES,{keyPath:'id'});if(!db.objectStoreNames.contains(SAMSARA_DB_SAVES))db.createObjectStore(SAMSARA_DB_SAVES,{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);}catch(err){reject(err);}});return samsaraDbPromise;
  }
  async function idbPut(storeName,value){const db=await openSamsaraDB();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readwrite');tx.objectStore(storeName).put(value);tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);});}
  async function idbGet(storeName,key){const db=await openSamsaraDB();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readonly'),req=tx.objectStore(storeName).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});}
  async function idbDelete(storeName,key){try{const db=await openSamsaraDB();return await new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readwrite');tx.objectStore(storeName).delete(key);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);});}catch(err){console.warn('[Samsara DB] exclusão indisponível.',err);return false;}}
  async function deleteSamsaraDatabase(){try{if(samsaraDbPromise){const db=await samsaraDbPromise.catch(()=>null);try{db?.close?.();}catch{}samsaraDbPromise=null;}return await new Promise(resolve=>{const req=indexedDB.deleteDatabase(SAMSARA_DB_NAME);req.onsuccess=req.onerror=req.onblocked=()=>resolve(true);});}catch{return false;}}
  async function persistAdventureDefinition(book=appState.book,filename=appState.currentFilename){if(!book)return false;const id=ensureBookIdentity(book);try{await idbPut(SAMSARA_DB_ADVENTURES,{id,format:SAMSARA_FORMAT_ID,filename:filename||'livro-jogo.md',updatedAt:Date.now(),book:deepClone(book)});appState.adventureId=id;return true;}catch(err){console.warn('[Samsara DB] aventura não persistida.',err);return false;}}
  function writeSavePointer(payload){try{localStorage.setItem(SAVE_POINTER_KEY,JSON.stringify({version:SAMSARA_SAVE_VERSION,adventureId:payload?.adventureId||'',savedAt:Number(payload?.savedAt)||Date.now()}));return true;}catch{return false;}}
  function readSavePointer(){try{const raw=localStorage.getItem(SAVE_POINTER_KEY);return raw?JSON.parse(raw):null;}catch{return null;}}
  function clearSavePointer(){try{localStorage.removeItem(SAVE_POINTER_KEY);}catch{}}
  function invalidateBookmarkSignature(){bookmarkSignatureCache={revision:-1,value:''};}
  function markRuntimeChanged({autosave=true}={}){runtimeRevision++;invalidateBookmarkSignature();if(autosave)scheduleAutosave();return runtimeRevision;}
  function scheduleAutosave(){if(!(appState.book&&appState.player&&!appState.editor&&appState.adventureStarted))return;if(autosaveTimer)clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>{autosaveTimer=null;const task=()=>{if(persistedRevision===runtimeRevision)return;saveAdventureToStorage(false);};if('requestIdleCallback'in window)requestIdleCallback(task,{timeout:1500});else setTimeout(task,0);},750);}
  function autoSaveBookmarked(){scheduleAutosave();}
  const renderAreaHandlers={inventory:()=>renderInventory(),save:()=>renderSaveBookmark(),choices:()=>renderChoices(),effects:()=>renderEffects(),combat:()=>renderCombat(),clock:()=>{renderGameClock();renderTimeLighting();},journal:()=>{if(el('journalDialog')?.open)renderJournal();}};
  function invalidateRender(...areas){const list=areas.flat().filter(Boolean);if(!list.length||list.includes('all')){renderPendingAll=true;}else{if(!invalidateRender.pending)invalidateRender.pending=new Set();for(const area of list)invalidateRender.pending.add(area);}if(renderFrame)return;renderFrame=requestAnimationFrame(()=>{renderFrame=0;const full=renderPendingAll;renderPendingAll=false;const pending=invalidateRender.pending?[...invalidateRender.pending]:[];invalidateRender.pending?.clear?.();if(full)renderAll();else for(const area of pending)try{renderAreaHandlers[area]?.();}catch(err){console.warn(`[Samsara Render] ${area}`,err);}});}

  const JOURNAL_LIMIT=320;
  function ensureJournal(){if(!Array.isArray(appState.journal))appState.journal=[];return appState.journal;}
  function journalClock(minutes=Number(ensureTimeState()?.gameMinutes)||adventureStartMinutes()){const total=Math.max(0,Math.round(Number(minutes)||0)),day=Math.floor(total/1440)+1,clock=formatAdventureClockMinutes(total);return {minutes:total,day,clock,label:`Dia ${day} - ${clock}`};}
  function journalEnabled(){return !!(appState.book&&appState.player&&appState.adventureStarted&&!appState.editor&&!appState.journalMuted);}
  function recordJournal(text,{kind='event',minutes=null,dedupeKey=''}={}){const copy=cleanText(text);if(!copy||!journalEnabled())return null;const time=journalClock(minutes==null?undefined:minutes),journal=ensureJournal(),duplicate=dedupeKey?journal.find(entry=>entry?.dedupeKey===dedupeKey&&entry?.minutes===time.minutes&&entry?.text===copy):null;if(duplicate)return duplicate;const entry={id:`jr-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`,minutes:time.minutes,day:time.day,clock:time.clock,text:copy,kind,dedupeKey};journal.push(entry);if(journal.length>JOURNAL_LIMIT)journal.splice(0,journal.length-JOURNAL_LIMIT);markRuntimeChanged();invalidateRender('journal');return entry;}
  function journalItemLabel(item,qty=1){const meta=itemMeta(item),name=isProvisionName(item)?'Provisão':isGoldItem(item)?currencyName():meta.name;return qtyLabel(Math.max(1,Number(qty)||1),name);}
  function journalRecordItem(item,qty,mode='add',verb=''){const n=Math.max(1,Number(qty)||1),label=journalItemLabel(item,n),action=cleanText(verb)||(mode==='add'?'Adquiri':'Gastei');return recordJournal(`${action} ${label}.`,{kind:'item'});}
  function stateRemainingCopy(entry){const remaining=Number(entry?.turnsRemaining);return Number.isFinite(remaining)?`${entry.name}: ${Math.max(0,remaining)} turno${remaining===1?'':'s'} restante${remaining===1?'':'s'}`:entry?.name||'';}
  function journalRecordStateAdded(entry){if(!entry||entry.hidden)return;const remaining=stateRemainingCopy(entry);recordJournal(`Adquiri ${remaining}.`,{kind:'state',dedupeKey:`state-add:${stateKey(entry.name)}`});}
  function journalRecordStateRemoved(entry){if(!entry||entry.hidden)return;recordJournal(`Superei ${entry.name}.`,{kind:'state',dedupeKey:`state-remove:${stateKey(entry.name)}`});}
  function journalRecordTimedStates(){if(!journalEnabled())return;for(const entry of playerStates().filter(x=>!x.hidden&&Number.isFinite(Number(x.turnsRemaining))&&Number(x.turnsRemaining)>0)){const copy=stateRemainingCopy(entry);recordJournal(copy+'.',{kind:'state',dedupeKey:`state-remaining:${stateKey(entry.name)}:${entry.turnsRemaining}`});}}
  function journalRecordChoice(choice){const text=cleanText(heroText(choice?.text||''));if(text)recordJournal(`Escolhi “${text.replace(/[“”]/g,'')}”.`,{kind:'choice'});}
  function journalRecordMeal(){return recordJournal('Comi 1 provisão.',{kind:'survival'});}
  function journalRecordSleep(hours=6){const n=Math.max(.5,Number(hours)||6),label=Number.isInteger(n)?String(n):String(n).replace('.',',');return recordJournal(`Dormi por ${label} hora${n===1?'':'s'} e descansei.`,{kind:'survival'});}
  function journalRecordUse(item){const name=itemMeta(item)?.name||cleanText(item);if(name)return recordJournal(`Usei ${name}.`,{kind:'item'});}
  function journalRecordRead(item){const name=itemMeta(item)?.name||cleanText(item);if(name)return recordJournal(`Li ${name}.`,{kind:'knowledge'});}
  function journalRecordSpell(spell,combat=null){const name=cleanText(spell);if(!name)return null;const target=combat&&!combat.won?cleanText(combat.name):'';return recordJournal(target?`Lancei ${name} contra ${target}.`:`Lancei ${name}.`,{kind:'magic'});}
  function journalRecordCombatResolution(c){if(!c?.won||c.sanityIllusion)return null;const name=cleanText(c.name)||'o oponente',outcome=c.outcome||(c.fled?'fuga_monstro':'vitoria_heroi'),key=`combat:${appState.sectionId}:${c.id||c.opponentId||name}:${outcome}`;if(outcome==='poupado')return recordJournal(`Poupei ${name}.`,{kind:'combat',dedupeKey:key});if(c.fled||outcome==='fuga_monstro')return recordJournal(`Venci o confronto contra ${name}; o oponente fugiu.`,{kind:'combat',dedupeKey:key});return recordJournal(`Venci ${name} em combate.`,{kind:'combat',dedupeKey:key});}
  function journalRecordCombatEscape(c){const name=cleanText(c?.name)||'o oponente';return recordJournal(`Fugi do combate contra ${name}.`,{kind:'combat',dedupeKey:`combat-flee:${appState.sectionId}:${c?.id||c?.opponentId||name}`});}
