  function normalizeMediaUrl(raw=''){
    const v=String(raw||'').trim().replace(/\\([\[\]\(\)])/g,'$1');
    const valid=url=>/^(https?:\/\/[^\s<>\[\]\(\)]+|data:(?:image|audio)\/[^\s<>]+|blob:[^\s<>]+)$/i.test(String(url||'').trim());
    if(valid(v))return v;
    const md=v.match(/^\[([^\[\]\n]+)\]\(([^\s\[\]\(\)]+)\)$/);
    if(md){const label=md[1].trim(),url=md[2].trim();if(valid(url)&&(/^https?:\/\//i.test(label)?label===url:true))return url;}
    return '';
  }
  function normalizeMusicUrl(raw=''){
    const v=String(raw||'').trim().replace(/\\([\[\]\(\)])/g,'$1');
    const valid=url=>/^(https?:\/\/[^\s<>\[\]\(\)]+|data:audio\/[^\s<>]+|blob:[^\s<>]+)$/i.test(String(url||'').trim());
    if(valid(v))return v;
    const md=v.match(/^\[([^\[\]\n\(\)]+)\]\(([^\s\[\]\(\)]+)\)$/);
    if(md){const label=md[1].trim(),url=md[2].trim();if(valid(url)&&label===url)return url;}
    return '';
  }
  function mediaLink(raw=''){const url=normalizeMediaUrl(raw);return /^https?:\/\//i.test(url)?`[${url}](${url})`:url;}
  function musicMarker(raw=''){const url=normalizeMusicUrl(raw);return url?`{MUSICA:${mediaLink(url)}}`:''; }
  function deepClone(v){if(v===undefined)return undefined;try{if(typeof structuredClone==='function')return structuredClone(v);}catch{}return JSON.parse(JSON.stringify(v));}
