  const CLIMATE_AI_LABELS={normal:'normal climate',chuva:'rainy climate',tempestade:'stormy climate',neblina:'foggy climate',nevado:'snowy climate',terremoto:'earthquake-struck climate',submerso:'underwater climate',ventania:'windy climate',incendio:'burning climate',magico:'magical climate',assombrado:'haunted climate',divino:'divine climate',eletrico:'electric climate',trevoso:'gloomy climate',tumultuado:'crowded climate'};
