  function previousTrackOptions(){const book=appState.book,items=[],seen=new Set();if(!book)return items;for(const id of book.order||[]){if(id===appState.sectionId)break;const sec=book.sections[id],url=normalizeMusicUrl(sec?.music||'')||normalizeMediaUrl(sec?.music||'')||String(sec?.music||'').trim();if(!url||seen.has(url))continue;seen.add(url);items.push({id,url});}return items.sort((a,b)=>String(b.id).localeCompare(String(a.id),'pt-BR',{numeric:true,sensitivity:'base'}));}
  function renderPreviousTracks(populate=false){const btn=el('previousTracksBtn'),box=el('previousTrackList'),opts=previousTrackOptions();if(btn)btn.classList.toggle('hidden',!opts.length);if(!box||!populate)return;box.innerHTML='';for(const item of opts){const card=document.createElement('div');card.className='previous-track-card';const head=document.createElement('div');head.className='previous-track-card-head';const title=document.createElement('strong');title.textContent=`Seção ${item.id}`;const use=document.createElement('button');use.type='button';use.className='secondary-btn media-select-btn';use.textContent='usar esta trilha';use.onclick=()=>applyPreviousTrack(item.url);head.append(title,use);card.appendChild(head);const yid=youtubeVideoId(item.url);if(yid){const frame=document.createElement('iframe');frame.loading='lazy';frame.allow='encrypted-media';frame.referrerPolicy='strict-origin-when-cross-origin';frame.src=`https://www.youtube-nocookie.com/embed/${encodeURIComponent(yid)}?rel=0`;frame.title=`Prévia da trilha da seção ${item.id}`;card.appendChild(frame);}else{const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=item.url;card.appendChild(audio);}const raw=document.createElement('div');raw.className='previous-track-url';raw.textContent=item.url;card.appendChild(raw);box.appendChild(card);}}
