  function renderImageEditorThumbs(sec=appState.book?.sections?.[appState.sectionId]){const box=el('imageEditorThumbs');if(!box)return;box.innerHTML='';const items=[];if(cleanText(sec?.image||''))items.push({label:'Imagem da seção',url:sec.image});if(cleanText(sectionNpc(sec)?.portrait||'')){const n=sectionNpc(sec);items.push({label:`Retrato · ${cleanText(n.name)}`,url:n.portrait});}for(const c of sectionCombatDefs(sec)){const url=combatDisplayImageUrl(c);if(url)items.push({label:`Oponente · ${c.name}`,url,name:c.name});}box.classList.toggle('hidden',!items.length);el('scenePanelBody')?.classList.toggle('has-preview',!!items.length);renderScenePanelSummary(sec);if(!items.length)return;items.forEach(item=>{const card=document.createElement('figure');card.className='image-thumb-card';const img=document.createElement('img');img.src=item.url;img.alt=item.label;if(item.name)installCombatImageFallback(img,item.name,()=>img.remove());else img.onerror=()=>img.remove();const cap=document.createElement('figcaption');cap.textContent=item.label;card.append(img,cap);box.appendChild(card);});}
