  function closeHungerPrompt(){const d=el('hungerDialog');if(d?.open)d.close();appState.hungerBusy=false;renderAll();}
  function recoverFoodEnergy(amount,label){
    const p=appState.player,before=p.stamina;p.stamina=Math.min(p.initialStamina,p.stamina+Math.max(0,amount||0));const gain=p.stamina-before;
    if(gain>0){playMediaSfx(SFX_URLS.crunch,.46);queueFx('energyUp',label||'ALIMENTO ENCONTRADO',`+${gain} VIDA`);}
    return gain;
  }
  async function testHungerSkill(title,lead){
    const target=effectiveHeroSkill();
    const result=await dramaticRoll({title,lead:`${lead} Você precisa tirar ${target} ou menos em 2d6.`,diceCount:2,evaluate:r=>{const roll=rollUnder2d6(r,target),total=roll.total,success=roll.success;return {total,equation:`${r[0]} + ${r[1]} = ${total}`,headline:roll.criticalSuccess?'ACERTO CRÍTICO':roll.criticalFailure?'FALHA CRÍTICA':success?'SUCESSO':'FRACASSO',detail:`Alvo de APTIDÃO: ${target}.`,success,criticalSuccess:roll.criticalSuccess,criticalFailure:roll.criticalFailure};}});
    return result?.outcome||null;
  }
  async function searchForFood(){
    const p=ensureTimeState();if(!hungerChoicesActive()||p.provisions>0)return;const before=captureState();
    const test=await testHungerSkill('Procurar alimentos','Você vasculha o ambiente em busca de algo comestível.');if(!test)return;
    await advanceAdventureTurns(1,{animate:false,countAwake:true});
    if(!test.success){pushHistory(before);failHungerAttempt('Você procura, mas volta de mãos vazias.');renderAll();return;}
    const found=await dramaticRoll({title:'O que você encontrou?',lead:'Role 1d6 para descobrir o alimento.',diceCount:1,evaluate:r=>{const table={1:{name:'Nada',gain:0},2:{name:'Cogumelos',gain:1},3:{name:'Cogumelos Tóxicos',gain:1,skill:-1},4:{name:'Líquens de Rocha',gain:1},5:{name:'Insetos Crocantes',gain:2},6:{name:'Rato',gain:3}},x=table[r[0]];return {total:r[0],equation:`1d6 = ${r[0]}`,headline:x.name.toUpperCase(),detail:x.gain?`${x.name}: +${x.gain} de VIDA${x.skill?' e -1 de APTIDÃO':''}.`:'Você procura por toda parte e não encontra nada.',food:x};}});if(!found)return;
    pushHistory(before);const food=found.outcome.food;
    if(!food.gain){failHungerAttempt('Você não encontrou alimento.');renderAll();return;}
    recoverFoodEnergy(food.gain,food.name.toUpperCase());if(food.skill){p.skill=Math.max(0,p.skill+food.skill);queueFx('skillFail','COGUMELOS TÓXICOS','-1 APTIDÃO');}recordMeal();renderAll();
  }
  const HUNGER_HUNT_TABLE={
    2:[{templateId:'cobra',provisions:1},{templateId:'bando-morcegos',provisions:1}],
    3:[{templateId:'lagarto',provisions:1}],
    4:[{templateId:'lebre',provisions:1},{templateId:'porco-espinho',provisions:1}],
    5:[{templateId:'lobo',provisions:2}],
    6:[{templateId:'porco-selvagem',provisions:3}]
  };
  async function huntForFood(){
    const p=ensureTimeState();if(!hungerChoicesActive()||p.provisions>0)return;const before=captureState();
    const test=await testHungerSkill('Caçar animais','Você procura rastros e tenta encontrar uma presa nas redondezas.');if(!test)return;
    await advanceAdventureTurns(1,{animate:false,countAwake:true});
    if(!test.success){pushHistory(before);failHungerAttempt('A caçada fracassou antes mesmo de encontrar uma presa.');renderAll();return;}
    const found=await dramaticRoll({title:'Rastreando uma presa',lead:'Role 1d6 para descobrir o que aparece.',diceCount:1,evaluate:r=>{if(r[0]===1)return {total:1,equation:'1d6 = 1',headline:'NADA',detail:'Os rastros desaparecem. Você não encontra nenhum animal.',animal:null};const pool=HUNGER_HUNT_TABLE[r[0]]||[],pick=pool.length?pool[Math.floor(Math.random()*pool.length)]:null,tpl=pick?COMBAT_TEMPLATE_MAP.get(pick.templateId):null;if(!pick||!tpl)return {total:r[0],equation:`1d6 = ${r[0]}`,headline:'NADA',detail:'Os rastros desaparecem antes que você identifique a presa.',animal:null};return {total:r[0],equation:`1d6 = ${r[0]}`,headline:tpl.name.toUpperCase(),detail:`Você encontra ${tpl.name}. Para conseguir alimento, será preciso vencê-lo.`,animal:{templateId:tpl.templateId,provisions:pick.provisions}};}});if(!found)return;
    pushHistory(before);const animal=found.outcome.animal;
    if(!animal){failHungerAttempt('Você não encontrou nenhum animal.');renderAll();return;}
    const tpl=COMBAT_TEMPLATE_MAP.get(animal.templateId),op=normalizeCombatOpponent({...deepClone(tpl),id:combatUid('hunt'),templateId:tpl.templateId,numberExpr:'1',reaction:'HOSTIL'}),c=runtimeCombat({...encounterOpponentPreviewDef(op),name:op.name,baseName:op.name,reaction:'HOSTIL',type:op.type,intelligence:op.intelligence,specialties:op.specialties,damageExpr:op.damageExpr,attacksExpr:op.attacksExpr,message:op.message,habitats:op.habitats,loot:op.loot,aiIllustration:op.aiIllustration});c.hungerHunt=true;c.hungerProvisions=animal.provisions;c.lootCollected=false;c.hungerResolved=false;appState.combats.push(c);setActiveCombat(appState.combats.length-1);appState.effects.push({text:`CAÇA: ${op.name}`,loss:false});renderAll();
  }
  async function resolveHungerHuntVictory(c){
    if(!c?.hungerHunt||c.hungerResolved)return;c.hungerResolved=true;c.lootCollected=true;
    const p=ensureTimeState(),before=p.stamina;recoverFoodEnergy(4,'CAÇA VENCIDA');const added=addQuantity('Provisão',c.hungerProvisions||1);recordMeal();
    await showRewardMoment({kind:'treasure',title:'CAÇA VENCIDA',headline:`${c.name.toUpperCase()} ABATIDO`,detail:`Você recupera ${p.stamina-before} de VIDA e ganha ${added} ${added===1?'Provisão':'Provisões'}.`,icon:'🍖'});
  }

  async function waitTemporalQueue(){while(appState.temporalBusy||appState.temporalQueue.length)await sleep(70);}
  async function advanceAdventureTurns(turns,{animate=false,countAwake=true,allowAutoSleep=true}={}){const p=ensureTimeState();if(!p||adventureEnded())return;const total=Math.max(0,Math.round(turns)),survival=survivalEnabled();if(animate)document.body.classList.add('time-warp');for(let i=0;i<total;i++){const beforeAwake=p.awakeMinutes;p.gameMinutes+=30;if(countAwake&&survival)p.awakeMinutes+=30;tickTurnCounters();advanceTemporalEffects();expireTimedChoiceEffects();await processCombatRebirths();await processDelayedCombatEvents();if(survival){checkHungerClock();if(countAwake){markSleepNeed(beforeAwake,p.awakeMinutes);applyAwakeFatigue();}}renderGameClock();renderTimeLighting();if(animate){renderAll();await sleep(105);}if(survival&&countAwake&&allowAutoSleep&&sleepNeededAutomatically()){if(animate)document.body.classList.remove('time-warp');markRuntimeChanged();journalRecordTimedStates();await performSleep({automatic:true});return;}}if(animate)document.body.classList.remove('time-warp');if(total){markRuntimeChanged();journalRecordTimedStates();invalidateRender('clock','save');}}
  function choiceTimeHours(c){const n=Number(c?.hours);return Number.isFinite(n)&&n>=.5?Math.round(n*2)/2:.5;}
  async function advanceChoiceTime(c){if(Number(c?.minutes)>0){const minutes=Math.max(1,Math.round(Number(c.minutes))),p=ensureTimeState();if(p){p.gameMinutes+=minutes;if(survivalEnabled())p.awakeMinutes+=minutes;expireTimedChoiceEffects();renderGameClock();renderTimeLighting();markRuntimeChanged();journalRecordTimedStates();invalidateRender('clock','save');}return;}const hours=choiceTimeHours(c),turns=Math.max(1,Math.round(hours*2));await advanceAdventureTurns(turns,{animate:hours>.5,countAwake:true});}
  function scheduleSleepPrompt(){if(!survivalEnabled())return;const p=ensureTimeState();if(!p?.sleepDue||!p.sleepPromptPending||adventureEnded()||appState.tutorialActive||appState.editor||appState.sleepBusy||document.body.classList.contains('time-warp'))return;setTimeout(showSleepPrompt,80);}
  function showSleepPrompt(){if(!survivalEnabled())return;const p=ensureTimeState(),d=el('sleepDialog');if(!p?.sleepDue||!p.sleepPromptPending||adventureEnded()||appState.editor||appState.sleepBusy||document.body.classList.contains('time-warp')||!d||d.open)return;if(document.querySelector('dialog[open]')){setTimeout(showSleepPrompt,250);return;}el('sleepNowBtn').classList.toggle('hidden',combatInProgress());d.showModal();}
  function deferSleep(){const p=ensureTimeState();if(!p)return;p.sleepPromptPending=false;appState.sleepPromptPending=false;if(p.awakeMinutes>=sleepyLimitMinutes(p))p.sleepSkillPenalty=1;el('sleepDialog').close();renderAll();toast(p.sleepSkillPenalty?'O sono reduz sua APTIDÃO em 1.':'A opção de dormir continuará disponível.');}
  function sleepVisualPause(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
  function randomDreamSection(){const book=appState.book,ids=(book?.order||[]).filter(id=>id!==appState.sectionId&&book.sections[id]&&cleanText(book.sections[id].text)&&cleanText(book.sections[id].text)!=='Clique em ✏️ para editar');const pool=ids.length?ids:(book?.order||[]).filter(id=>book.sections[id]&&cleanText(book.sections[id].text));if(!pool.length)return null;return book.sections[pool[Math.floor(Math.random()*pool.length)]];}
  async function sleepFade(dark=true){const layer=el('sleepFadeLayer');if(!layer)return;requestAnimationFrame(()=>layer.classList.toggle('active',dark));await sleepVisualPause(760);}
  async function playSleepDream(){const overlay=el('dreamOverlay'),story=el('dreamStory'),wake=el('dreamWakeBtn'),dream=randomDreamSection();if(!overlay||!story||!wake)return;await sleepFade(true);story.innerHTML=renderMarkdownText(dream?.text||'As imagens do mundo se dissolvem em formas impossíveis, e por um instante tudo parece leve.');overlay.classList.remove('hidden');await sleepVisualPause(60);await sleepFade(false);await new Promise(resolve=>{wake.onclick=()=>resolve();});wake.onclick=null;await sleepFade(true);overlay.classList.add('hidden');story.innerHTML='';await sleepVisualPause(60);await sleepFade(false);}
  async function applySleepPassage(p){p.sleepDue=false;p.sleepPromptedThisWake=false;p.sleepSkillPenalty=0;p.sleepFatigueStage=0;p.sleepExtraFatigueStage=0;p.awakeMinutes=0;await advanceAdventureTurns(12,{animate:false,countAwake:false,allowAutoSleep:false});p.lastSleepMinutes=p.gameMinutes;await waitTemporalQueue();journalRecordSleep(6);markRuntimeChanged();if(p.stamina>0){const before=p.stamina;p.stamina=Math.min(p.initialStamina,p.stamina+2);const recovered=p.stamina-before;if(recovered)queueFx('energyUp','DESCANSO','+2 VIDA');const meditation=Math.max(0,Number(knowledgeValue('Meditação'))||0),magicRecovered=recoverMagic(2+meditation);if(magicRecovered){const stat=playerStatLabel('SANIDADE');queueFx('luckWin',`${stat} RESTAURADA`,`+${magicRecovered} ${stat}`);}}await maybeSleepAmbush();}
  async function performSleep({automatic=false}={}){if(!survivalEnabled())return;const p=ensureTimeState();if(!p||adventureEnded()||appState.sleepBusy)return;const nearbyFoe=!automatic?sleepCombatOpponent():null;appState.sleepBusy=true;appState.sleepPromptPending=false;p.sleepPromptPending=false;if(el('sleepDialog')?.open)el('sleepDialog').close();if(nearbyFoe){nearbyFoe.ambush=true;nearbyFoe.traits=[...new Set([...(nearbyFoe.traits||[]),'EMBOSCADA'])];nearbyFoe.ambushResolved=false;nearbyFoe.ambushProcessing=false;const idx=(appState.combats||[]).indexOf(nearbyFoe);if(idx>=0)setActiveCombat(idx);await resolveAmbushCombat(nearbyFoe);appState.sleepBusy=false;renderAll();return;}if(automatic)await showNotice('O corpo cede ao sono',`Depois de ${sleepAutomaticMinutes(p)/60} horas acordado, você já não consegue continuar.`);await playSleepDream();await showNotice('Você acordou renovado','Você dormiu profundamente. O corpo relaxou, a mente clareou e você se sente renovado.',{buttonText:'Continuar',dialogClass:'rested-notice'});await applySleepPassage(p);appState.sleepBusy=false;renderAll();}

  function updateVitalTheme(){
    if(!appState.player){document.documentElement.style.setProperty('--vital','#16a34a');document.documentElement.style.setProperty('--hero-life','100%');return;}
    const p=appState.player,ratio=p.initialStamina>0?Math.max(0,Math.min(1,p.stamina/p.initialStamina)):0;
    document.documentElement.style.setProperty('--hero-life',`${(ratio*100).toFixed(2)}%`);
    if(appState.editor){document.documentElement.style.setProperty('--vital','#6d4aff');return;}
    let color;
    if(ratio>=2/3){const t=(ratio-2/3)/(1/3);color=mixHex('#15803d','#22c55e',t);}
    else if(ratio>=1/3){const t=(ratio-1/3)/(1/3);color=mixHex('#eab308','#15803d',t);}
    else{const t=ratio/(1/3);color=mixHex('#dc2626','#eab308',t);}
    document.documentElement.style.setProperty('--vital',color);
  }

  const DEFAULT_KNOWLEDGES=['Cultura Geral','Botânica','História','Gramática','Matemática','Medicina','Idiomas','Espada','Arco e Flecha','Roubar','Esgueirar','Luta Armada','Meditação','Treino Mágico','Controle Arcano','Artes Ladinas','Malabarismo','Etiqueta','Retórica','Empatia','Comércio','Jogos de Azar','Intimidação','Mentalismo','Malandragem','Colapso Mental','Amnésia'];
  function normalizeKnowledgeName(value=''){return String(value||'').trim().replace(/\s+/g,' ');}
  function knowledgeKey(value=''){return normalizeKnowledgeName(value).normalize('NFD').replace(/[̀-ͯ]/g,'').toLocaleLowerCase('pt-BR');}
  function ensureKnowledgeState(p=appState.player){if(!p)return null;if(!p.knowledges||typeof p.knowledges!=='object'||Array.isArray(p.knowledges))p.knowledges={};if(!Number.isFinite(p.knowledgeBoost))p.knowledgeBoost=0;if(!Number.isFinite(p.knowledgeBoostTurns))p.knowledgeBoostTurns=0;if(!Array.isArray(p.knowledgeCriticalEffects))p.knowledgeCriticalEffects=[];if(!p.readBooks||typeof p.readBooks!=='object'||Array.isArray(p.readBooks))p.readBooks={};return p;}
  function knowledgeEntries(p=appState.player){ensureKnowledgeState(p);return Object.values(p?.knowledges||{}).filter(e=>e&&normalizeKnowledgeName(e.name)&&Number(e.value)>0);}
  function permanentKnowledgeTotal(p=appState.player){return knowledgeEntries(p).reduce((sum,e)=>sum+Math.max(0,Number(e.value)||0),0);}
  function knowledgeValue(name,{effective=true}={}){const p=ensureKnowledgeState(),entry=p?.knowledges?.[knowledgeKey(name)],base=Math.max(0,Number(entry?.value)||0);if(!base)return 0;const boost=effective&&p.knowledgeBoostTurns>0?Math.max(0,Number(p.knowledgeBoost)||0):0;return base+boost;}
  function knowledgeSummaryText(){const entries=knowledgeEntries().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR',{sensitivity:'base'}));if(!entries.length)return 'Perícias: nenhuma.';return `Perícias: ${entries.map(e=>{const value=Math.max(1,Number(e.value)||1);return value>1?`${e.name} x${value}`:e.name;}).join(', ')}.`;}
