  const SAMSARA_FORMAT_ID='SAMSARA-1.0',SAMSARA_LEGACY_SAVE_VERSION=1,SAMSARA_SAVE_VERSION=2;
  function faerieMarketEnabled(book=appState.book){return book?.faerieMarketEnabled!==false;}
  const STAT_TOKEN_ALIASES={'APTIDÃO':'APTIDÃO','APTIDAO':'APTIDÃO','FORTUNA':'FORTUNA','SANIDADE':'SANIDADE','VIDA':'VIDA'};
