  const COMBAT_EVENT_TRIGGERS=['FIRST_ROUND','FIRST_HERO_DAMAGE','FIRST_ENEMY_DAMAGE','FLEE','AFTER_ROUNDS','RANDOM','MONSTER_VICTORY','HERO_VICTORY','ON_HURT','ON_DAMAGE','AFTER_HITS_DEALT','AFTER_HITS_TAKEN','AFTER_WINS_CONSEC','AFTER_LOSSES_CONSEC','AT_LIFE_PERCENT','REMAINING_X','LEADER_DEATH','ON_DEATH','AFTER_DEFEAT_TIME'];
