  function normalizeEncounterDef(def={}){return {version:2,opponents:(def.opponents||[]).map(normalizeCombatOpponent).filter(x=>x.name),events:(def.events||[]).map(normalizeCombatEvent)};}
  function encodeCombatDef(def){const json=JSON.stringify(normalizeEncounterDef(def));try{return btoa(unescape(encodeURIComponent(json)));}catch{return '';}}
  function decodeCombatDef(raw=''){try{return normalizeEncounterDef(JSON.parse(decodeURIComponent(escape(atob(String(raw).trim())))));}catch{return null;}}
