  function parseEncounterDef(block=''){const m=String(block||'').match(/^\{COMBATE_DEF:([^}]+)\}\s*$/mi);return m?decodeCombatDef(m[1]):null;}
  function encounterOpponentPreviewDef(op={}){op=normalizeCombatOpponent(op);return {name:op.name,skillExpr:op.skillExpr,staminaExpr:op.staminaExpr,skill:Number(op.skillExpr)||8,stamina:Number(op.staminaExpr)||8,damageExpr:op.damageExpr,specialties:op.specialties,image:op.image,aiIllustration:op.aiIllustration,numberExpr:op.numberExpr,type:op.type,reaction:op.reaction,intelligence:op.intelligence,loot:op.loot,lore:op.lore,attacksExpr:op.attacksExpr,variation:op.variation,leader:op.leader,morale:op.morale,resistances:op.resistances,contextActions:op.contextActions,drainStat:op.drainStat,drainEvery:op.drainEvery,drainAmountExpr:op.drainAmountExpr,retaliateHitMax:op.retaliateHitMax,retaliateDamageExpr:op.retaliateDamageExpr,rebirthMinutes:op.rebirthMinutes,opponentId:op.id,ambush:op.specialties.includes('EMBOSCADA'),poison:op.specialties.includes('VENENO'),paralyzer:op.specialties.includes('PARALISADOR'),multiple:1};}
  function diceExpressionParts(expr=''){const raw=String(expr||'').trim().replace(/\s+/g,''),m=raw.match(/^(?:(\d*)d(\d+)|(-?\d+))(?:([+-])(\d+))?$/i);if(!m)return null;if(m[3]!=null)return {count:0,sides:0,base:Number(m[3])||0,bonus:(m[4]==='-'?-1:1)*(Number(m[5])||0)};return {count:Math.max(1,Number(m[1])||1),sides:Math.max(2,Number(m[2])||6),base:0,bonus:(m[4]==='-'?-1:1)*(Number(m[5])||0)};}
  function rollDiceExpression(expr='1',{min=0,max=999}={}){const p=diceExpressionParts(expr);if(!p){const dyn=dynamicNumber(expr,null,NaN);return Number.isFinite(dyn)?Math.max(min,Math.min(max,Math.round(dyn))):min;}let n=p.base+p.bonus;for(let i=0;i<p.count;i++)n+=1+Math.floor(Math.random()*p.sides);return Math.max(min,Math.min(max,Math.round(n)));}
  function expectedDiceExpression(expr='1'){const p=diceExpressionParts(expr);if(!p){const n=Number(expr);return Number.isFinite(n)?n:1;}return p.base+p.bonus+(p.count?p.count*(p.sides+1)/2:0);}
  function combatSpecialtyWeight(list=[]){let w=(list||[]).reduce((a,k)=>a+(COMBAT_SPECIALTY_META[k]?.weight||0),0),s=new Set(list||[]);if(s.has('RESILIENTE')&&s.has('VAMPIRO'))w+=.28;if(s.has('EMBOSCADA')&&s.has('RAJADA'))w+=.20;if(s.has('PERTURBADOR')&&s.has('AMALDICOADOR'))w+=.18;if(s.has('VOADOR')&&s.has('ESCORREGADIO'))w+=.18;if(s.has('CAMUFLADO')&&s.has('ESTRATEGICO'))w+=.15;if(s.has('TREINADO')&&s.has('ESPINHUDO'))w+=.15;if(s.has('TELEPORTE')&&s.has('TREINADO'))w+=.16;if(s.has('GRUDENTO')&&s.has('ESCORREGADIO'))w+=.12;if(s.has('ENXAME')&&s.has('DIMINUTO'))w+=.18;if(s.has('GIGANTESCO')&&s.has('ESPINHUDO'))w+=.18;return w;}
  function combatDangerData(op={}){op=normalizeCombatOpponent(op);const skill=Math.max(1,Number(resolveDynamicExpression(op.skillExpr))||Number(op.skillExpr)||8),life=Math.max(1,Number(resolveDynamicExpression(op.staminaExpr))||Number(op.staminaExpr)||8),damage=Math.max(1,expectedDiceExpression(op.damageExpr)||2),attacks=Math.max(1,expectedDiceExpression(op.attacksExpr)||1),qty=Math.max(1,expectedDiceExpression(op.numberExpr)||1),base=.30*(skill/8)+.25*(life/8)+.25*(damage/2)+.20*attacks,qtyFactor=1+.48*Math.log2(Math.max(1,qty)),specialFactor=1+combatSpecialtyWeight(op.specialties),synergy=damage>=3&&attacks>1?1.15:1,score=base*qtyFactor*specialFactor*synergy,skulls=score<.72?1:score<1.35?2:score<1.90?3:score<3.50?4:5,label=['','Baixo','Moderado','Perigoso','Mortal','Extremo'][skulls];return {score,skulls,label,detail:`APTIDÃO ${skill} · VIDA ${life} · DANO ${op.damageExpr} · ATAQUES ${op.attacksExpr} · NÚMERO ${op.numberExpr}${op.specialties.length?` · ${op.specialties.join(', ')}`:''}`};}
  function encounterDangerData(def={}){const ds=(def.opponents||[]).map(combatDangerData);if(!ds.length)return {skulls:0,label:'Sem combate',score:0};const sorted=ds.map(x=>x.score).sort((a,b)=>b-a),score=sorted[0]+sorted.slice(1).reduce((a,x)=>a+x*.35,0),skulls=score<.72?1:score<1.35?2:score<1.90?3:score<3.50?4:5;return {score,skulls,label:['','Baixo','Moderado','Perigoso','Mortal','Extremo'][skulls]};}
