  function parseKnowledgeMarker(raw=''){const m=String(raw||'').trim().match(/^\{([^{}|]+)\((?:Saber|Per[ií]cia)\)\}\s*$/i);return m?normalizeKnowledgeName(m[1]):'';}
  function parseBookGrantMarker(raw=''){const t=String(raw||'').trim();if(!/^\{.*\}$/s.test(t)||!/\(Livro\)\s*\|/i.test(t))return null;const inner=t.slice(1,-1).trim(),pipe=inner.indexOf('|');if(pipe<0)return null;const item=inner.slice(0,pipe).trim(),effect=inner.slice(pipe+1).trim();if(!/\(Livro\)\s*$/i.test(item)||!effect)return null;const meta=itemMeta(`${item}|${effect}`);return {item:meta.raw,effect};}
