  function parseCommerceLine(raw=''){const t=String(raw||'').trim();if(!/^\{COMERCIO:/i.test(t)||!t.endsWith('}'))return null;const inner=t.slice(t.indexOf(':')+1,-1).trim(),sep=inner.lastIndexOf('=>');if(sep<0)return null;const itemSpec=inner.slice(0,sep).trim(),price=Math.max(1,parseInt(inner.slice(sep+2).trim(),10)||0);if(!itemSpec||!price)return null;const qi=parseQtyItem(itemSpec),meta=itemMeta(qi.item);return meta.name?{item:meta.raw,qty:qi.qty,price}:null;}
