        if(context.patienceLow)templates.push(mechanic==='COMOVER'?'“Entendo. Ainda assim, prefiro chegar logo ao ponto.”':'“Esse ponto faz sentido. Prefiro chegar logo ao essencial.”');else if(reaction==='AMISTOSA')templates.push('“Certo. Podemos continuar.”');
