  function npcQuestionAvailable(q,rt=appState.npcRuntime){if(!q||!rt)return false;const answered=new Set(rt.answeredQuestions||[]);if(answered.has(q.id))return false;if(q.unlockAfter)return answered.has(q.unlockAfter);return !!q.start;}
  function npcAvailableQuestions(){const npc=npcSocialDefinition(),rt=ensureNpcRuntimeShape(appState.npcRuntime);if(!npc||!rt)return[];const casual=npcAvailableCasualQuestions(npc,rt),authored=npc.dialogues.filter(q=>npcQuestionAvailable(q,rt)).map(q=>({...q,source:'AUTHOR',canonical:true}));if(casual.length&&Number(rt.smallTalkStage||0)<=0)return casual;if(casual.length)return [...casual,...authored];return authored;}
  function openNpcConversation(){const npc=npcSocialDefinition(),rt=ensureNpcRuntimeShape(appState.npcRuntime),box=el('npcConversationList');if(!npc||!rt||!box)return;box.innerHTML='';const casual=npcAvailableCasualQuestions(npc,rt),etiquette=npcApproachKnowledgeBonus('CONVERSAR');if(casual.length&&etiquette>=1){const family=npcSmallTalkFamily(rt),hint=document.createElement('div');hint.className='npc-smalltalk-hint';hint.textContent=npcSmallTalkEtiquetteHint(family,npc);box.appendChild(hint);}for(const q of npcAvailableQuestions()){const b=document.createElement('button');b.type='button';b.textContent=q.question;b.dataset.source=q.source||'AUTHOR';if(q.casualAppropriate&&etiquette>=2)b.classList.add('npc-smalltalk-fit');b.onclick=()=>resolveNpcConversation(q.id);box.appendChild(b);}if(!box.children.length)box.innerHTML='<div class="empty-state">Nenhum assunto disponível.</div>';if(!el('npcConversationDialog').open)el('npcConversationDialog').showModal();}
