    const avatar=box.querySelector('.npc-box-avatar');if(avatar){makeDialogueImageClickable(avatar,portraitUrl,npc.name);avatar.onerror=e=>{const img=e.currentTarget;img.onerror=null;img.src=DEFAULT_DIALOGUE_AVATAR;makeDialogueImageClickable(img,DEFAULT_DIALOGUE_AVATAR,npc.name);};}box.querySelector('[data-role="npc-lore-btn"]')?.addEventListener('click',showNpcLog);
    const actionsHost=box.querySelector('[data-role="npc-reader-actions"]');if(active&&actionsHost){const actions=getNpcAvailableActions();if(actions.length)renderAvailableActions(actionsHost,actions,{choice:false});else actionsHost.innerHTML='<div class="npc-box-empty-actions">Nenhuma abordagem está disponível neste momento.</div>';}
    else if(actionsHost)actionsHost.innerHTML=`<div class="npc-box-empty-actions">${rt.outcome==='yielded'?esc(npcTreasureAcquisitionSentence(npc)):rt.outcome==='combat'?'A conversa terminou em confronto.':rt.outcome==='combat-won'?'O obstáculo foi superado.':rt.outcome==='section'?'A conversa mudou o rumo da história.':rt.outcome==='defeat'?'Algo essencial para a história ficou para trás.':rt.outcome==='final'?'Este encontro levou ao desfecho.':'O NPC encerrou a conversa.'}</div>`;
