  function npcPopulateTemplateSelect(){const sel=el('npcTemplateSelect');if(!sel)return;sel.innerHTML='<option value="">Personalizado</option>'+NPC_TEMPLATES.map(t=>`<option value="${esc(t.templateId)}">${esc(t.name)}</option>`).join('');}
  function npcEditorQuestionOptions(draft,currentId=''){return '<option value="">— nenhuma —</option>'+draft.dialogues.filter(q=>q.id!==currentId).map(q=>`<option value="${esc(q.id)}">${esc(q.question||'Pergunta sem texto')}</option>`).join('');}
  function renderNpcApproachEditor(){const box=el('npcApproachEditor'),draft=appState.npcEditorDraft;if(!box||!draft)return;box.innerHTML='';for(const key of NPC_EDITOR_APPROACH_ORDER){const meta=NPC_APPROACH_META[key],cfg=draft.approaches[key],row=document.createElement('div');row.className='npc-approach-row';row.innerHTML=`<label><input type="checkbox" data-npc-approach-enabled="${key}"${cfg.enabled?' checked':''}> ${esc(meta.label)}</label><input type="text" data-npc-approach-label="${key}" value="${esc(cfg.label)}" placeholder="Título no botão (opcional)">`;row.querySelector('[data-npc-approach-enabled]').onchange=e=>cfg.enabled=e.target.checked;row.querySelector('[data-npc-approach-label]').oninput=e=>cfg.label=e.target.value;box.appendChild(row);}}
  function renderNpcDialogueEditor(){
    const box=el('npcDialogueEditor'),draft=appState.npcEditorDraft;if(!box||!draft)return;box.innerHTML='';
    draft.dialogues.forEach((q,index)=>{
      const card=document.createElement('div'),availabilityName=`npc-dialogue-availability-${q.id}`;card.className='npc-dialogue-card';
      const startMode=!!q.start&&!q.unlockAfter;
      card.innerHTML=`<button class="npc-dialogue-remove" type="button" title="Remover">✕</button><div class="npc-dialogue-card-grid"><label class="full">Pergunta<input data-q="question" value="${esc(q.question)}"></label><label>Impacto na RESISTÊNCIA<input data-q="impact" type="number" step="1" value="${q.impact}"></label><label class="full">Resposta<textarea data-q="response" rows="3">${esc(q.response)}</textarea></label></div><div class="npc-dialogue-deps"><label><span><input data-q="startMode" type="radio" name="${esc(availabilityName)}"${startMode?' checked':''}> Liberar desde o início</span></label><label><span><input data-q="afterMode" type="radio" name="${esc(availabilityName)}"${startMode?'':' checked'}> Liberar após responder</span><select data-q="unlockAfter"${startMode?' disabled':''}>${npcEditorQuestionOptions(draft,q.id)}</select></label></div>`;
      card.querySelector('[data-q="question"]').oninput=e=>{q.question=e.target.value;};
      card.querySelector('[data-q="impact"]').oninput=e=>q.impact=Math.round(Number(e.target.value)||0);
      card.querySelector('[data-q="response"]').oninput=e=>q.response=e.target.value;
      const startRadio=card.querySelector('[data-q="startMode"]'),afterRadio=card.querySelector('[data-q="afterMode"]'),unlock=card.querySelector('[data-q="unlockAfter"]');
      unlock.value=q.unlockAfter||'';
      startRadio.onchange=()=>{if(!startRadio.checked)return;q.start=true;q.unlockAfter='';unlock.value='';unlock.disabled=true;};
      afterRadio.onchange=()=>{if(!afterRadio.checked)return;q.start=false;unlock.disabled=false;};
      unlock.onchange=e=>{q.unlockAfter=e.target.value;q.start=false;afterRadio.checked=true;startRadio.checked=false;};
      card.querySelector('.npc-dialogue-remove').onclick=()=>{draft.dialogues.splice(index,1);for(const other of draft.dialogues){if(other.unlockAfter===q.id){other.unlockAfter='';other.start=true;}}renderNpcDialogueEditor();};
      box.appendChild(card);
    });
    if(!draft.dialogues.length)box.innerHTML='<div class="empty-state">Nenhuma pergunta cadastrada.</div>';
  }
  function npcClosureOptions(essential=false){return essential?[['DEFEAT','Derrota'],['COMBAT','Iniciar Combate'],['SECTION','Ir para seção']]:[['END','Encerrar encontro'],['COMBAT','Iniciar Combate'],['FINAL','FINAL']];}
  function npcClosureTargetDisplay(target=''){const id=cleanText(target),sec=id?appState.book?.sections?.[id]:null;return sec?`${id} · ${firstText(sec.text)||'seção sem texto'}`:(id?`${id} · seção inexistente`:'');}
  function npcUpdateClosureTargetDisplay(){const input=el('npcClosureTargetInput'),d=appState.npcEditorDraft;if(input)input.value=npcClosureTargetDisplay(d?.closure?.target||'');}
  function npcSyncEssentialEditor(){const d=appState.npcEditorDraft,check=el('npcEssentialCheck'),select=el('npcClosureSelect');if(!d||!check||!select)return;const essential=!!check.checked,prior=String(d.closure?.type||select.value||'END').toUpperCase(),allowed=npcClosureOptions(essential),values=new Set(allowed.map(x=>x[0])),next=values.has(prior)?prior:(prior==='COMBAT'?'COMBAT':essential?'DEFEAT':'END');d.essential=essential;d.closure=d.closure||{type:next,text:'',target:''};d.closure.type=next;if(next!=='SECTION')d.closure.target='';if(essential&&next!=='COMBAT')d.closure.text='';select.innerHTML=allowed.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');select.value=next;el('npcClosureLabel').textContent=essential?'Se a RESISTÊNCIA chegar ao máximo':'Fechamento';el('npcClosureTargetRow').classList.toggle('hidden',next!=='SECTION');el('npcClosureTextWrap').classList.toggle('hidden',essential&&next!=='COMBAT');if(!el('npcClosureTextWrap').classList.contains('hidden'))el('npcClosureTextInput').value=d.closure.text||'';npcUpdateClosureTargetDisplay();}
  function npcReadEditorIntoDraft(){const sec=appState.book?.sections?.[appState.sectionId],d=appState.npcEditorDraft;if(!sec||!d)return null;d.name=cleanText(el('npcNameInput').value)||'NPC';d.physicalDescription=String(el('npcPhysicalDescriptionInput').value||'').trim();d.aiIllustration=!!el('npcAiIllustrationCheck').checked;d.portrait=d.aiIllustration?npcPortraitAiUrl(d,sec):cleanText(el('npcPortraitInput').value);d.skill=Math.max(0,Math.round(Number(el('npcSkillInput').value)||0));d.stamina=Math.max(1,Math.round(Number(el('npcStaminaInput').value)||1));d.sanity=Math.max(0,Math.round(Number(el('npcSanityInput').value)||0));d.luck=Math.max(0,Math.round(Number(el('npcLuckInput').value)||0));d.maxResistance=Math.max(1,Math.round(Number(el('npcMaxResistanceInput').value)||10));d.resistance=Math.max(0,Math.min(d.maxResistance,Math.round(Number(el('npcResistanceInput').value)||0)));d.alignment=el('npcAlignmentSelect').value;d.reaction=el('npcReactionSelect').value;d.intelligence=el('npcIntelligenceSelect').value;d.socialEnabled=!!el('npcSocialEnabledCheck').checked;d.casualTalkEnabled=!!el('npcCasualTalkCheck').checked;d.treasureValue=Math.max(0,Math.round(Number(el('npcTreasureValueInput').value)||0));d.treasure=cleanText(el('npcTreasureInput').value);d.offerHint=cleanText(el('npcOfferHintInput').value);d.essential=!!el('npcEssentialCheck').checked;const type=String(el('npcClosureSelect').value||'END').toUpperCase(),target=type==='SECTION'?cleanText(d.closure?.target):'',text=d.essential&&type!=='COMBAT'?'':cleanText(el('npcClosureTextInput').value);d.closure={type,text,target};return d;}
  function npcFillEditor(def){const d=normalizeNpcDef(def)||npcTemplateClone('tavern-keeper');appState.npcEditorDraft=deepClone(d);el('npcNameInput').value=d.name;el('npcPhysicalDescriptionInput').value=d.physicalDescription||'';el('npcPortraitInput').value=d.portrait;el('npcAiIllustrationCheck').checked=!!d.aiIllustration;el('npcSkillInput').value=d.skill;el('npcStaminaInput').value=d.stamina;el('npcSanityInput').value=d.sanity;el('npcLuckInput').value=d.luck;el('npcResistanceInput').value=d.resistance;el('npcMaxResistanceInput').value=d.maxResistance;el('npcAlignmentSelect').value=d.alignment;el('npcReactionSelect').value=d.reaction;el('npcIntelligenceSelect').value=d.intelligence;el('npcSocialEnabledCheck').checked=d.socialEnabled;el('npcCasualTalkCheck').checked=d.casualTalkEnabled!==false;el('npcTreasureValueInput').value=d.treasureValue;el('npcTreasureInput').value=d.treasure;el('npcOfferHintInput').value=d.offerHint||'';el('npcEssentialCheck').checked=!!d.essential;el('npcClosureTextInput').value=d.closure.text||'';npcPopulateTemplateSelect();el('npcTemplateSelect').value=d.templateId||'';npcSyncEssentialEditor();npcSyncPortraitEditor();renderNpcApproachEditor();renderNpcDialogueEditor();}
  function openNpcConfig(){const sec=appState.book?.sections?.[appState.sectionId];if(!sec)return;npcFillEditor(sec.npc||npcTemplateClone('tavern-keeper'));el('npcConfigDialog').showModal();}
  function applyNpcTemplateFromEditor(){const id=el('npcTemplateSelect').value;if(!id)return;npcFillEditor(npcTemplateClone(id));el('npcTemplateSelect').value=id;}
  function addNpcDialogueEditor(){const d=appState.npcEditorDraft;if(!d)return;d.dialogues.push(normalizeNpcDialogue({id:npcId(),question:'Nova pergunta',impact:0,response:'',start:true},d.dialogues.length));renderNpcDialogueEditor();}
  function openNpcClosureLink(){const d=appState.npcEditorDraft;if(!d||!d.essential||d.closure?.type!=='SECTION')return;appState.genericLinkCallback=id=>{d.closure.target=id;npcUpdateClosureTargetDisplay();invalidateAdventureGraphAnalysis();};el('sectionSearch').value='';renderSectionList('');el('linkDialog').showModal();setTimeout(()=>el('sectionSearch').focus(),40);}
  function createNpcClosureTarget(){const sec=appState.book?.sections?.[appState.sectionId],d=npcReadEditorIntoDraft();if(!sec||!d||!d.essential||d.closure.type!=='SECTION')return;const previousTarget=cleanText(d.closure.target),target=createSection();d.closure.target=target;sec.npc=normalizeNpcDef(d);sec.dialogue=false;sec.dialogueName='';sec.portrait='';if(previousTarget&&previousTarget!==target&&!referencedElsewhere(previousTarget)&&isDisposableSection(previousTarget))deleteSection(previousTarget);appState.npcRuntime=null;invalidateAdventureGraphAnalysis();el('npcConfigDialog').close();renderEditor();editorNavigateTo(target);}
  function saveNpcConfig(){const sec=appState.book?.sections?.[appState.sectionId],d=npcReadEditorIntoDraft();if(!sec||!d)return;if(d.essential&&d.closure.type==='SECTION'&&!d.closure.target){toast('Vincule ou crie a seção de destino do NPC essencial.');return;}const previousTarget=cleanText(sectionNpc(sec)?.closure?.target);sec.npc=normalizeNpcDef(d);sec.dialogue=false;sec.dialogueName='';sec.portrait='';const nextTarget=cleanText(sec.npc?.closure?.target);if(previousTarget&&previousTarget!==nextTarget&&!referencedElsewhere(previousTarget)&&isDisposableSection(previousTarget))deleteSection(previousTarget);appState.npcRuntime=null;invalidateAdventureGraphAnalysis();el('npcConfigDialog').close();renderEditor();renderAll();toast(`NPC: ${sec.npc.name}`);}
  function removeNpcConfig(){const sec=appState.book?.sections?.[appState.sectionId];if(!sec)return;const previousTarget=cleanText(sectionNpc(sec)?.closure?.target);sec.npc=null;sec.dialogue=false;sec.dialogueName='';sec.portrait='';if(previousTarget&&!referencedElsewhere(previousTarget)&&isDisposableSection(previousTarget))deleteSection(previousTarget);appState.npcRuntime=null;invalidateAdventureGraphAnalysis();el('npcConfigDialog').close();renderEditor();renderAll();toast('NPC removido.');}
  function parseSection(id,block){
    const documentPack=extractDocumentBlocks(block);block=documentPack.cleaned;const temporal=extractTempoBlocks(block),tempos=temporal.blocks;block=temporal.cleaned;
    const states=[];for(const line of block.split(/\r?\n/)){const t=line.trim(),remove=t.match(/^!\{Estado:([^}]+)\}$/);if(remove){const name=cleanStateName(remove[1]);if(name)states.push({name,hidden:false,clear:false,remove:true});continue;}const st=t.match(/^(!)?\{ESTADO(?::([^}]*))?\}$/i);if(st){const name=cleanStateName(st[2]||'');states.push(name?{name,hidden:!!st[1],clear:false,remove:false}:{name:'',hidden:false,clear:true,remove:false});}}
    let image='';const im=block.match(/^\{IMAGEM:(.*?)\}\s*$/mi);if(im)image=normalizeMediaUrl(im[1]);
    let portrait='';const rp=block.match(/^\{RETRATO:(.*?)\}\s*$/mi);if(rp)portrait=normalizeMediaUrl(rp[1]);
    let npc=parseNpcDef(block);if(!npc)npc=legacyNpcFromBlock(block);if(npc)portrait=npc.portrait||portrait;
    let music='';const sm=block.match(/^\{MUSICA:(.*?)\}\s*$/mi);if(sm&&sm[1].trim())music=normalizeMusicUrl(sm[1]);
    let climate='';const cl=block.match(/^\{CLIMA:(.*?)\}\s*$/mi);if(cl&&cl[1].trim())climate=normalizeClimate(cl[1]);
    let lighting=null;const li=block.match(/^\{ILUMINACAO:\s*(\d{1,3})\s*\}\s*$/mi);if(li)lighting=normalizeSectionLighting(li[1]);
    let terrain='',terrainDescription='';const te=block.match(/^\{TERRENO:(.*?)\}\s*$/mi);if(te&&te[1].trim()){const spec=parseTerrainSpec(te[1]);terrain=spec.terrain;terrainDescription=spec.description;}
    const ending=/^\{FINAL\}\s*$/mi.test(block);
    let dialogue=!!npc,dialogueName=npc?.name||'';const lg=block.match(/^\{LEGENDA:(.*?)\}\s*$/mi);if(!dialogueName&&lg)dialogueName=String(lg[1]||'').trim();
    const encounter=parseEncounterDef(block);
    let treasure=null;const tr=block.match(/\{TESOURO(?:\s+([^}]+))?\}/i);if(tr){const raw=tr[1];treasure=raw?{mode:'fixed',reward:parseQtyItem(raw.trim())}:{mode:'random'};}
    const trades=[];const tradeRe=/^\{Troca:([^|}]+)\|([^}]+)\}\s*$/gmi;let tx;while((tx=tradeRe.exec(block)))trades.push({from:parseQtyItem(tx[1]),to:parseQtyItem(tx[2])});
    const commerceName=parseCommerceName(block),commerceBudget=parseCommerceBudget(block),commerceRequireZero=parseCommerceRequireZero(block),commerce=[];for(const rawLine of block.split(/\r?\n/)){const entry=parseCommerceLine(rawLine);if(entry)commerce.push(entry);}
    const knowledges=[],books=[];for(const rawLine of block.split(/\r?\n/)){const k=parseKnowledgeMarker(rawLine);if(k){knowledges.push(k);continue;}const b=parseBookGrantMarker(rawLine);if(b)books.push(b);}
    const mods=[...(documentPack.documents||[])];
    for(const rawLine of block.split(/\r?\n/)){const t=rawLine.trim(),water=t.match(/^\{!\+\s*(.+)\}$/s);if(water){const qi=parseItemModSpec('!'+water[1].trim());if(qi.item)mods.push({kind:'item',op:'+',qty:qi.qty,item:qi.item});continue;}const m=t.match(/^\{([+-])\s*(.+)\}$/s);if(!m)continue;const payload=m[2].trim(),stat=payload.match(/^(\d+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)$/i);if(stat){mods.push({kind:'stat',op:m[1],amount:+stat[1],stat:normalizeStatToken(stat[2])});continue;}const qi=parseItemModSpec(payload);if(qi.item)mods.push({kind:'item',op:m[1],qty:qi.qty,item:qi.item});}
    const choices=[],textLines=[];
    for(const line of block.split(/\r?\n/)){const t=line.trim();if(parseKnowledgeMarker(t)||parseBookGrantMarker(t)||/^\{FINAL\}$/i.test(t)||/^!?\{ESTADO(?::[^}]*)?\}$/i.test(t)||/^\{IMAGEM:.*\}$/i.test(t)||/^\{RETRATO:.*\}$/i.test(t)||/^\{MUSICA:.*\}$/i.test(t)||/^\{CLIMA:.*\}$/i.test(t)||/^\{ILUMINACAO:.*\}$/i.test(t)||/^\{TERRENO:.*\}$/i.test(t)||/^\{DIALOGO\}$/i.test(t)||/^\{NPC_DEF:.*\}$/i.test(t)||/^\{COMBATE_DEF:.*\}$/i.test(t)||/^\{!?[+-].*\}$/i.test(t)||/^\{TESOURO(?:\s+[^}]+)?\}(?:\{.*\})?$/i.test(t)||/^\{Troca:.+?\|.+?\}$/i.test(t)||/^\{COMERCIO:/i.test(t)||/^\{COMERCIO_NOME:/i.test(t)||/^\{COMERCIO_ORCAMENTO:/i.test(t)||/^\{COMERCIO_EXIGIR_ZERO:/i.test(t)||/^\{LEGENDA:.*\}$/i.test(t))continue;const c=t.match(/^\[(.+?):(.+)\]$/);if(c){choices.push(parseChoice(c[1].trim(),c[2].trim()));continue;}textLines.push(line);}
    const text=textLines.join('\n').replace(/^\s*\{FINAL\}\s*$/gmi,'').replace(/^\s*!?\{ESTADO(?::[^}]*)?\}\s*$/gmi,'').replace(/\{IMAGEM:[^}]+\}/gi,'').replace(/\{RETRATO:[^}]+\}/gi,'').replace(/\{MUSICA:[^}]+\}/gi,'').replace(/\{CLIMA:[^}]+\}/gi,'').replace(/\{ILUMINACAO:[^}]+\}/gi,'').replace(/\{TERRENO:[^}]+\}/gi,'').replace(/^\s*\{DIALOGO\}\s*$/gmi,'').replace(/^\s*\{LEGENDA:[^}]*\}\s*$/gmi,'').replace(/^\s*\{NPC_DEF:[^}]+\}\s*$/gmi,'').replace(/^\s*\{COMBATE_DEF:[^}]+\}\s*$/gmi,'').replace(/\{!?[+-]\s*(?:\d+\s+(?:APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)|[^}]+)\}/gi,'').replace(/\{TESOURO(?:\s+[^}]+)?\}/gi,'').replace(/^\{Troca:.+?\|.+?\}\s*$/gmi,'').replace(/^\s*\{COMERCIO:.*\}\s*$/gmi,'').replace(/^\s*\{COMERCIO_NOME:.*\}\s*$/gmi,'').replace(/^\s*\{COMERCIO_ORCAMENTO:.*\}\s*$/gmi,'').replace(/^\s*\{COMERCIO_EXIGIR_ZERO:.*\}\s*$/gmi,'').replace(/\n{3,}/g,'\n\n').trim();
    return {id,image,portrait,music,climate,lighting,terrain,terrainDescription,dialogue,dialogueName,npc,ending,encounter,mods,knowledges,books,treasure,trades,commerceName,commerceBudget,commerceRequireZero,commerce,tempos,states,text,choices};
  }

  function parseRequirementSpec(raw=''){let t=String(raw||'').trim(),consume=false,activate=false,compare='gte';while(/[!^]$/.test(t)){if(t.endsWith('!'))consume=true;if(t.endsWith('^'))activate=true;t=t.slice(0,-1).trim();}if(/^<=/.test(t)){compare='lte';t=t.slice(2).trim();}else if(/^=/.test(t)){compare='eq';t=t.slice(1).trim();}const qm=t.match(/^(\d+)\s+(.+)$/);if(!qm)return null;const qty=Math.max(0,parseInt(qm[1])||0),item=qm[2].trim();return item?{item,qty,compare,consume,activate}:null;}
  function serializeRequirementSpec(r){if(!r?.item)return '';const cmp=r.compare==='eq'?'=':r.compare==='lte'?'<=':'',flags=`${r.consume?'!':''}${r.activate?'^':''}`,qty=Math.max(0,parseInt(r.qty)||0);return `${cmp}${qty} ${r.item}${flags}`;}
  function parseRequirementsMarker(working,c){const m=working.match(/\{REQUER_ITENS:(TODOS|QUALQUER)\|([^}]*)\}/i);if(!m)return working;c.requirementMode=m[1].toUpperCase()==='QUALQUER'?'ANY':'ALL';c.requirements=m[2].split('|').map(parseRequirementSpec).filter(Boolean);return working.replace(m[0],'').trim();}
  function serializeRequirementsMarker(c){const list=Array.isArray(c.requirements)?c.requirements.filter(r=>r?.item):[];return list.length?`{REQUER_ITENS:${c.requirementMode==='ANY'?'QUALQUER':'TODOS'}|${list.map(serializeRequirementSpec).join('|')}}`:'';}
  function requirementQuantityAvailable(item=''){const raw=String(item||'').trim(),sm=raw.match(/^ESTADO\s*:\s*(.+)$/i),cm=raw.match(/^CLASSE\s*:\s*(.+)$/i);if(sm)return hasState(cleanStateName(sm[1]))?1:0;if(cm)return appState.player?.classKey===String(cm[1]).trim().toUpperCase()?1:0;return quantityAvailable(raw);}
  function requirementEditorKind(item=''){const raw=String(item||'').trim();if(/^ESTADO\s*:/i.test(raw))return 'STATE';if(/^CLASSE\s*:/i.test(raw))return 'CLASS';return 'ITEM';}
  function choiceFailPresentation(c){return c?.conditionFail==='HIDE'?'HIDE':c?.conditionFail==='BLOCK'?'BLOCK':'';}
  function requirementQuantityMet(r){const have=requirementQuantityAvailable(r.item),q=Math.max(0,parseInt(r.qty)||0);return r.compare==='eq'?have===q:r.compare==='lte'?have<=q:have>=q;}
  function choiceRequirementsMet(c){const list=Array.isArray(c?.requirements)?c.requirements:[];if(!list.length)return true;const vals=list.map(requirementQuantityMet);return c.requirementMode==='ANY'?vals.some(Boolean):vals.every(Boolean);}
  function effectList(raw=''){return String(raw||'').split(';').map(x=>x.trim()).filter(Boolean);}
  async function applyCompactEffect(effect,{source='💱'}={}){let t=String(effect||'').trim();if(!t)return false;if(/^ESTADO_OCULTO:/i.test(t))return applySimpleMarkerEffect(`!{ESTADO:${t.replace(/^ESTADO_OCULTO:/i,'').trim()}}`,{source});if(/^ESTADO:/i.test(t))return applySimpleMarkerEffect(`{ESTADO:${t.replace(/^ESTADO:/i,'').trim()}}`,{source});if(/^SEM_ESTADO:/i.test(t))return applySimpleMarkerEffect(`!{Estado:${t.replace(/^SEM_ESTADO:/i,'').trim()}}`,{source});let m=t.match(/^([+-])\s*(.+)$/);if(m){const payload=m[2].trim(),stat=payload.match(/^([\d.]+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)$/i);if(stat)return applySimpleMarkerEffect(`{${m[1]}${stat[1]} ${stat[2]}}`,{source});const qi=parseQtyItem(payload);if(qi.item){if(m[1]==='+')addQuantity(qi.item,qi.qty,{silent:true,force:true,narrativeDiscovery:true,narrativeSource:source});else removeQuantity(qi.item,qi.qty);queueFx(m[1]==='+'?'luckWin':'luckLoss',source,`${m[1]}${qi.qty} ${itemMeta(qi.item).name}`,{quiet:m[1]==='+'});return true;}}return applySimpleMarkerEffect(t,{source});}
  function ensureNextCombatEffects(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.nextCombatEffects))p.nextCombatEffects=[];return p.nextCombatEffects;}
  function ensureNextTestEffects(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.nextTestEffects))p.nextTestEffects=[];return p.nextTestEffects;}
  function ensureTimedChoiceEffects(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.timedChoiceEffects))p.timedChoiceEffects=[];return p.timedChoiceEffects;}
  function compactEffectReversible(effect,{source='💱'}={}){const p=appState.player,t=String(effect||'').trim();if(!p||!t)return null;let m=t.match(/^([+-])\s*([\d.]+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)$/i);if(m){const key=statKeyFromToken(normalizeStatToken(m[3])),before=Number(p[key])||0,delta=(m[1]==='+'?1:-1)*Number(m[2]);changePlayerStat(key,delta,before);const actual=(Number(p[key])||0)-before;if(actual)queueFx(actual>0?'luckWin':'luckLoss',source,`${actual>0?'+':''}${actual} ${playerStatLabel(m[3])}`);return actual?{kind:'stat',key,delta:actual}:null;}if(/^ESTADO:/i.test(t)){const name=cleanStateName(t.replace(/^ESTADO:/i,'')),had=hasState(name);if(name)addState(name);return name&&!had?{kind:'stateAdded',name}:null;}if(/^SEM_ESTADO:/i.test(t)){const name=cleanStateName(t.replace(/^SEM_ESTADO:/i,'')),prior=playerStates().find(x=>stateKey(x.name)===stateKey(name));if(name)removeState(name);return prior?{kind:'stateRemoved',entry:deepClone(prior)}:null;}m=t.match(/^([+-])\s*(.+)$/);if(m){const qi=parseQtyItem(m[2].trim());if(qi.item){const before=quantityAvailable(qi.item);if(m[1]==='+')addQuantity(qi.item,qi.qty,{silent:true,force:true});else removeQuantity(qi.item,qi.qty);const after=quantityAvailable(qi.item),delta=after-before;if(delta)queueFx(delta>0?'luckWin':'luckLoss',source,`${delta>0?'+':''}${delta} ${itemMeta(qi.item).name}`);return delta?{kind:'item',item:qi.item,delta}:null;}}applyCompactEffect(t,{source});return null;}
