  async function activateConditionalItem(raw,c=null){const meta=itemMeta(raw);if(!meta.name)return false;const cat=categoryKey(meta.category);if(cat==='feitiço'){const target=c||appState.combat||null;if(target){await applyMagicEffect(meta.name,target,meta,{magicTarget:appState.player?.magic});return true;}if(meta.itemEffect){if(await applySimpleMarkerEffect(meta.itemEffect,{source:'FEITIÇO'}))return true;}return false;}if(cat==='poções'){const effect=String(meta.itemEffect||'').trim();if(effect){const spellRaw=potionSpellGrant(effect);if(spellRaw)await grantTemporarySpell(spellRaw);else await applySimpleMarkerEffect(effect,{source:meta.name.toUpperCase()});return true;}}if(isBookMeta(meta)&&meta.bookEffect){await applyBookEffect(meta.bookEffect);return true;}if(meta.itemEffect)return applySimpleMarkerEffect(meta.itemEffect,{source:meta.name.toUpperCase()});return false;}
