    const build=()=>{if(!appState.musicPlaying||appState.musicMode!=='ambient'||appState.ambientMaster)return;const master=ac.createGain();master.gain.value=AMBIENT_VOLUME;master.connect(ac.destination);appState.ambientMaster=master;appState.ambientNodes.push(master);const bed=ac.createGain();bed.gain.value=.20;bed.connect(master);appState.ambientNodes.push(bed);[55,82.41,110].forEach((f,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=i===1?'triangle':'sine';o.frequency.value=f;g.gain.value=i===0?.24:.11;o.connect(g).connect(bed);o.start();appState.ambientNodes.push(o,g);});const notes=[146.83,164.81,196,220,246.94,220,196,164.81,146.83,130.81,146.83,196];let step=0;const pulse=()=>{if(!appState.musicPlaying||!appState.musicFallback||appState.musicMode!=='ambient')return;const now=ac.currentTime,f=notes[step++%notes.length];const o=ac.createOscillator(),g=ac.createGain(),filter=ac.createBiquadFilter();o.type='triangle';o.frequency.value=f;filter.type='lowpass';filter.frequency.value=1250;g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.28,now+.08);g.gain.exponentialRampToValueAtTime(.0001,now+1.75);o.connect(filter).connect(g).connect(master);o.start(now);o.stop(now+1.8);};pulse();appState.ambientTimer=setInterval(pulse,1350);applyMusicVolume(1);};
