  async function setReadingAssistEnabled(value,{restorePrevious=true,announce=true}={}){const next=!!value;if(next===!!appState.readingAssistEnabled){applyReadingAssistConstraints();syncReadingAssistSettings();syncVoiceUi();applyMusicVolume(1);return true;}if(next&&!voiceSpeechAvailable()){if(announce)toast('Este navegador não oferece narração por voz.');syncReadingAssistSettings();return false;}if(next){if(!readReadingAssistPrevious())writeReadingAssistPrevious({combatMode:appState.combatMode,hideDiceRolls:!!appState.hideDiceRolls});appState.readingAssistEnabled=true;appState.voiceEnabled=true;appState.readingAssistReady=!!(appState.adventureStarted&&!appState.adventureCoverActive&&appState.book&&appState.player);writeReadingAssistSetting(true);applyReadingAssistConstraints();appState.voiceLastNarratedStoryKey='';appState.voiceLastNarratedPromptKey='';appState.voiceContextKey='';syncReadingAssistSettings();syncVoiceUi();applyMusicVolume(1);ensureReadingMicrophonePermission();if(appState.readingAssistReady&&!appState.editor)scheduleVoiceCycle(true,180);if(announce)toast('Leitura e comandos por voz ativados.');return true;}appState.readingAssistEnabled=false;appState.voiceEnabled=false;appState.readingAssistReady=false;writeReadingAssistSetting(false);cancelVoiceIO();const previous=readReadingAssistPrevious();writeReadingAssistPrevious(null);if(restorePrevious&&previous){appState.hideDiceRolls=!!previous.hideDiceRolls;writeHideDiceRollsSetting(appState.hideDiceRolls);if(!combatModeChangeLocked()){appState.combatMode=previous.combatMode==='quick'?'quick':previous.combatMode==='strategic'?'strategic':'action';writeCombatModeSetting(appState.combatMode);}}syncReadingAssistSettings();syncVoiceUi();applyMusicVolume(1);renderAll();if(announce)toast('Leitura e comandos por voz desativados.');return true;}
