  function tone(freq,dur=.08,when=0,type='triangle',gain=.035){if(appState.soundMuted)return;const ac=ensureAudio();if(!ac)return;const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime+when);g.gain.setValueAtTime(Math.max(.0001,gain*1.65),ac.currentTime+when);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+when+dur);o.connect(g).connect(ac.destination);o.start(ac.currentTime+when);o.stop(ac.currentTime+when+dur+.02);}
