  function queueFx(type,title,detail='',opts={}){if(type==='death'&&appState.combat?.sanityIllusion)return;if(type==='death'){if(appState.deathPresentationPending||appState.deathFlowActive||appState.fxQueue.some(item=>item.type==='death'))return;appState.deathPresentationPending=true;}appState.fxQueue.push({type,title,detail,criticalSound:opts?.criticalSound||'',quiet:!!opts?.quiet});runFxQueue();}
