  function inventoryEntry(key){return inventoryCounts().find(x=>x.meta.key===key)||null;}
  function categoryKey(v){const k=canonicalCategory(v).toLocaleLowerCase('pt-BR');if(k==='armas')return 'arma';if(k==='armaduras'||k==='defesas')return 'armadura';if(k==='magia'||k==='magias'||k==='feitiço'||k==='feitiços')return 'feitiço';if(k==='poção'||k==='pocao'||k==='pocoes')return 'poções';if(k==='documento'||k==='documentos')return 'documento';return k;}
  function displayCategoryName(category){const key=categoryKey(category);return key==='armadura'?'Defesas':key==='livro'?'Livros':key==='feitiço'?'Feitiços':key==='documento'?'Documentos':key==='poções'?'Poções':key==='materiais'?'Materiais':(category||'Itens');}
  function craftName(value=''){const name=isProvisionName(value)?'Provisão':itemMeta(value).name;return String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();}
