  function normalizeCustomRecipe(recipe={}){return {a:itemMeta(recipe.a||'').raw||String(recipe.a||'').trim(),b:itemMeta(recipe.b||'').raw||String(recipe.b||'').trim(),result:itemMeta(recipe.result||'').raw||String(recipe.result||'').trim(),hours:Math.max(.5,Number(recipe.hours)||1)};}
  function ensureCustomRecipes(book=appState.book){if(!book)return [];if(!Array.isArray(book.editorCustomRecipes))book.editorCustomRecipes=[];book.editorCustomRecipes=book.editorCustomRecipes.map(normalizeCustomRecipe).filter(r=>r.a&&r.b&&r.result);return book.editorCustomRecipes;}
  function allCraftRecipes(book=appState.book){const map=new Map();for(const r of CRAFT_RECIPES)map.set(craftPairKey(r.a,r.b),r);for(const r of ensureCustomRecipes(book))map.set(craftPairKey(r.a,r.b),r);return [...map.values()];}
  function craftRecipeFor(a,b){return allCraftRecipes().find(r=>craftPairKey(r.a,r.b)===craftPairKey(a,b))||null;}
  function craftIngredientAvailable(name,firstName=''){const need=craftName(name),first=craftName(firstName);if(need==='provisao')return (appState.player?.provisions||0)>0;if(need===first){const entry=inventoryCounts().find(e=>craftName(e.meta.raw)===need);return (entry?.count||0)>=2;}return inventoryCounts().some(e=>craftName(e.meta.raw)===need);}
  function craftRecipesForIngredient(value){const name=craftName(value);return allCraftRecipes().filter(r=>craftName(r.a)===name||craftName(r.b)===name);}
  function craftingAllowed(){return !!appState.player&&!appState.editor&&!adventureEnded()&&!combatInProgress()&&!ensureSanityRuntime().activeEpisode;}
  function craftAvailableRecipesForIngredient(value){if(!craftingAllowed())return [];const name=craftName(value);return craftRecipesForIngredient(value).filter(r=>{const other=craftName(r.a)===name?r.b:r.a;return craftIngredientAvailable(other,value);});}
  function craftFirstEntry(){return appState.craftingIngredientKey?inventoryEntry(appState.craftingIngredientKey):null;}
  function craftHoursLabel(hours){const n=Number(hours)||.5;return `${String(n).replace('.',',')} ${n===1?'hora':'horas'}`;}
  function cancelCrafting({render=true}={}){appState.craftingIngredientKey=null;appState.craftingBusy=false;if(render&&inventoryOpen())renderInventory();}
  function startCrafting(key){if(!craftingAllowed())return;const entry=inventoryEntry(key);if(!entry||!craftAvailableRecipesForIngredient(entry.meta.raw).length)return;appState.craftingIngredientKey=key;appState.inventorySelection=key;renderInventory();}
  async function completeCraft(recipe,firstRaw,secondRaw){if(!recipe||appState.craftingBusy||!craftingAllowed())return;const same=craftName(firstRaw)===craftName(secondRaw),needFirst=same?2:1;if(quantityAvailable(firstRaw)<needFirst||(!same&&quantityAvailable(secondRaw)<1)){cancelCrafting();toast('Os ingredientes já não estão disponíveis.');return;}appState.craftingBusy=true;const before=captureState();pushHistory(before);if(same)removeQuantity(firstRaw,2);else{removeQuantity(firstRaw,1);removeQuantity(secondRaw,1);}if(!hasActiveNamedItem('Tocha')&&!hasActiveNamedItem('Tocha Improvisada'))appState.player.torchTurns=0;if(!activeArmor())appState.player.armorGuard=0;forceAddOne(recipe.result);journalRecordItem(recipe.result,1,'add','Produzi');markRuntimeChanged();const resultMeta=itemMeta(recipe.result),hours=Math.max(.5,Number(recipe.hours)||.5),turns=Math.max(1,Math.round(hours*2));cancelCrafting({render:false});closeInventoryIfOpen();await advanceAdventureTurns(turns,{animate:false,countAwake:true,allowAutoSleep:false});await waitTemporalQueue();renderAll();if(appState.player?.stamina>0&&!adventureEnded())await showRewardMoment({kind:'craft',title:'ITEM PRODUZIDO',headline:resultMeta.name.toUpperCase(),detail:`${itemMeta(firstRaw).name} + ${isProvisionName(secondRaw)?'Provisão':itemMeta(secondRaw).name} · ${craftHoursLabel(hours)}.`,icon:'🔨'});scheduleVoiceCycle(true,180);}
  function promptCraftCombination(secondRaw){const first=craftFirstEntry();if(!first)return;const recipe=craftRecipeFor(first.meta.raw,secondRaw);if(!recipe)return;const firstName=first.meta.name,secondName=isProvisionName(secondRaw)?'Provisão':itemMeta(secondRaw).name,result=itemMeta(recipe.result).name;confirmSpecial('Produzir item',`${firstName} + ${secondName} serão consumidos para produzir ${result}. Tempo necessário: ${craftHoursLabel(recipe.hours)}. Deseja produzir?`,()=>completeCraft(recipe,first.meta.raw,secondRaw),'Produzir');}
  function selectCraftProvision(){const first=craftFirstEntry();if(!first||!(appState.player?.provisions>0))return;const recipe=craftRecipeFor(first.meta.raw,'Provisão');if(recipe)promptCraftCombination('Provisão');}
  function hasRequirementItem(item){if(hasItem(item))return true;return craftName(item)==='corda'&&hasItem('Gancho de Escalada');}
  function activeEntriesByCategory(category){const want=categoryKey(category),active=ensureActiveItems();return inventoryCounts().filter(e=>categoryKey(e.meta.category)===want&&active[e.meta.key]);}
  function activeEntryByCategory(category){return activeEntriesByCategory(category)[0]||null;}
  function readyRowForMeta(meta){const cat=categoryKey(meta?.category);return cat==='arma'?'weapon':cat==='feitiço'?'spell':'item';}
  function activeReadyEntries(){const byKey=new Map(inventoryCounts().map(e=>[e.meta.key,e])),active=ensureActiveItems();return ensureActiveOrder().map(key=>byKey.get(key)).filter(e=>e&&active[e.meta.key]);}
  function activeOtherItems(){return activeReadyEntries().filter(e=>readyRowForMeta(e.meta)==='item');}
  function activeWeapons(){return activeReadyEntries().filter(e=>readyRowForMeta(e.meta)==='weapon');}
  function activeWeapon(){const entries=activeWeapons();return entries.find(e=>!e.meta.projectileDamage)||entries[0]||null;}
  function activeProjectileWeapon(){return activeWeapons().find(e=>!!e.meta.projectileDamage)||null;}
  function weaponSaberBonus(meta=activeWeapon()?.meta){if(!meta?.name)return 0;return Math.max(0,knowledgeValue(meta.name)||0);}
  function activeMagics(){return activeReadyEntries().filter(e=>readyRowForMeta(e.meta)==='spell');}
  function activeMagic(){return activeMagics()[0]||null;}
  function activeArmor(){return activeOtherItems().filter(e=>categoryKey(e.meta.category)==='armadura').at(-1)||null;}
  const ARMOR_PROFILES={
    'broquel':{guard:1,penalty:0},'cota de malha':{guard:2,penalty:0},'escudo leve':{guard:3,penalty:0},'escudo pesado':{guard:4,penalty:1},'escudo lendário':{guard:5,penalty:0},'armadura leve':{guard:6,penalty:1},'armadura pesada':{guard:7,penalty:1},'armadura lendária':{guard:8,penalty:0},'escudo improvisado':{guard:2,penalty:0},'couraça improvisada':{guard:4,penalty:1}
  };
  function armorProfile(metaOrName){const name=(typeof metaOrName==='string'?itemMeta(metaOrName).name:metaOrName?.name||'').toLocaleLowerCase('pt-BR');return ARMOR_PROFILES[name]||{guard:1,penalty:0};}
  function armorGuard(){const a=activeArmor();if(!a)return 0;const p=appState.player;if(!p)return 0;const max=armorProfile(a.meta).guard;if(!p.armorGuard||p.armorGuard<1)p.armorGuard=max;return Math.max(0,Math.min(max,p.armorGuard));}
  function armorSkillPenalty(){const a=activeArmor();return a?armorProfile(a.meta).penalty||0:0;}
  function breakActiveArmor(entry){if(!entry)return;const meta=entry.meta;removeOneItem(meta.raw,{journal:false});recordJournal(`${meta.name} se quebrou.`,{kind:'item'});delete ensureActiveItems()[meta.key];if(appState.player)appState.player.armorGuard=0;toast(`${meta.name} se quebrou.`);}
  function applyArmorProtection(loss){const entry=activeArmor();if(!entry)return loss;const before=armorGuard();if(before<=0)return loss;appState.player.armorGuard=before-1;const reduced=Math.max(0,loss-1);queueFx('luckWin','ARMADURA',`-1 VIDA`);if(appState.player.armorGuard<=0)breakActiveArmor(entry);return reduced;}
  const SELF_MAGIC_NAMES=new Set(['cura','benção','maestria','abrir caminho','voltar no tempo','invisibilidade','aura','buraco mágico','premonição','mãos múltiplas','soltar-se','contra-feitiço']);
  const MAGIC_COSTS={'benção':1,'bola de fogo':2,'cura':2,'maestria':2,'fraqueza':2,'medo':2,'fortaleza':2,'voar':2,'soltar-se':2,'abrir caminho':3,'invisibilidade':3,'ilusão':3,'sono':3,'aura':3,'premonição':3,'mãos múltiplas':4,'cura total':4,'buraco mágico':4,'voltar no tempo':4,'conjurar goblin':3,'reflexo aéreo':3,'camuflagem mística':3,'desconcertar':3,'grande benção':3,'telecinese':3,'aceleração':4,'pele fluida':3,'armadura de espinhos':3,'dreno de vida':4,'veneno mágico':3,'contra-feitiço':4};
  function magicCost(spellOrMeta){const name=(typeof spellOrMeta==='string'?spellOrMeta:spellOrMeta?.name||'').toLocaleLowerCase('pt-BR').trim();return MAGIC_COSTS[name]||2;}
  function ensureTemporarySpells(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.temporarySpells))p.temporarySpells=[];return p.temporarySpells;}
  function temporarySpellTurns(key){const matches=ensureTemporarySpells().filter(x=>x.key===key);return matches.length?Math.max(...matches.map(x=>Math.max(0,Number(x.remaining)||0))):0;}
  function consumeTemporarySpellTracking(key){const list=ensureTemporarySpells(),i=list.findIndex(x=>x.key===key);if(i>=0){list.splice(i,1);return true;}return false;}
  function removeLastItemByKey(key){const items=appState.player?.items||[];let i=-1;for(let n=items.length-1;n>=0;n--)if(itemMeta(items[n]).key===key){i=n;break;}if(i<0)return false;const meta=itemMeta(items[i]);items.splice(i,1);if(!items.some(x=>itemMeta(x).key===key)){delete ensureActiveItems()[key];if(appState.inventorySelection===key)appState.inventorySelection=null;}return true;}
  function consumeSpellItem(meta){if(!meta)return false;const temporary=consumeTemporarySpellTracking(meta.key);return temporary?removeLastItemByKey(meta.key):removeOneItem(meta.raw,{journal:false});}
  async function temporarySpellDuration(){if(knowledgeValue('Treino Mágico')<=0)return 3;const roll=await dramaticRoll({title:'Duração do Feitiço',lead:'Seu Treino Mágico prolonga o Feitiço. Role 1d6: ele ficará disponível por 1d6 + 3 turnos.',diceCount:1,evaluate:r=>({total:r[0]+3,equation:`${r[0]} + 3 = ${r[0]+3}`,headline:`${r[0]+3} TURNOS`,detail:'Até o fim desse prazo, o Feitiço pode ser lançado normalmente.',turns:r[0]+3})});return roll?.outcome?.turns||6;}
  async function grantTemporarySpell(raw){const meta=itemMeta(raw);if(categoryKey(meta.category)!=='feitiço')return false;const turns=await temporarySpellDuration();addQuantity(meta.raw,1,{force:true,silent:true});ensureTemporarySpells().push({key:meta.key,raw:meta.raw,remaining:turns});activateItemMeta(meta);await showRewardMoment({kind:'magic',title:'FEITIÇO ENGARRAFADO',headline:meta.name.toUpperCase(),detail:`O Feitiço fica disponível por ${turns} turno${turns===1?'':'s'} e desaparece se permanecer sem uso.`,icon:'🧪'});return true;}
  function tickTemporarySpells(){const list=ensureTemporarySpells();if(!list.length)return;const keep=[];for(const fx of list){fx.remaining=Math.max(0,(Number(fx.remaining)||1)-1);if(fx.remaining<=0){removeLastItemByKey(fx.key);toast(`${itemMeta(fx.raw).name} desapareceu antes de ser lançado.`);}else keep.push(fx);}appState.player.temporarySpells=keep;}
  function tickMultiHands(){const p=appState.player;if(!p||(Number(p.multiHandsTurns)||0)<=0)return;p.multiHandsTurns=Math.max(0,(Number(p.multiHandsTurns)||0)-1);if(p.multiHandsTurns===0){for(const rec of ensureLingeringSpells())if(lingeringMagicName(rec.name||itemMeta(rec.raw).name)==='mãos múltiplas')deactivateActiveKey(rec.key);normalizeActiveLoadout();toast('Mãos Múltiplas terminou. Seu limite voltou a 2 itens ativos.');}}
  const LINGERING_MAGIC_NAMES=new Set(['maestria','fraqueza','ilusão','sono','aura','mãos múltiplas']);
  function lingeringMagicName(metaOrName){return (typeof metaOrName==='string'?metaOrName:metaOrName?.name||'').toLocaleLowerCase('pt-BR').trim();}
  function isLingeringMagic(metaOrName){const name=lingeringMagicName(metaOrName);return LINGERING_MAGIC_NAMES.has(name)||/^conjurar\s+/.test(name);}
  function ensureLingeringSpells(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.lingeringSpells))p.lingeringSpells=[];return p.lingeringSpells;}
  function lingeringSpellRecord(key){return ensureLingeringSpells().find(x=>x.key===key)||null;}
  function lingeringSpellEffectActive(rec){
    if(!rec||!appState.player)return false;const name=lingeringMagicName(rec.name||itemMeta(rec.raw).name),p=appState.player,c=appState.combat;
    if(name==='aura')return (Number(p.auraTurns)||0)>0;
    if(name==='mãos múltiplas')return (Number(p.multiHandsTurns)||0)>0;
    if(name==='maestria')return (p.skillModifiers||[]).some(m=>m.source==='maestria'&&(Number(m.remaining)||0)>0);
    if(name==='fraqueza')return !!(c&&!c.won&&(Number(c.weaknessTurns)||0)>0);
    if(name==='ilusão')return !!(c&&!c.won&&(Number(c.illusionTurns)||0)>0);
    if(name==='sono')return !!(c&&!c.won&&(Number(c.sleepTurns)||0)>0);
    if(/^conjurar\s+/.test(name)){
      if(!c||c.won)return false;const spec=parseSummonSpell(itemMeta(rec.raw)),summonName=(spec?.name||name.replace(/^conjurar\s+/,'')).toLocaleLowerCase('pt-BR');
      if(combatSummons(c).some(x=>String(x.name||'').toLocaleLowerCase('pt-BR')===summonName))return true;
      const mainRemaining=Math.max(0,(Number(c.summonedMainExpiresAtRound)||0)-(Number(c.round)||0));return !!(c.summonedMain&&mainRemaining>0&&String(c.name||'').toLocaleLowerCase('pt-BR')===summonName);
    }
    return false;
  }
  function registerLingeringSpell(meta){if(!meta||!isLingeringMagic(meta))return false;const list=ensureLingeringSpells();if(list.some(x=>x.key===meta.key))return true;const temporary=consumeTemporarySpellTracking(meta.key);list.push({key:meta.key,raw:meta.raw,name:meta.name,temporary});ensureActiveItems()[meta.key]=true;return true;}
  function finishLingeringSpell(rec){if(!rec)return false;const meta=itemMeta(rec.raw),removed=rec.temporary?removeLastItemByKey(rec.key):removeOneItem(rec.raw);delete ensureActiveItems()[rec.key];if(appState.inventorySelection===rec.key&&!inventoryEntry(rec.key))appState.inventorySelection=null;return removed||!inventoryEntry(rec.key);}
  function cleanupExpiredLingeringSpells(){const p=appState.player,list=ensureLingeringSpells();if(!p||!list.length)return;const keep=[];for(const rec of list){if(lingeringSpellEffectActive(rec)){keep.push(rec);continue;}const name=rec.name||itemMeta(rec.raw).name;finishLingeringSpell(rec);recordJournal(`O efeito de ${name} terminou.`,{kind:'magic',dedupeKey:`spell-end:${rec.key}`});toast(`${name} terminou e desapareceu do Equipamento.`);}p.lingeringSpells=keep;}
  function potionSpellGrant(effect=''){const t=String(effect||'').trim(),m=t.match(/^\{\+\s*(.+\(Feitiço\)(?:\|[^{}]+)?)\}$/i);return m?itemMeta(m[1]).raw:'';}
  async function usePotion(meta){if(!meta||categoryKey(meta.category)!=='poções')return false;const effect=String(meta.itemEffect||'').trim();if(!effect){if(/^poção da cura$/i.test(meta.name)){useCurePotion();return true;}if(/^poção maravilhosa$/i.test(meta.name)){usePowerPotion();return true;}removeOneItem(meta.raw,{journal:false});journalRecordUse(meta.raw);scheduleCustomItemDelayedEffects(meta);toast(`${meta.name} foi consumida.`);renderAll();return true;}removeOneItem(meta.raw,{journal:false});journalRecordUse(meta.raw);scheduleCustomItemDelayedEffects(meta);const spellRaw=potionSpellGrant(effect);if(spellRaw)await grantTemporarySpell(spellRaw);else if(!(await applySimpleMarkerEffect(effect,{source:'POÇÃO'})))toast(`Efeito de ${meta.name} ainda sem executor.`);if(inventoryOpen())renderInventory();renderAll();return true;}
  function expireSummonedMainIfDue(c){if(!c?.summonedMainExpiresAtRound)return false;if((c.round||0)<=c.summonedMainExpiresAtRound)return false;c.stamina=0;c.won=true;c.lootCollected=true;c.pendingLuck=null;c.logs.unshift(`${c.name} desaparece quando a conjuração termina.`);queueFx('luckWin','CONJURAÇÃO ENCERRADA',`${c.name} desapareceu.`);return true;}
  function promoteHostileSummon(c){const hostiles=combatSummons(c).filter(x=>x.side==='enemy');if(!hostiles.length)return false;const h=hostiles[0],others=(c.summons||[]).filter(x=>x!==h);c.name=h.name;c.skill=h.skill;c.stamina=h.stamina;c.maxStamina=h.maxStamina;c.perEnemyStamina=h.maxStamina;c.multiple=1;c.members=[{index:1,skill:h.skill,stamina:h.stamina,maxStamina:h.maxStamina,leader:false,defeated:false,spared:false}];c.baseSkill=h.skill;c.basePerEnemyStamina=h.maxStamina;c.summons=others;c.weaknessTurns=0;c.weaknessDamage=0;c.illusionTurns=0;c.sleepTurns=0;c.poison=false;c.paralyzer=false;c.ambush=false;c.ambushResolved=true;c.summonedMain=true;c.summonedMainExpiresAtRound=(c.round||0)+Math.max(1,h.remaining||1);c.logs.unshift(`${h.name} permanece como oponente principal por até ${h.remaining} turno${h.remaining===1?'':'s'}.`);queueFx('criticalFail','NOVO OPONENTE',`${h.name} continua a luta`,{criticalSound:'failure'});return true;}
