  function knowledgeCriticalModifier(name){const p=ensureKnowledgeState(),key=knowledgeKey(name),fx=(p?.knowledgeCriticalEffects||[]).find(x=>knowledgeKey(x.name)===key&&Number(x.remaining)>0);return Number(fx?.delta)||0;}
