  function epaStateForResult(result){return {3:'Sapo',4:'Bebê',11:'Cabelo Azul',13:'Chifres de Bode',17:'Sexo Alterado'}[result]||'';}
  function captureEpaReversal(result){const p=ensurePlayerStats(),stateName=epaStateForResult(result),stateEntry=stateName?playerStates().find(s=>stateKey(s.name)===stateKey(stateName)):null;return {result,stateName,stateEntry:stateEntry?deepClone(stateEntry):null,age:p.age,gender:p.gender,activeItems:deepClone(ensureActiveItems()),activeOrder:deepClone(p.activeOrder||[]),epaEnvironment:deepClone(p.epaEnvironment||null),createdSerial:Number(p.turnSerial)||0};}
  function recordEpaReversal(result,label,before){const p=ensurePlayerStats(),id=`epa-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`,entry={id,result,label,before,createdSerial:Number(p.turnSerial)||0,active:true};p.epaReversals.push(entry);return entry;}
  function deactivateEpaReversal(id){const p=ensurePlayerStats(),x=(p.epaReversals||[]).find(r=>r.id===id);if(x)x.active=false;}
  function latestEpaReversal(){const p=ensurePlayerStats();return [...(p?.epaReversals||[])].reverse().find(x=>x?.active)||null;}
  function applyEpaReversal(entry){const p=ensurePlayerStats();if(!p||!entry?.active)return false;const b=entry.before||{},result=Number(entry.result);if(b.stateName){if(b.stateEntry)addState(b.stateName,{restoreEntry:b.stateEntry});else removeState(b.stateName,{skipEndEffects:true});}if(result===4)p.age=b.age;if(result===17)p.gender=b.gender;if(result===3||result===4){p.activeItems=deepClone(b.activeItems||{});p.activeOrder=deepClone(b.activeOrder||[]);normalizeActiveLoadout();}if(result===3)setEpaAppearance('SAPO',false);if(result===4)setEpaAppearance('BEBE',false);if(result===11)setEpaAppearance('CABELO_AZUL',false);if(result===13)setEpaAppearance('CHIFRES',false);if(result===17){setEpaAppearance('SEXO',false);refreshEpaPortrait();}if([7,8,12,15,18].includes(result)){p.epaEnvironment=deepClone(b.epaEnvironment||null);applyEpaEnvironmentDisplay();}entry.active=false;return true;}
  function prepareRecentMagicEffect(label='Magia'){const p=ensurePlayerStats();if(!p)return null;const prior=p.lastMagicEffect;p.lastMagicEffect=null;const snapshot=captureState();p.lastMagicEffect=prior;if(snapshot.player)snapshot.player.lastMagicEffect=null;return {label,createdSerial:Number(p.turnSerial)||0,snapshot};}
