  async function castCounterspellEffect({counterCost=0,counterRaw=''}={}){const p=ensurePlayerStats(),recent=recentMagicEffect(),epa=latestEpaReversal(),recentSerial=Number(recent?.createdSerial??-1),epaSerial=Number(epa?.createdSerial??-1);if(recent&&recentSerial>=epaSerial){const currentMagic=p.magic,currentSerial=p.turnSerial,snap=deepClone(recent.snapshot);restoreState(snap);const restored=ensurePlayerStats();restored.magic=Math.max(0,currentMagic);restored.turnSerial=Math.max(Number(restored.turnSerial)||0,currentSerial);restored.lastMagicEffect=null;removeCounterspellFromRestored(counterRaw);await showRewardMoment({kind:'magic',title:'CONTRA-FEITIÇO',headline:'A MAGIA RECENTE FOI DESFEITA',detail:`${recent.label} retorna ao instante imediatamente anterior ao seu efeito.`,icon:'↩️'});renderAll();return true;}if(epa){const ok=applyEpaReversal(epa);if(ok){p.lastMagicEffect=null;await showRewardMoment({kind:'magic',title:'CONTRA-FEITIÇO',headline:'EFEITO MÍSTICO DESFEITO',detail:`${epa.label} perde sustentação e a realidade recupera sua forma.`,icon:'↩️'});renderAll();return true;}}await showRewardMoment({kind:'magic',title:'CONTRA-FEITIÇO',headline:'A REALIDADE ESTÁ ESTÁVEL',detail:'Nenhuma alteração mágica alcançável permanece ativa.',icon:'◌'});return false;}
  function applyEpaEnvironmentDisplay(){const sec=appState.book?.sections?.[appState.sectionId],env=epaEnvironment();const terrain=normalizeTerrain(env?.terrain||sec?.terrain)||'neutro',climate=normalizeClimate(env?.climate||sec?.climate)||'normal';setActiveTerrain(terrain,env?.terrain?'':(sec?.terrainDescription||''));setActiveClimate(climate);}
  function startEpaEnvironment(spec={}){const p=ensurePlayerStats(),remaining=Math.max(1,Number(spec.remaining)||1);p.epaEnvironment={key:spec.key||'EPA',label:spec.label||'Falha Mística ambiental',terrain:spec.terrain||null,climate:spec.climate||null,remaining,skillPenalty:Math.max(0,Number(spec.skillPenalty)||0),enemyPenalty:Math.max(0,Number(spec.enemyPenalty)||0),projectilePenalty:Math.max(0,Number(spec.projectilePenalty)||0),sanityPenalty:Math.max(0,Number(spec.sanityPenalty)||0),rupture:!!spec.rupture,specterSpawned:false,reversalId:''};applyEpaEnvironmentDisplay();return p.epaEnvironment;}
  function tickEpaRuntime(){const p=ensurePlayerStats();if(!p)return;const env=p.epaEnvironment;if(env&&env.remaining>0){if(env.rupture&&combatInProgress()&&Math.floor(Math.random()*6)===0){const heroLoss=loseEnergy(1);let foes=0;for(const c of appState.combats||[])if(c&&!c.won&&(c.started||c.reaction==='HOSTIL'))foes+=Math.max(0,damageCurrentCombatEnemy(c,1));if(heroLoss||foes)queueFx('damage','RUPTURA VULCÂNICA',`${heroLoss?'-1 VIDA no herói. ':''}${foes?`${foes} VIDA distribuída entre os inimigos.`:''}`.trim());}env.remaining=Math.max(0,env.remaining-1);if(env.remaining===0){if(env.reversalId)deactivateEpaReversal(env.reversalId);p.epaEnvironment=null;applyEpaEnvironmentDisplay();queueFx('luckWin','A REALIDADE SE RECOMPÕE','O terreno e o clima originais retornam.');}}if(p.epaHazard?.remaining>0){p.epaHazard.remaining=Math.max(0,p.epaHazard.remaining-1);if(p.epaHazard.remaining===0)p.epaHazard=null;}if(p.epaSquid?.remaining>0){p.epaSquid.remaining=Math.max(0,p.epaSquid.remaining-1);if(p.epaSquid.remaining===0){clearEpaSquidRuntime();if(hasState('IMOBILIZADO'))removeState('IMOBILIZADO');queueFx('luckWin','A LULA SE SOLTA','O peso desaparece e seus movimentos voltam ao normal.',{quiet:true});}else renderEpaSquidOverlay();}}
