  function topStatusItemHtml(text){const raw=String(text||''),i=raw.indexOf(':');if(i<0)return `<span class="top-status-item"><strong>${esc(raw)}</strong></span>`;const name=raw.slice(0,i).trim(),detail=raw.slice(i+1).trim();return `<span class="top-status-item"><strong>${esc(name)}</strong>${detail?`: <span class="top-status-detail">${esc(detail)}</span>`:''}</span>`;}
