  function normalizeEffectMarker(raw=''){return canonicalizeStatSyntax(String(raw||'').trim());}
  function splitSimpleEffectMarkers(raw=''){const text=String(raw||'').trim(),found=text.match(/!?\{[^{}]+\}/g)||[];if(found.length&&found.join('')===text.replace(/\s+/g,''))return found.map(normalizeEffectMarker);if(found.length>1)return found.map(normalizeEffectMarker);return text?[normalizeEffectMarker(text)]:[];}
