  function normalizeCustomStateDefinition(def={}){const name=cleanStateName(def.name||''),hidden=!!def.hidden,duration=def.duration==null?null:Math.max(1,parseInt(def.duration)||1),effects=Array.isArray(def.effects)?def.effects.map(normalizeEffectEntry).filter(x=>x.marker):[];return {name,hidden,duration,reapply:'renew',effects};}
  function serializeCustomDefinitions(book=appState.book){const catalog=ensureEditorCatalog(book),lines=[];for(const item of catalog.items||[]){const def=normalizeCustomItemDefinition(item);if(def.raw)lines.push(`{ITEM_DEF:${JSON.stringify(def)}}`);}for(const state of catalog.states||[]){const def=normalizeCustomStateDefinition(state);if(def.name)lines.push(`{ESTADO_DEF:${JSON.stringify(def)}}`);}const prices=ensureAdventureMarketPrices(book);if(Object.keys(prices).length)lines.push(`{MERCADO_PRECOS:${JSON.stringify(prices)}}`);for(const recipe of ensureCustomRecipes(book)){const def=normalizeCustomRecipe(recipe);if(def.a&&def.b&&def.result)lines.push(`{RECEITA_DEF:${JSON.stringify(def)}}`);}return lines;}
  function customItemDefinition(metaOrRaw){const key=itemMeta(typeof metaOrRaw==='string'?metaOrRaw:metaOrRaw?.raw||'').key;return ensureEditorCatalog().items.map(normalizeCustomItemDefinition).find(x=>itemMeta(x.raw).key===key)||null;}
  function customStateDefinition(name){const key=stateKey(name);return ensureEditorCatalog().states.map(normalizeCustomStateDefinition).find(x=>stateKey(x.name)===key)||null;}
  function ensureSourcedEffects(){const p=appState.player;if(!p)return {};if(!p.sourcedEffects||typeof p.sourcedEffects!=='object')p.sourcedEffects={};return p.sourcedEffects;}
  function sourcedRecord(sourceId){const all=ensureSourcedEffects();if(!all[sourceId])all[sourceId]={stats:[],addedStates:[]};return all[sourceId];}
  function statInitialKey(key){return {skill:'initialSkill',luck:'initialLuck',magic:'initialMagic',stamina:'initialStamina'}[key]||'';}
  function applySourcedStatModifier(sourceId,statToken,delta){const stat=normalizeStatToken(statToken),key=statKeyFromToken(stat),n=parseInt(delta)||0;if(!sourceId||!key||!n)return false;const rec=sourcedRecord(sourceId),p=ensurePlayerStats(),initialKey=statInitialKey(key),before=Number(p[key])||0,beforeInitial=initialKey?(Number(p[initialKey])||0):null;p[key]=Math.max(0,before+n);if(initialKey)p[initialKey]=Math.max(0,beforeInitial+n);const actual=p[key]-before,actualInitial=initialKey?p[initialKey]-beforeInitial:0;rec.stats.push({key,initialKey,actual,actualInitial,markerDelta:n});if(key==='stamina'&&p.stamina<=0)queueFx('death','VIDA ESGOTADA','Um efeito ativo reduziu sua VIDA a zero.');return true;}
  function applySourcedStateAdd(sourceId,name,{hidden=false}={}){name=cleanStateName(name);if(!sourceId||!name)return false;const rec=sourcedRecord(sourceId),key=stateKey(name);addState(name,{hidden,sourceId});if(!rec.addedStates.includes(key))rec.addedStates.push(key);return true;}
  function releaseSourcedState(sourceId,stKey){const st=playerStates().find(x=>stateKey(x.name)===stKey);if(!st)return;if(!Array.isArray(st.sourceOwners))st.sourceOwners=[];st.sourceOwners=st.sourceOwners.filter(x=>x!==sourceId);if(!st.independent&&!st.sourceOwners.length)removeState(st.name);}
  function clearSourcedEffects(sourceId){const all=ensureSourcedEffects(),rec=all[sourceId];if(!rec)return;const p=ensurePlayerStats();for(const stKey of [...(rec.addedStates||[])].reverse())releaseSourcedState(sourceId,stKey);for(const mod of [...(rec.stats||[])].reverse()){p[mod.key]=Math.max(0,(Number(p[mod.key])||0)-(Number(mod.actual)||0));if(mod.initialKey)p[mod.initialKey]=Math.max(0,(Number(p[mod.initialKey])||0)-(Number(mod.actualInitial)||0));}delete all[sourceId];}
  function clearSourcedEffectsByPrefix(prefix=''){for(const key of Object.keys(ensureSourcedEffects()))if(key.startsWith(prefix))clearSourcedEffects(key);}
  function applyCustomEffectMarkerSync(marker,{source='EFEITO',sourceId='',active=false}={}){const raw=normalizeEffectMarker(marker);if(!raw)return false;let m=raw.match(/^\{([+-])\s*(\d+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)\}$/i);if(m){const amount=(m[1]==='+'?1:-1)*(parseInt(m[2])||0);if(active&&sourceId)return applySourcedStatModifier(sourceId,m[3],amount);const stat=normalizeStatToken(m[3]),key=statKeyFromToken(stat),p=ensurePlayerStats(),before=p[key],actual=changePlayerStat(key,amount,before);if(actual)queueFx(actual<0?'luckLoss':'luckWin',source,`${amount>0?'+':''}${amount} ${playerStatLabel(stat)}`);return true;}m=raw.match(/^!\{Estado:([^}]+)\}$/i);if(m){if(active)return false;removeState(m[1]);return true;}m=raw.match(/^(!)?\{ESTADO:([^}]+)\}$/i);if(m){if(active&&sourceId)return applySourcedStateAdd(sourceId,m[2],{hidden:!!m[1]});addState(m[2],{hidden:!!m[1]});return true;}return false;}
  const customStateActivationStack=new Set();
  function customEffectsByTiming(def,timing){return (def?.effects||[]).filter(x=>x.timing===timing&&x.marker);}
  function activateCustomStateDefinition(entry,{reapplied=false}={}){const def=customStateDefinition(entry?.name),key=stateKey(entry?.name);if(!def||!key||customStateActivationStack.has(key))return;customStateActivationStack.add(key);try{entry.age=0;entry.delayedFired=[];entry.turnsRemaining=def.duration==null?null:def.duration;const sourceId=`state:${key}`;if(!ensureSourcedEffects()[sourceId])for(const fx of customEffectsByTiming(def,'active'))applyCustomEffectMarkerSync(fx.marker,{source:`ESTADO ${entry.name}`,sourceId,active:true});for(const fx of customEffectsByTiming(def,'apply'))applyCustomEffectMarkerSync(fx.marker,{source:`ESTADO ${entry.name}`});}finally{customStateActivationStack.delete(key);}}
  function applyCustomStateEndEffects(entry){const def=customStateDefinition(entry?.name);if(!def)return;for(const fx of customEffectsByTiming(def,'end'))applyCustomEffectMarkerSync(fx.marker,{source:`FIM DE ${entry.name}`});}
  function tickCustomStates(){for(const entry of [...playerStates()]){const def=customStateDefinition(entry.name);if(!def)continue;entry.age=Math.max(0,Number(entry.age)||0)+1;if(!Array.isArray(entry.delayedFired))entry.delayedFired=[];for(let i=0;i<(def.effects||[]).length;i++){const fx=def.effects[i];if(fx.timing==='delayed'&&entry.age>=fx.delay&&!entry.delayedFired.includes(i)){entry.delayedFired.push(i);applyCustomEffectMarkerSync(fx.marker,{source:`ESTADO ${entry.name}`});}else if(fx.timing==='periodic'&&entry.age%Math.max(1,fx.every||1)===0)applyCustomEffectMarkerSync(fx.marker,{source:`ESTADO ${entry.name}`});}if(entry.turnsRemaining!=null&&Number.isFinite(Number(entry.turnsRemaining))){entry.turnsRemaining=Math.max(0,Number(entry.turnsRemaining)-1);if(entry.turnsRemaining<=0){const label=entry.name,visible=!entry.hidden;removeState(label);if(visible)noteSystemState('state-removed',label,{source:'duração'});else toast(`${label} terminou.`);}}}}
  function rebuildCustomStateActiveEffects(){clearSourcedEffectsByPrefix('state:');for(const st of playerStates()){const def=customStateDefinition(st.name);if(!def)continue;const sourceId=`state:${stateKey(st.name)}`;for(const fx of customEffectsByTiming(def,'active'))applyCustomEffectMarkerSync(fx.marker,{source:`ESTADO ${st.name}`,sourceId,active:true});}}
  function syncCustomStateActiveEffects(){const stateKeys=new Set(playerStates().map(x=>stateKey(x.name)));for(const sourceId of Object.keys(ensureSourcedEffects()))if(sourceId.startsWith('state:')&&!stateKeys.has(sourceId.slice(6)))clearSourcedEffects(sourceId);for(const st of playerStates()){const def=customStateDefinition(st.name),sourceId=`state:${stateKey(st.name)}`;if(def&&!ensureSourcedEffects()[sourceId])for(const fx of customEffectsByTiming(def,'active'))applyCustomEffectMarkerSync(fx.marker,{source:`ESTADO ${st.name}`,sourceId,active:true});}}
  function syncActiveCustomItemEffects(){const active=ensureActiveItems(),activeKeys=new Set(Object.keys(active).filter(k=>active[k]));for(const sourceId of Object.keys(ensureSourcedEffects()))if(sourceId.startsWith('item:')&&!activeKeys.has(sourceId.slice(5)))clearSourcedEffects(sourceId);for(const key of activeKeys){const entry=inventoryEntry(key),def=entry?customItemDefinition(entry.meta):null,sourceId=`item:${key}`;if(def&&!ensureSourcedEffects()[sourceId])for(const fx of customEffectsByTiming(def,'active'))applyCustomEffectMarkerSync(fx.marker,{source:`ITEM ${entry.meta.name}`,sourceId,active:true});}}
  function scheduleCustomItemDelayedEffects(meta){const def=customItemDefinition(meta);if(!def)return;const p=ensureTimeState();for(const fx of customEffectsByTiming(def,'delayed'))p.temporalEffects.push({sourceSection:`ITEM:${meta.key}`,remaining:Math.max(1,fx.delay||1),actions:[fx.marker]});}
  function temporalEffects(){if(!Array.isArray(appState.player?.temporalEffects))appState.player.temporalEffects=[];return appState.player.temporalEffects;}
  function temporalActionLabel(raw=''){
    const v=String(raw||'').trim(),state=v.match(/^!?\{ESTADO(?::([^}]*))?\}$/i);if(state)return state[1]?`Estado: ${cleanStateName(state[1])}`:'Remover estados';const stat=v.match(/^\{([+-])\s*(\d+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)\}$/i);if(stat)return `${stat[1]}${stat[2]} ${playerStatLabel(stat[3])}`;
    const item=v.match(/^\{([+-])\s*(.+)\}$/i);if(item){const meta=itemMeta(item[2].trim());return item[1]==='+'?meta.name:`-${meta.name}`;}
    const treasure=v.match(/^\{TESOURO(?:\s+\+?([^}]+))?\}$/i);if(treasure)return treasure[1]?`Tesouro: ${treasure[1].trim()}`:'Tesouro';
    const music=v.match(/^\{MUSICA:(.*?)\}$/i);if(music)return 'Nova trilha sonora';
    const encounter=parseEncounterDef(v);if(encounter?.opponents?.length)return `Combate com ${encounter.opponents.map(op=>op.name).join(', ')}`;
    return v.replace(/^\{|\}$/g,'').trim()||'Evento';
  }
  function temporalStatusParts(){const parts=[];if(!appState.player)return parts;for(const e of temporalEffects()){for(const action of e.actions||[]){const label=temporalActionLabel(action);parts.push(e.remaining==null?`🕑 ${label} a cada turno`:`🕑 ${label} daqui ${e.remaining} ${e.remaining===1?'turno':'turnos'}`);}}return parts;}
  function renderTemporalStatus(){const box=el('timeStatus');if(!box)return;box.innerHTML='';box.classList.add('hidden');}
  function registerTemporalMarkers(sec,{replaceCurrent=false}={}){
    const list=temporalEffects();if(replaceCurrent){appState.player.temporalEffects=list.filter(e=>e.sourceSection!==sec.id);}
    const defs=sec?.tempos||[];if(defs.some(t=>t.zero)){appState.player.temporalEffects=[];appState.effects.push({text:'TEMPO: efeitos interrompidos',loss:false});}
    for(const t of defs){if(t.zero||!(t.actions||[]).length)continue;appState.player.temporalEffects.push({sourceSection:sec.id,remaining:t.duration==null?null:t.duration,actions:[...t.actions]});}
  }
  function advanceTemporalEffects(){
    const list=temporalEffects(),keep=[];for(const e of list){if(e.remaining==null){queueTemporalActions(e.actions);keep.push(e);continue;}e.remaining--;if(e.remaining<=0)queueTemporalActions(e.actions);else keep.push(e);}appState.player.temporalEffects=keep;
  }
  function processTemporalSectionEntry(sec){
    const defs=sec?.tempos||[];if(defs.some(t=>t.zero)){appState.player.temporalEffects=[];appState.effects.push({text:'TEMPO: efeitos interrompidos',loss:false});}
    for(const t of defs){if(t.zero||!(t.actions||[]).length)continue;appState.player.temporalEffects.push({sourceSection:sec.id,remaining:t.duration==null?null:t.duration,actions:[...t.actions]});}
  }
