  async function executeTemporalAction(raw){
    const v=String(raw||'').trim(),p=appState.player;
    let rm=v.match(/^!\{Estado:([^}]+)\}$/i);if(rm){const name=cleanStateName(rm[1]),existing=playerStates().find(x=>stateKey(x.name)===stateKey(name));removeState(name);appState.effects.push({text:`ESTADO REMOVIDO: ${name}`,loss:true});if(existing&&!existing.hidden)noteSystemState('state-removed',name,{source:'tempo'});return;}let sm=v.match(/^(!)?\{ESTADO(?::([^}]*))?\}$/i);if(sm){const name=cleanStateName(sm[2]||'');if(!name){const visibleBefore=playerStates().filter(x=>!x.hidden).length;clearAllStates();appState.effects.push({text:'ESTADOS REMOVIDOS',loss:false});if(visibleBefore)offerSystemNarrativeMoment({kind:'states-cleared',importance:'significant',title:'CONDIÇÕES SUPERADAS',headline:'VOCÊ RECUPERA ESTABILIDADE',icon:'◇'});}else{const existing=playerStates().find(x=>stateKey(x.name)===stateKey(name)),wasHidden=existing?.hidden;addState(name,{hidden:!!sm[1]});if(!sm[1])appState.effects.push({text:`ESTADO: ${name}`,loss:false});if(!sm[1]&&(!existing||wasHidden))noteSystemState('state-added',name,{source:'tempo'});}return;}
    let m=v.match(/^\{([+-])\s*(\d+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)\}$/i);if(m){const stat=normalizeStatToken(m[3]),key=statKeyFromToken(stat),requested=(m[1]==='+'?1:-1)*(+m[2]),before=p[key];const actual=changePlayerStat(key,requested,before);appState.effects.push({text:`${requested>0?'+':''}${requested} ${playerStatLabel(stat)}`,loss:requested<0});if(key==='stamina'&&actual>0)queueFx('energyUp','VIDA RECUPERADA',`+${actual} VIDA`);if(key==='stamina'&&actual<0)queueFx('energyDown','VIDA REDUZIDA',`${actual} VIDA`);if(p.stamina<=0){queueFx('death','MORTE','Sua VIDA chegou a zero.');document.body.classList.add('fx-death');}return;}
    m=v.match(/^\{([+-])\s*(.+)\}$/i);if(m){const meta=itemMeta(m[2].trim()),isProvision=/^provisão$/i.test(meta.name);if(m[1]==='+'){if(isProvision){const added=addQuantity('Provisão',1);appState.effects.push({text:added?`ADQUIRIU: Provisão ×${p.provisions}`:'CARGA CHEIA: Provisão',loss:false});}else{const added=addQuantity(meta.raw,1,{narrativeDiscovery:true,narrativeSource:'tempo'});appState.effects.push({text:added?`ADQUIRIU: ${effectInventoryDisplayName(meta)}${itemCount(meta.raw)>1?` ×${itemCount(meta.raw)}`:''}`:`CARGA CHEIA: ${meta.name}`,loss:false});}}else{if(isProvision){const removed=p.provisions>0;if(removed){p.provisions--;journalRecordItem('Provisão',1,'remove');markRuntimeChanged();}appState.effects.push({text:removed?`REMOVEU: Provisão · RESTAM ×${p.provisions}`:'ITEM AUSENTE: Provisão',loss:true});}else{const removed=removeOneItem(meta.raw);appState.effects.push({text:removed?`REMOVEU: ${effectInventoryDisplayName(meta)}`:`ITEM AUSENTE: ${meta.name}`,loss:true});}}return;}
    m=v.match(/^\{TESOURO(?:\s+\+?([^}]+))?\}$/i);if(m){let reward;if(m[1]){const r=parseQtyItem(m[1].trim());reward={headline:qtyLabel(r.qty,r.item),detail:`${qtyLabel(r.qty,r.item)} chegou até você.`,icon:'💎',item:r.item,qty:r.qty};}else{const roll=await dramaticRoll({title:'Tesouro do tempo',lead:'Algo destinado a você finalmente chegou. Role 2d6.',diceCount:2,evaluate:r=>{const total=r[0]+r[1];return {total,equation:`${r[0]} + ${r[1]} = ${total}`,headline:'TESOURO',detail:'O tempo entregou sua recompensa.'};}});if(!roll)return;reward=treasureRewardFor(roll.total);}applyTreasureReward(reward);await showRewardMoment({kind:'treasure',title:'O TEMPO SE CUMPRIU',headline:reward.headline,detail:reward.detail,icon:reward.icon});return;}
    m=v.match(/^\{MUSICA:(.*?)\}$/i);if(m){const music=normalizeMusicUrl(m[1]);if(music){appState.activeMusicUrl=music;if(appState.musicPlaying)startSoundtrack(music);}return;}
    const timedEncounter=parseEncounterDef(v);if(timedEncounter?.opponents?.length){const built=instantiateEncounterRuntime(timedEncounter,appState.sectionId),startIndex=appState.combats.length;if(!appState.encounterRuntime)appState.encounterRuntime=built.runtime;else appState.encounterRuntime.events.push(...built.runtime.events);appState.combats.push(...built.combats);setActiveCombat(startIndex);const names=built.combats.map(c=>c.name),headline=names.length===1?`${names[0]} SURGE`:'NOVOS OPONENTES SURGEM';await showRewardMoment({kind:'special',title:'O TEMPO SE CUMPRIU',headline,detail:'Um novo combate começa agora.',icon:'👹'});const c=built.combats[0];if(c?.ambush)setTimeout(()=>resolveAmbushCombat(c),80);return;}
  }

  function enterSection(id,applyEffects=true,scroll=true){appState.voiceFollowupSectionId=null;appState.bookPlayerFocus=null;
    const sec=appState.book.sections[id];if(!sec){toast(`Seção ${id} inexistente.`);return;}const previousId=appState.sectionId;if(!appState.editor&&previousId&&previousId!==id)storeCurrentSectionMemory(previousId);appState.sectionId=id;appState.bookSubpageIndex=0;appState.bookSubpageCount=1;appState.bookPaginationPages=[];appState.bookPaginationSourceHtml='';appState.bookPaginationSourceSectionId=id;markSectionVisited(id);if(!appState.editor){appState.latestSectionId=id;if(appState.adventureStarted&&previousId!==id){const memory=ensureSectionMemory(id);memory.visits=Math.max(1,memory.visits+1);}}if(applyEffects&&!appState.editor)advanceHungerSectionCounter(previousId,id);appState.effects=[];appState.appliedSectionEffects=[];initSectionCombats(sec);initSectionNpc(sec);const activeTrack=adoptSectionMusic(sec);if(sec.music&&appState.musicPlaying)startSoundtrack(activeTrack);if(!appState.editor){adoptSectionClimate(sec);adoptSectionTerrain(sec);}if(applyEffects&&!appState.editor){appState.sectionCheckpoint={...captureState(),historyLength:appState.history.length};applySectionEntryEffectsOnce(sec);}renderAll();if(scroll)window.scrollTo({top:0,behavior:bookModeEnabled()?'auto':'smooth'});if(!appState.editor){scheduleQuickCombatResolution(false?520:460);noteSanityRealSectionEntry(id,previousId);}
  }

  function applySectionStates(sec,{narrative=true}={}){
    const entries=sec?.states||[];if(!entries.length)return;const p=ensurePlayerStats(),before=deepClone(playerStates()),beforeStats={skill:p.skill,luck:p.luck,magic:p.magic,stamina:p.stamina,initialSkill:p.initialSkill,initialLuck:p.initialLuck,initialMagic:p.initialMagic,initialStamina:p.initialStamina},beforeSourced=deepClone(ensureSourcedEffects());let changed=false;
    for(const st of entries){if(st.clear){const visibleBefore=playerStates().filter(x=>!x.hidden).length;clearAllStates();changed=true;appState.effects.push({text:'ESTADOS REMOVIDOS',loss:false});if(narrative&&visibleBefore)offerSystemNarrativeMoment({kind:'states-cleared',importance:'significant',title:'CONDIÇÕES SUPERADAS',headline:'VOCÊ RECUPERA ESTABILIDADE',icon:'◇'});continue;}const name=cleanStateName(st.name);if(!name)continue;if(st.remove){const existing=playerStates().find(x=>stateKey(x.name)===stateKey(name)),removed=removeState(name);if(removed){changed=true;appState.effects.push({text:`ESTADO REMOVIDO: ${name}`,loss:true});if(narrative&&!existing?.hidden)noteSystemState('state-removed',name,{source:'section'});if(stateKey(name)===stateKey('Envenenado'))appState.player.poisonEffect=null;}continue;}const existing=playerStates().find(x=>stateKey(x.name)===stateKey(name)),wasHidden=existing?.hidden;addState(name,{hidden:!!st.hidden});changed=true;if(!st.hidden&&(!existing||wasHidden)){appState.effects.push({text:`ESTADO: ${name}`,loss:false});if(narrative)noteSystemState('state-added',name,{source:'section'});}}
    if(changed)appState.appliedSectionEffects.push({kind:'statesSnapshot',states:before,stats:beforeStats,sourcedEffects:beforeSourced});
  }

  function applySectionEffects(sec,{narrative=true}={}){
    const ownCycle=narrative&&beginSystemNarrativeCycle(`section:${appState.sectionId}`);appState.appliedSectionEffects=[];applySectionStates(sec,{narrative});let energyDelta=0;
    if((sec.knowledges||[]).length){const p=ensureKnowledgeState();appState.appliedSectionEffects.push({kind:'knowledgeSnapshot',knowledges:deepClone(p.knowledges),knowledgeBoost:p.knowledgeBoost,knowledgeBoostTurns:p.knowledgeBoostTurns});for(const name of sec.knowledges){const result=acquireKnowledge(name),text=knowledgeGainText(result);if(text)appState.effects.push({text,loss:result.kind==='collapse'||result.kind==='limit'});if(narrative)noteSystemKnowledge(result,'section');}}
    for(const book of sec.books||[]){const meta=itemMeta(book.item),added=addQuantity(meta.raw,1,{narrativeDiscovery:narrative,narrativeSource:'section'});appState.appliedSectionEffects.push({kind:'item',op:'+',item:meta.raw,qty:1,appliedQty:added});appState.effects.push({text:added?`ADQUIRIU: ${effectInventoryDisplayName(meta)}`:`CARGA CHEIA: ${meta.name}`,loss:false});}
    for(const m of sec.mods||[]){
      if(m.kind==='item'){
        const qty=Math.max(1,m.qty||1),meta=itemMeta(m.item),isProvision=isProvisionName(meta.raw);
        if(m.op==='+'){
          if(isProvision){const added=addQuantity('Provisão',qty);appState.appliedSectionEffects.push({kind:'provision',op:'+',qty:added,applied:added>0});appState.effects.push({text:added?`ADQUIRIU: Provisão ×${appState.player.provisions}`:'CARGA CHEIA: Provisão',loss:false});}
          else{const added=addQuantity(m.item,qty,{narrativeDiscovery:narrative,narrativeSource:'section'});appState.appliedSectionEffects.push({kind:'item',op:'+',item:m.item,qty,appliedQty:added});const count=itemCount(m.item),label=effectInventoryDisplayName(meta);appState.effects.push({text:added?`ADQUIRIU: ${label}${count>1?` ×${count}`:''}`:`CARGA CHEIA: ${label}`,loss:false});}
        } else {
          if(isProvision){const removed=Math.min(qty,appState.player.provisions);if(removed){appState.player.provisions-=removed;journalRecordItem('Provisão',removed,'remove');markRuntimeChanged();}appState.appliedSectionEffects.push({kind:'provision',op:'-',qty:removed,applied:removed>0});appState.effects.push({text:removed?`REMOVEU: Provisão · RESTAM ×${appState.player.provisions}`:'ITEM AUSENTE: Provisão',loss:true});}
          else{let removed=0;for(let i=0;i<qty;i++)if(removeOneItem(m.item))removed++;appState.appliedSectionEffects.push({kind:'item',op:'-',item:m.item,qty:removed,appliedQty:removed});const left=itemCount(m.item),label=effectInventoryDisplayName(meta);appState.effects.push({text:removed?`REMOVEU: ${label}${left>0?` · RESTAM ×${left}`:''}`:`ITEM AUSENTE: ${label}`,loss:true});}
        }
      } else {
        const key=statKeyFromToken(m.stat),requested=(m.op==='+'?1:-1)*m.amount,before=appState.player[key];const actual=changePlayerStat(key,requested,before);appState.appliedSectionEffects.push({kind:'stat',key,actual});if(key==='stamina')energyDelta+=actual;appState.effects.push({text:`${requested>0?'+':''}${requested} ${playerStatLabel(m.stat)}`,loss:requested<0});
      }
    }
    if(energyDelta>0)queueFx('energyUp','VIDA RECUPERADA',`+${energyDelta} VIDA`);if(energyDelta<0)queueFx('energyDown','VIDA REDUZIDA',`${energyDelta} VIDA`);if(appState.player.stamina<=0){appState.player.stamina=0;appState.effects.push({text:'VIDA ESGOTADA',loss:true});queueFx('death','MORTE','Sua VIDA chegou a zero.');}if(ownCycle)commitSystemNarrativeCycle();
  }

  function undoAppliedSectionEffects(){const priorJournalMute=appState.journalMuted;appState.journalMuted=true;try{
    const ops=[...(appState.appliedSectionEffects||[])].reverse();
    for(const op of ops){
      if(op.kind==='statesSnapshot'){clearSourcedEffectsByPrefix('state:');appState.player.states=deepClone(op.states||[]);if(op.stats)for(const [k,v] of Object.entries(op.stats))appState.player[k]=v;appState.player.sourcedEffects=deepClone(op.sourcedEffects||{});rebuildCustomStateActiveEffects();}else if(op.kind==='knowledgeSnapshot'){const p=ensureKnowledgeState();p.knowledges=deepClone(op.knowledges||{});p.knowledgeBoost=Number(op.knowledgeBoost)||0;p.knowledgeBoostTurns=Number(op.knowledgeBoostTurns)||0;}else if(op.kind==='item'){const qty=op.appliedQty??(op.applied?op.qty||1:0);if(!qty)continue;if(op.op==='+')removeQuantity(op.item,qty);else addQuantity(op.item,qty,{force:true});}
      else if(op.kind==='provision'){const qty=op.qty??(op.applied?1:0);if(!qty)continue;if(op.op==='+')appState.player.provisions=Math.max(0,appState.player.provisions-qty);else appState.player.provisions+=qty;}
      else if(op.kind==='stat'&&op.actual)appState.player[op.key]-=op.actual;
    }
    appState.appliedSectionEffects=[];appState.effects=[];appState.player.stamina=Math.min(appState.player.stamina,appState.player.initialStamina);if(appState.player.stamina>0)document.body.classList.remove('fx-death');
  }finally{appState.journalMuted=priorJournalMute;}}

  function auraActive(){return (appState.player?.auraTurns||0)>0;}
  function tickAuraTurn(){const p=appState.player;if(!p||!p.auraTurns)return;p.auraTurns=Math.max(0,p.auraTurns-1);if(p.auraTurns===0)toast('A Aura se dissipou.');}
  function tickPoisonEffect(){const p=ensureTimeState();if(!p)return;if(!hasState('Envenenado')){p.poisonEffect=null;return;}const fx=p.poisonEffect;if(!fx)return;fx.remaining=Math.max(0,(Number(fx.remaining)||1)-1);if(fx.remaining>0)return;const lost=spendEnergy(1);if(lost)queueFx('energyDown','VENENO','-1 VIDA');fx.interval=secureDie();fx.remaining=fx.interval;if(p.stamina<=0)queueFx('death','MORTE','O veneno consumiu sua última VIDA.');}
  function tickTurnCounters(){const p=ensurePlayerStats();if(p)p.turnSerial=(Number(p.turnSerial)||0)+1;if(appState.combat?.reequipOpportunity)appState.combat.reequipOpportunity=false;tickSkillModifiers();tickAuraTurn();tickPoisonEffect();tickKnowledgeEffects();tickTemporarySpells();tickMultiHands();tickTorchTurn();tickCustomStates();tickCombatRecoveries();tickEpaRuntime();scheduleFaerieDebtCollection();}
  function loseEnergy(amount,reason=''){const p=appState.player,loss=Math.max(0,+amount||0);if(!p||loss<=0)return 0;if(auraActive()){queueFx('luckWin','AURA PROTEGEU',`${loss} VIDA evitada`);return 0;}const finalLoss=applyArmorProtection(loss);const before=p.stamina;p.stamina=Math.max(0,p.stamina-finalLoss);return before-p.stamina;}
  function spendEnergy(amount){const p=appState.player,loss=Math.max(0,+amount||0);if(!p||loss<=0)return 0;const before=p.stamina;p.stamina=Math.max(0,p.stamina-loss);return before-p.stamina;}
  function changePlayerStat(key,delta,beforeValue=null){const p=ensurePlayerStats(),before=beforeValue??p[key];markRuntimeChanged();if(key==='stamina'){if(delta<0)loseEnergy(-delta);else p.stamina=Math.min(p.initialStamina,p.stamina+delta);}else if(key==='magic'){if(delta<0)spendMagic(-delta);else recoverMagic(delta);}else p[key]=Math.max(0,p[key]+delta);if(key==='luck'&&p[key]<=0)breakLuckAmuletIfDepleted();return p[key]-before;}


  /* v212 — Economia nativa de SANIDADE: Prazer + recomposição universal. */
  /* v210 — Diretor de SANIDADE. Os episódios são internos ao motor e independentes do Markdown. */
  const SANITY_WHISPERS=[
    '{NOME}, vire-se.','{NOME}, eles sabem onde você está.','{NOME}, você deixou alguma coisa para trás.','{NOME}, pare de fingir que não me ouve.','{NOME}, isso já aconteceu antes.','{NOME}, saia daqui.','{NOME}, fique em silêncio.','{NOME}, você se lembra de mim?','{NOME}, não confie no que está vendo.','{NOME}, continue andando. Não olhe para trás.'
  ];
  const SANITY_MONSTERS=['A Sombra','O Homem sem Rosto','Seu Duplo','A Coisa que Rasteja','A Figura Atrás de Você','A Criança sem Olhos','O Animal Impossível','A Massa de Mãos'];
  const SANITY_ILLUSIONS=[
    {id:'reflexo',title:'O Reflexo Atrasado',loop:true,trap:0,variants:[
      `Você percebe uma pessoa diante de você.\n\nPor um instante parece perfeitamente normal, até que entende que está olhando para si mesmo.\n\nVocê ergue a mão. O reflexo permanece imóvel. Alguns segundos depois, ele ergue a própria mão também.\n\nEntão sorri.\n\nVocê ainda não sorriu.\n\n— Você está ficando lento, {NOME}.`,
      `Você percebe uma pessoa diante de você.\n\nÉ você outra vez. Há uma certeza desagradável de que já tocou aquela superfície antes.\n\nO reflexo parece aliviado ao vê-lo.\n\n— Voltou, {NOME}.`,
      `A superfície está diante de você novamente. Seus dedos parecem frios antes mesmo de tocá-la.\n\nO reflexo inclina a cabeça.\n\n— Quantas vezes ainda vamos trocar de lugar, {NOME}?`
    ],choices:[['Tocar o reflexo','Afastar-se dele']],resolutions:[`A superfície cede como pele fria. Uma mão segura a sua pelo outro lado e puxa com força. Por um instante você tem certeza de ter atravessado para o lugar onde o reflexo estava.`,`Você recua. O reflexo permanece imóvel. Então ele dá um passo em sua direção, embora você continue se afastando.`]},
    {id:'cadeiras',title:'As Cadeiras',text:`Quando percebe, existem cadeiras ao seu redor.\n\nDezenas delas. Todas vazias. Todas voltadas para você.\n\nUma cadeira começa a bater contra o chão como se alguém invisível estivesse aplaudindo. Outra responde. Logo toda a sala ressoa com uma salva de palmas produzida por pessoas que você não consegue ver.\n\nAs palmas cessam ao mesmo tempo.\n\nUma voz cochicha:\n\n— Agora faça alguma coisa interessante.`,choices:[['Perguntar quem está ali','Derrubar uma das cadeiras']],resolutions:[`Todas as palmas param. Uma voz responde, muito perto: — Você sabe.`,`A cadeira cai. O assento afunda por um instante, como se alguém invisível acabasse de se levantar.`]},
    {id:'nome',title:'Seu Nome',text:`— {NOME}.\n\nVocê olha ao redor.\n\n— {NOME}.\n\nA voz está mais próxima.\n\n— {NOME}.\n\nAgora parece vir exatamente de trás da sua cabeça.\n\nVocê tenta ignorá-la.\n\n— {NOME}.\n\nDesta vez percebe algo pior.\n\nA voz é sua.`,choices:[['Responder à voz','Ordenar que ela se cale']],resolutions:[`— Finalmente — responde sua própria voz.`,`— Foi você quem começou a falar comigo — responde a voz.`]},
    {id:'outra-versao',title:'A Outra Versão',text:`Alguém está esperando por você.\n\nÉ você.\n\nAs mesmas feições. As mesmas roupas. As mesmas marcas.\n\nA outra versão parece exausta.\n\n— Finalmente.\n\nEla olha para algum ponto atrás de você.\n\n— Desta vez, tente sobreviver mais tempo.\n\nVocê pergunta do que está falando.\n\nEla apenas balança a cabeça.\n\n— Você sempre pergunta isso.`,choices:[['Perguntar como você morreu','Exigir que prove quem é']],resolutions:[`— Do mesmo jeito que vai morrer desta vez.`,`Seu duplo menciona uma lembrança íntima com uma precisão impossível. Você reconhece cada detalhe e, ao mesmo tempo, tem certeza de que aquilo jamais aconteceu.`]},
    {id:'corredor',title:'O Corredor',loop:true,trap:0,variants:[
      `Existe um corredor diante de você.\n\nVocê começa a atravessá-lo. A extremidade parece próxima, mas cada passo torna o corredor ligeiramente mais comprido.\n\nVocê acelera. Ele cresce. Você corre. Ele continua crescendo.\n\nEntão percebe uma figura parada muito longe, na outra extremidade.\n\nÉ você.\n\nA figura também está correndo. Na sua direção.`,
      `Existe um corredor diante de você.\n\nSeus músculos já parecem cansados, embora você mal tenha começado.\n\nAo longe, alguém corre em sua direção. É você.\n\nDesta vez, ele também parece cansado.`,
      `O corredor continua diante de você.\n\nVocê já conhece cada passo, cada distância impossível. Seu outro eu corre na direção contrária com o mesmo cansaço nos olhos.\n\nNenhum dos dois parece capaz de chegar ao fim.`
    ],choices:[['Correr ao encontro dele','Parar e esperar']],resolutions:[`Você corre. A distância se alonga outra vez, como se o corredor estivesse sendo criado à frente dos seus pés.`,`Seu outro eu continua correndo. Quanto mais se aproxima, mais lentamente se move, até ficar imóvel diante de você. — Finalmente aprendemos alguma coisa.`]},
    {id:'contagem',title:'A Contagem',loop:true,trap:0,variants:[
      `Uma voz começa a contar.\n\n— Dez.\n— Nove.\n— Oito.\n— Sete.\n— Seis.\n\nEntão para.\n\nSilêncio.\n\nBem junto ao seu ouvido, a voz pergunta:\n\n— Quer saber o que acontece quando eu chegar a zero, {NOME}?`,
      `— Dez.\n\nVocê sabe que já ouviu esse número.\n\nA voz prossegue lentamente, satisfeita com a sua atenção.\n\n— Nove. Oito. Sete...`,
      `— Dez.\n\nA voz parece sorrir entre um número e outro.\n\n— Você continua esperando, {NOME}. Isso facilita muito.`
    ],choices:[['Esperar pelo zero','Interromper a contagem']],resolutions:[`A contagem chega a zero. Há um segundo de silêncio absoluto. Então a voz recomeça: — Dez.`,`Você fala por cima da voz. Ela se cala no meio de um número e, pela primeira vez, parece ter sido surpreendida.`]},
    {id:'esqueceu',title:'Algo Ficou Para Trás',text:`Uma certeza absoluta invade sua mente.\n\nVocê esqueceu alguma coisa. Algo importante.\n\nTalvez uma pessoa. Talvez um objeto. Talvez uma promessa.\n\nVocê tenta se lembrar. Quanto mais procura pela memória, mais certeza tem de que aquilo era essencial.\n\nEntão uma segunda certeza surge:\n\nVocê se lembra perfeitamente.\n\nSó está fingindo que esqueceu.`,choices:[['Tentar lembrar o que esqueceu','Voltar para procurar']],resolutions:[`Uma memória inteira surge pronta: cores, vozes e detalhes perfeitos de algo que você sabe que jamais aconteceu.`,`Você se vira para voltar e percebe que é incapaz de recordar de onde veio.`]},
    {id:'passos',title:'O Som dos Passos',text:`Você ouve passos atrás de você.\n\nUm. Dois. Três.\n\nQuando para, eles param. Quando continua, eles continuam.\n\nVocê se vira. Nada.\n\nComeça novamente.\n\nUm. Dois. Três.\n\nDesta vez você permanece completamente imóvel.\n\nOs passos continuam.\n\nE continuam se aproximando.`,choices:[['Virar-se de uma vez','Continuar imóvel']],resolutions:[`Você se vira e encontra apenas suas próprias pegadas chegando até onde está.`,`Os passos param exatamente atrás de você. Algo respira uma única vez junto à sua nuca.`]},
    {id:'porta',title:'A Porta',loop:true,trap:0,variants:[
      `Há uma porta onde antes existia apenas espaço vazio.\n\nVocê tem certeza de que ela jamais esteve ali.\n\nDo outro lado, alguém está chorando.\n\nVocê se aproxima. O choro cessa.\n\nUma voz baixa diz:\n\n— {NOME}?\n\nVocê reconhece a voz. É a sua.\n\n— Por favor, não abra.\n\nA maçaneta começa a girar pelo lado de dentro.`,
      `A porta está diante de você novamente.\n\nAntes mesmo de tocar a maçaneta, você sabe o que encontrará do outro lado.\n\nSua própria voz continua chorando.`,
      `A porta se abre alguns centímetros antes que você faça qualquer movimento.\n\nDo outro lado, seu outro eu já segura a maçaneta.\n\n— Entre. Vamos tentar de novo.`
    ],choices:[['Abrir a porta','Afastar-se dela']],resolutions:[`Você abre a porta. Do outro lado existe o mesmo lugar onde estava. Diante de você há uma porta. Atrás dela, alguém chora.`,`Você se afasta. A porta continua no mesmo lugar, ficando maior em vez de menor conforme a distância cresce.`]},
    {id:'ja-esteve',title:'Você Já Esteve Aqui',loop:true,trap:0,variants:[
      `Tudo parece familiar. Não apenas parecido. Familiar.\n\nVocê sabe exatamente o que acontecerá em seguida.\n\nUma voz falará seu nome. Você ouvirá três batidas. Depois sentirá alguém tocar seu ombro.\n\n— {NOME}.\n\nUma. Duas. Três.\n\nAlgo pousa a mão sobre seu ombro.`,
      `Você conhece esta sequência.\n\nDesta vez decide fazer algo diferente antes que ela termine. No mesmo instante, lembra-se de já ter tomado exatamente essa decisão.`,
      `Você tenta produzir um gesto imprevisível.\n\nEntão se lembra de pensar exatamente isso.\n\nA lembrança chega sempre um instante antes da escolha.`
    ],choices:[['Tentar quebrar a sequência','Deixar que tudo aconteça']],resolutions:[`Você age de forma diferente. Imediatamente se lembra de já ter feito exatamente isso.`,`Você para de resistir. Pela primeira vez acontece algo que não estava na lembrança: absoluto silêncio.`]},
    {id:'publico',title:'O Público',text:`Você percebe pessoas observando você.\n\nSeus rostos permanecem indistintos, como se sua mente recusasse cada tentativa de enxergá-los.\n\nUma delas cochicha alguma coisa. As outras riem. Outra aponta para você. Mais risadas.\n\nEntão todas ficam em silêncio.\n\nUma voz pergunta:\n\n— Ele já percebeu?\n\nOutra responde:\n\n— Ainda pensa que é real.`,choices:[['Aproximar-se delas','Perguntar o que deveria perceber']],resolutions:[`À medida que se aproxima, os rostos começam lentamente a assumir as suas próprias feições.`,`— Que nós estamos do lado de fora — responde alguém.`]},
    {id:'palavra',title:'A Palavra Errada',text:`Você tenta pensar no seu próprio nome.\n\nPor um momento, ele desapareceu.\n\nVocê sabe quem é. Lembra de acontecimentos. Lembra de escolhas. Lembra do seu rosto.\n\nMas seu nome simplesmente deixou de existir.\n\nEntão alguma coisa dentro da sua cabeça oferece outro nome.\n\nVocê sabe que aquele nome está errado. Mesmo assim, por alguns segundos, ele parece muito mais verdadeiro que {NOME}.`,choices:[['Tentar recordar seu nome verdadeiro','Aceitar o outro nome']],resolutions:[`Cada tentativa produz um nome diferente. Todos parecem quase corretos.`,`Uma voz responde imediatamente: — Bem-vindo de volta.`]},
    {id:'branco',title:'O Quarto Branco',loop:true,trap:0,variants:[
      `Tudo desaparece.\n\nExiste apenas um espaço branco sem portas, janelas ou sombras.\n\nVocê está sozinho.\n\nEntão ouve uma voz atrás de você.\n\n— Outra vez aqui?\n\nVocê se vira. Continua sozinho.\n\n— Nós já explicamos isso, {NOME}.\n\nPausa.\n\n— Você precisa parar de inventar lugares para fugir daqui.`,
      `O quarto continua branco.\n\nAgora existe uma porta. Você tem certeza de que acabou de atravessá-la e, mesmo assim, continua do mesmo lado.\n\n— De novo — comenta a voz.`,
      `Existem três versões de você diante de três portas idênticas.\n\nCada uma parece convencida de que as outras duas são parte do problema.`
    ],choices:[['Abrir a porta','Recusar-se a sair']],resolutions:[`Há outro quarto branco. No centro dele está você, diante de uma porta.`,`Você se senta. A voz fica em silêncio. Lentamente, as paredes começam a perder os contornos.`]},
    {id:'conversa',title:'A Conversa Interrompida',text:`Você percebe que alguém está falando com você.\n\nA conversa aparentemente já dura algum tempo.\n\n— ...e foi aí que tudo começou.\n\nVocê tenta lembrar quem é aquela pessoa. Seu rosto parece familiar.\n\n— Você realmente não se lembra de mim? Depois de tudo?\n\nVocê tenta responder.\n\nA figura leva um dedo aos lábios.\n\n— Quieto. Eles estão ouvindo você pensar.`,choices:[['Perguntar quem está ouvindo','Tentar pensar em outra coisa']],resolutions:[`— Eles. A figura olha diretamente para algum ponto além de você.`,`— Isso. Continue fingindo que você escolhe o que pensa.`]},
    {id:'corpo',title:'O Corpo Adiante',text:`Há alguém caído à frente.\n\nVocê se aproxima lentamente.\n\nA pessoa usa suas roupas. Seu equipamento. Seu rosto.\n\nVocê observa seu próprio corpo imóvel.\n\nEntão os olhos se abrem.\n\nSua própria voz sai da boca:\n\n— Demorou bastante.\n\nO corpo inspira profundamente.\n\n— Agora é a minha vez.`,choices:[['Impedir que ele se levante','Perguntar o que ele quer']],resolutions:[`Você o segura. Ele segura você exatamente da mesma forma, como um espelho com força própria.`,`— Continuar de onde você parou.`]},
    {id:'vozes',title:'As Vozes Debatem',text:`Duas vozes começam a discutir dentro da sua cabeça.\n\n— Agora.\n— Ainda é cedo.\n— Ele está fraco.\n— Ele sempre fica fraco.\n\nVocê tenta interrompê-las. As duas se calam.\n\nDepois de alguns segundos, uma delas pergunta:\n\n— Você ouviu isso?\n\nA outra responde:\n\n— Sim.\n\nPausa.\n\n— Então ele também consegue nos ouvir.`,choices:[['Perguntar quem são','Tentar expulsá-las da mente']],resolutions:[`— Ele ainda acha que nós somos duas.`,`As duas começam a rir simultaneamente com a sua própria voz.`]},
    {id:'canto',title:'A Coisa no Canto do Olho',text:`Há alguma coisa acompanhando você.\n\nEla só aparece no limite da visão. Quando olha diretamente, desaparece.\n\nVocê tenta surpreendê-la. Nada.\n\nOlha para frente novamente. Agora está mais próxima.\n\nVocê vira depressa. Nada.\n\nQuando retorna o olhar, uma voz sussurra:\n\n— Continue fazendo isso. Está funcionando.`,choices:[['Fechar os olhos','Fixar os olhos no ponto onde ela aparece']],resolutions:[`— Muito melhor. A voz vem de perto demais.`,`Você percebe que existe alguma coisa entre você e o ponto que estava tentando observar.`]},
    {id:'todos',title:'Todos São Você',text:`Uma pessoa passa por você.\n\nEla tem seu rosto.\n\nOutra aparece. Também tem seu rosto.\n\nEntão outra. E outra.\n\nTodas são você. Nenhuma parece surpresa.\n\nUma delas para. Observa você cuidadosamente.\n\n— Este acha que é o original.\n\nAs outras começam a rir.`,choices:[['Perguntar qual deles é o original','Escolher um deles e confrontá-lo']],resolutions:[`Todos apontam simultaneamente para outra pessoa. Nenhum aponta para você.`,`Seu duplo sorri: — Eu fiz isso também na primeira vez.`]},
    {id:'pensamento',title:'O Pensamento Estranho',text:`Um pensamento surge em sua mente:\n\n*Não olhe para trás.*\n\nVocê sente imediatamente que aquele pensamento não pertence a você.\n\nOutro aparece:\n\n*Ele percebeu.*\n\nDepois outro:\n\n*Finja que somos pensamentos dele.*\n\nVocê tenta esvaziar a mente. Por alguns instantes funciona.\n\nEntão surge uma última frase:\n\n*Muito melhor, {NOME}. Agora podemos conversar.*`,choices:[['Responder mentalmente','Tentar pensar em absoluto silêncio']],resolutions:[`*Ele respondeu.* Outra presença pensa: *Então já conseguimos atravessar.*`,`*Ele está ouvindo.*\n\n*Finja que fomos embora.*`]},
    {id:'realidade',title:'A Realidade Errada',text:`Tudo parece perfeitamente normal.\n\nEssa é a parte mais perturbadora.\n\nNenhuma voz. Nenhuma sombra. Nenhuma figura impossível.\n\nVocê respira fundo. Talvez tenha passado.\n\nEntão uma voz dentro da sua cabeça ri.\n\n— Engraçado, {NOME}. Você realmente acha que esta é a realidade?`,choices:[['Ignorar a voz e seguir em frente','Perguntar o que é real']],resolutions:[`— Ótimo. É sempre mais fácil quando você coopera.`,`— Qual das vezes?`]},
  ];

  function freshSanityRuntime(){return {majorCooldown:0,lastRealSectionId:null,choiceImmunitySectionId:null,activeEpisode:null,illusionLoopCount:0,recentIllusions:[],pendingCritical:null,sectionIncidentToken:0,sectionIncidentRolledId:null,processingCritical:false,illusoryCombat:null,illusionView:null};}
  function ensureSanityRuntime(){if(!appState.sanityRuntime||typeof appState.sanityRuntime!=='object')appState.sanityRuntime=freshSanityRuntime();const r=appState.sanityRuntime,base=freshSanityRuntime();for(const [k,v] of Object.entries(base))if(r[k]===undefined)r[k]=v;if(!Array.isArray(r.recentIllusions))r.recentIllusions=[];return r;}
  function resetSanityRuntime(){appState.sanityRuntime=freshSanityRuntime();return appState.sanityRuntime;}
  function sanityRuntimeForSave(){const r=ensureSanityRuntime();return {majorCooldown:Math.max(0,Number(r.majorCooldown)||0),lastRealSectionId:r.lastRealSectionId||null,choiceImmunitySectionId:r.choiceImmunitySectionId||null,recentIllusions:(r.recentIllusions||[]).slice(-6)};}
  function restoreSanityRuntime(saved){const r=resetSanityRuntime(),src=saved&&typeof saved==='object'?saved:{};r.majorCooldown=Math.max(0,Number(src.majorCooldown)||0);r.lastRealSectionId=src.lastRealSectionId||appState.sectionId||null;r.choiceImmunitySectionId=src.choiceImmunitySectionId||null;r.recentIllusions=Array.isArray(src.recentIllusions)?src.recentIllusions.slice(-6):[];return r;}
  function sanityValue(){return Number(appState.player?.magic)||0;}
  function sanityRandom(){try{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296;}catch{return Math.random();}}
  function sanityPick(list){return list?.length?list[Math.floor(sanityRandom()*list.length)]:null;}
  function sanityDie(sides=6){return 1+Math.floor(sanityRandom()*Math.max(1,sides));}
  function sanityIncidentEligible(){return !!(appState.book&&appState.player&&appState.player.stamina>0&&appState.adventureStarted&&!appState.editor&&!appState.premonition&&!adventureEnded()&&!appState.deathFlowActive&&!appState.deathPresentationPending);}
  function sanityOverlayVisible(){return !el('sanityOverlay')?.classList.contains('hidden');}
  function sanityBusySurface(){return sanityOverlayVisible()||!el('rewardOverlay')?.classList.contains('hidden')||!el('dreamOverlay')?.classList.contains('hidden')||!el('diceOverlay')?.classList.contains('hidden')||!!document.querySelector('dialog[open]')||appState.pageTurning||appState.fxBusy||appState.temporalBusy||appState.sleepBusy||appState.hungerBusy||appState.quickCombatBusy;}
  function sanityMajorAllowed(){const r=ensureSanityRuntime();return sanityIncidentEligible()&&!r.activeEpisode&&r.majorCooldown<=0;}
  function markSanityMajorIncident(){const r=ensureSanityRuntime();r.majorCooldown=3;r.choiceImmunitySectionId=appState.sectionId||null;}
  function changeSanity(delta,source=''){const p=appState.player;if(!p)return 0;const d=Number(delta)||0,before=Number(p.magic)||0;if(!d)return 0;p.magic=d>0?Math.min(Math.max(0,Number(p.initialMagic)||0),before+d):before+d;const actual=p.magic-before;if(!ensureSanityRuntime().activeEpisode&&actual<0){const r=ensureSanityRuntime();r.pendingCritical=p.magic<0?'rupture':p.magic===0?'collapse':r.pendingCritical;if(r.pendingCritical)scheduleSanityCritical();}return actual;}
  function scheduleSanityCritical(delay=120){const r=ensureSanityRuntime();if(!r.pendingCritical||r.processingCritical||r.activeEpisode)return;setTimeout(()=>processSanityPendingCritical(),Math.max(40,delay));}
  async function processSanityPendingCritical(){const r=ensureSanityRuntime();if(r.processingCritical||r.activeEpisode||!r.pendingCritical||!appState.player)return;if(sanityBusySurface()){scheduleSanityCritical(180);return;}const kind=sanityValue()<0?'rupture':sanityValue()===0?'collapse':null;if(!kind){r.pendingCritical=null;return;}r.processingCritical=true;r.pendingCritical=null;try{if(kind==='rupture')await triggerSanityRupture();else await triggerSanityCollapse();}finally{r.processingCritical=false;}}

  function showSanityOverlay({icon='🧠',title='SANIDADE BAIXA',headline='',detail='',story='',actions=[{id:'continue',label:'Continuar',kind:'primary'}],episode=false}={}){
    return new Promise(resolve=>{primeAudio();const overlay=el('sanityOverlay'),card=el('sanityCard'),box=el('sanityActions');if(!overlay||!card||!box){resolve(actions[0]?.id||'continue');return;}card.classList.toggle('episode',!!episode);el('sanityIcon').textContent=icon;el('sanityTitle').textContent=title;el('sanityHeadline').textContent=headline;const detailBox=el('sanityDetail');detailBox.textContent=detail;detailBox.classList.toggle('hidden',!detail);const storyBox=el('sanityStory');storyBox.innerHTML=story?renderMarkdownText(heroText(story)):'';storyBox.classList.toggle('hidden',!story);box.innerHTML='';box.classList.toggle('one',actions.length<=1);let settled=false;const finish=id=>{if(settled)return;settled=true;overlay.classList.add('hidden');box.innerHTML='';storyBox.innerHTML='';card.classList.remove('episode');if(appState.readingAssistEnabled)scheduleVoiceCycle(true,160);resolve(id);};for(const a of actions){const b=document.createElement('button');b.type='button';b.className=a.kind==='danger'?'danger-btn':a.kind==='secondary'?'secondary-btn':'primary-btn';b.textContent=a.label;b.onclick=()=>finish(a.id);box.appendChild(b);}overlay.classList.remove('hidden');tone(210,.12,0,'triangle',.035);tone(330,.16,.08,'sine',.025);if(navigator.vibrate)navigator.vibrate([22,35,22]);if(appState.readingAssistEnabled)scheduleVoiceCycle(true,90);});
  }
  function showSanityMoment(opts={}){return showSanityOverlay({...opts,episode:false});}
  async function sanityWhisper(){const phrase=heroText(sanityPick(SANITY_WHISPERS)||'{NOME}, você está ouvindo?');await showSanityMoment({icon:'👂',title:'SANIDADE BAIXA',headline:'UMA VOZ NA SUA CABEÇA',detail:`“${phrase}”`,actions:[{id:'continue',label:'Continuar'}]});}
  async function sanityDistortion(){const r=ensureSanityRuntime();if(r.activeEpisode)return;const classes=['sanity-distort-shake','sanity-distort-invert','sanity-distort-double','sanity-distort-drift','sanity-distort-breathe'],cls=sanityPick(classes),notice='Sua baixa sanidade começa a afetar sua percepção.';r.activeEpisode='distortion';document.body.classList.add(cls,'sanity-perception-active','sanity-perception-notice');try{if(appState.readingAssistEnabled)queueVoiceDynamic(notice);await sleep(2300);}finally{document.body.classList.remove(cls,'sanity-perception-active');setTimeout(()=>document.body.classList.remove('sanity-perception-notice'),1500);r.activeEpisode=null;if(r.pendingCritical)scheduleSanityCritical(100);}}
  async function triggerSanityMinor(){if(!sanityIncidentEligible()||ensureSanityRuntime().activeEpisode)return;if(sanityRandom()<.5)await sanityWhisper();else await sanityDistortion();}

  function noteSanityRealSectionEntry(id,previousId=null){const r=ensureSanityRuntime();if(!id||appState.editor)return;if(r.lastRealSectionId&&id!==r.lastRealSectionId&&r.majorCooldown>0)r.majorCooldown--;r.lastRealSectionId=id;r.sectionIncidentRolledId=null;r.sectionIncidentToken++;scheduleSanitySectionIncident(id,r.sectionIncidentToken,previousId);}
  function scheduleSanitySectionIncident(id,token=ensureSanityRuntime().sectionIncidentToken,_previousId=null){setTimeout(async function attempt(){const r=ensureSanityRuntime();if(token!==r.sectionIncidentToken||appState.sectionId!==id||!sanityIncidentEligible())return;const v=sanityValue();if(v<=0){r.pendingCritical=v<0?'rupture':'collapse';scheduleSanityCritical();return;}if(v>4||r.sectionIncidentRolledId===id)return;if(sanityBusySurface()||!allCombatsResolved()){setTimeout(attempt,420);return;}r.sectionIncidentRolledId=id;try{if(v===4){if(sanityRandom()<.15)await sanityWhisper();return;}if(v===3){if(sanityRandom()<.25)await triggerSanityMinor();return;}if(v===2){if(sanityMajorAllowed()&&sanityRandom()<.20){await triggerSanityIllusion();return;}if(sanityRandom()<.25)await triggerSanityMinor();return;}if(v<=1){if(sanityMajorAllowed()&&sanityRandom()<.35){const roll=sanityRandom();if(roll<.45)await triggerSanityIllusion();else if(roll<.80)await triggerSanityIllusoryCombat();else await triggerSanityCompulsion();return;}if(sanityRandom()<.40)await triggerSanityMinor();}}catch(err){console.error('Falha em incidente de SANIDADE',err);ensureSanityRuntime().activeEpisode=null;}},520);}

  function pickSanityIllusion(){const r=ensureSanityRuntime(),recent=new Set((r.recentIllusions||[]).slice(-6)),pool=SANITY_ILLUSIONS.filter(x=>!recent.has(x.id)),def=sanityPick(pool.length?pool:SANITY_ILLUSIONS);if(def){r.recentIllusions=[...(r.recentIllusions||[]).filter(id=>id!==def.id),def.id].slice(-6);}return def;}
  async function showReturnToReality(extra='Nada ocorrido durante o episódio alterou a realidade.'){await showSanityMoment({icon:'🫧',title:'VOLTANDO À REALIDADE',headline:'FOI UMA ILUSÃO',detail:`Sua percepção da realidade falhou por alguns instantes.\n\n${extra}\n\nSANIDADE: ${sanityValue()}`,actions:[{id:'continue',label:'Retomar a aventura'}]});}
  function sanityIllusionSection(def,text,sectionId){const labels=def?.choices?.[0]||['Continuar','Esperar'];return {id:sectionId,image:'',music:'',climate:'',lighting:null,dialogue:false,dialogueName:'',npc:null,mods:[],knowledges:[],books:[],treasure:null,trades:[],commerceName:'Comércio',commerceBudget:'@MOEDA',commerceRequireZero:false,commerce:[],tempos:[],states:[],text:text||'',ending:false,choices:labels.map((label,index)=>({type:'goto',text:label,target:sectionId,sanityIllusionChoice:true,sanityChoiceIndex:index}))};}
  function sanityIllusionVariant(view){const def=view?.def;if(!def)return '';return def.loop?(def.variants[Math.min(ensureSanityRuntime().illusionLoopCount,def.variants.length-1)]||def.variants[0]):def.text;}
  function activateSanityIllusionView(view){if(!view?.realSectionId||!appState.book?.sections)return;appState.book.sections[view.realSectionId]=sanityIllusionSection(view.def,sanityIllusionVariant(view),view.realSectionId);appState.effects=[];appState.appliedSectionEffects=[];appState.combats=[];appState.activeCombatIndex=0;appState.combat=null;appState.bookSubpageIndex=0;appState.bookSubpageCount=1;appState.bookPaginationPages=[];appState.bookPaginationSourceHtml='';appState.bookPaginationSourceSectionId=view.realSectionId;renderAll();}
  function prepareSanityIllusionReturn(view){if(!view?.realSectionId||!appState.book?.sections)return;appState.book.sections[view.realSectionId]=view.realSection;appState.bookSubpageIndex=0;appState.bookSubpageCount=1;appState.bookPaginationPages=[];appState.bookPaginationSourceHtml='';appState.bookPaginationSourceSectionId=view.realSectionId;renderAll();}
  function restoreSanityIllusionReality(view){if(!view)return;if(appState.book?.sections&&view.realSectionId)appState.book.sections[view.realSectionId]=view.realSection;restoreIllusoryCombatSnapshot(view.snapshot);}
  async function chooseSanityIllusion(c,index){const r=ensureSanityRuntime(),view=r.illusionView;if(r.activeEpisode!=='illusion'||!view)return;const def=view.def,idx=Number.isFinite(Number(c?.sanityChoiceIndex))?Number(c.sanityChoiceIndex):Math.max(0,Number(index)||0);if(def.loop&&idx===def.trap){r.illusionLoopCount++;await turnBookPage(()=>activateSanityIllusionView(view),c);return;}await turnBookPage(()=>prepareSanityIllusionReturn(view),c);restoreSanityIllusionReality(view);r.illusionView=null;r.activeEpisode=null;r.illusionLoopCount=0;await showReturnToReality();renderAll();view.resolve?.(true);}
  async function triggerSanityIllusion(){if(!sanityMajorAllowed())return false;const r=ensureSanityRuntime(),def=pickSanityIllusion();if(!def)return false;markSanityMajorIncident();const realSectionId=appState.sectionId,realSection=appState.book?.sections?.[realSectionId],snapshot=captureIllusoryCombatSnapshot();if(!realSection)return false;r.activeEpisode='illusion';r.illusionLoopCount=0;const view={def,realSectionId,realSection,snapshot,resolve:null};r.illusionView=view;try{await turnBookPage(()=>activateSanityIllusionView(view),null,false?{seed:`sanity-illusion-${def.id}-${Date.now()}`} : null);return await new Promise(resolve=>{view.resolve=resolve;});}catch(err){console.error('Falha ao apresentar seção ilusória',err);restoreSanityIllusionReality(view);r.illusionView=null;r.activeEpisode=null;r.illusionLoopCount=0;renderAll();return false;}}

  function sanityProtectedItemKeys(){const out=new Set();for(const id of appState.book?.order||[]){const sec=appState.book?.sections?.[id];for(const c of sec?.choices||[])for(const r of c.requirements||[])if(!/^(?:ESTADO|CLASSE)\s*:/i.test(String(r.item||'')))out.add(itemMeta(r.item).key);}return out;}
  function sanityDiscardCandidates(){const p=appState.player,protectedKeys=sanityProtectedItemKeys();return (p?.items||[]).filter(raw=>!isGoldItem(raw)&&!protectedKeys.has(itemMeta(raw).key));}
  function applySanityRealConsequence(){const p=appState.player;if(!p)return {kind:'none',detail:'O episódio passa sem deixar uma consequência material.'};const candidates=[];if(sanityDiscardCandidates().length)candidates.push('item');if(goldCount()>0)candidates.push('money');candidates.push('life');const kind=sanityPick(candidates);if(kind==='item'){const raw=sanityPick(sanityDiscardCandidates()),meta=itemMeta(raw);removeOneItem(raw);return {kind,detail:`Item perdido: ${meta.name}.`,headline:meta.name.toUpperCase(),icon:'🗑️'};}if(kind==='money'){const loss=Math.min(goldCount(),sanityDie(6));removeQuantity('Ouro',loss);return {kind,detail:`Você se desfez de ${loss} ${currencyName()}.`,headline:`−${loss} ${currencyName()}`,icon:'🪙'};}const loss=Math.min(Math.max(0,p.stamina),Math.ceil(sanityDie(6)/2));if(loss>0)spendEnergy(loss);return {kind:'life',detail:`Durante o episódio, você feriu a si mesmo e perdeu ${loss} VIDA.`,headline:`−${loss} VIDA`,icon:'🩸'};}
  async function triggerSanityCompulsion(){if(!sanityMajorAllowed())return false;const r=ensureSanityRuntime();markSanityMajorIncident();r.activeEpisode='compulsion';const before=captureState();pushHistory(before);try{const result=applySanityRealConsequence();await showSanityMoment({icon:result.icon||'🧠',title:'COMPULSÃO — SANIDADE CRÍTICA',headline:result.headline||'VOCÊ PERDE O CONTROLE',detail:`Por alguns instantes, você age contra a própria intenção.\n\n${result.detail}\n\nEsta consequência é real.`,actions:[{id:'continue',label:'Continuar'}]});renderAll();return true;}finally{r.activeEpisode=null;}}

  function captureIllusoryCombatSnapshot(){return {state:captureState(),history:deepClone(appState.history||[]),sectionCheckpoint:deepClone(appState.sectionCheckpoint||null),visitedSectionIds:deepClone(appState.visitedSectionIds||[]),temporalQueue:deepClone(appState.temporalQueue||[]),temporalBusy:!!appState.temporalBusy};}
  function restoreIllusoryCombatSnapshot(pack){if(!pack)return;appState.history=deepClone(pack.history||[]);appState.sectionCheckpoint=deepClone(pack.sectionCheckpoint||null);appState.visitedSectionIds=deepClone(pack.visitedSectionIds||[]);appState.temporalQueue=deepClone(pack.temporalQueue||[]);appState.temporalBusy=false;restoreState(pack.state);}
  async function triggerSanityIllusoryCombat(){if(!sanityMajorAllowed())return false;const r=ensureSanityRuntime();markSanityMajorIncident();r.activeEpisode='illusoryCombat';const name=sanityPick(SANITY_MONSTERS),heroSkill=Math.max(1,Math.round(Number(effectiveHeroSkill())||7)),skill=Math.max(1,heroSkill+(sanityDie(3)-2)),stamina=4+sanityDie(6),snapshot=captureIllusoryCombatSnapshot(),c=runtimeCombat({name,skill,stamina});c.sanityIllusion=true;c.lootCollected=true;r.illusoryCombat={snapshot,realSectionId:appState.sectionId,name};appState.combats=[c];appState.activeCombatIndex=0;appState.combat=c;await showSanityMoment({icon:'👁️',title:'SANIDADE CRÍTICA',headline:`${name.toUpperCase()} SURGE`,detail:'Sua percepção vacila. Uma presença impossível bloqueia o caminho e parece absolutamente real.',actions:[{id:'fight',label:'Enfrentar'}]});renderAll();if(quickCombatEnabled())scheduleQuickCombatResolution(220);return true;}
  async function waitSanityFxIdle(limit=2600){const start=Date.now();while((appState.fxBusy||appState.fxQueue?.length)&&Date.now()-start<limit)await sleep(90);}
