  function treasureRewardFor(total){const table={2:{headline:'Nada',detail:'O baú guarda apenas poeira antiga.',icon:'🕸️'},3:{headline:'Provisão ×1',detail:'Uma refeição ainda aproveitável.',icon:'🥖',provisions:1},4:{headline:`${currencyName()} ×10`,detail:`10 ${currencyName()} entram no seu equipamento.`,icon:'🪙',item:'Ouro',qty:10},5:{headline:'Talismã da sorte',detail:'+1 FORTUNA.',icon:'🍀',item:'Talismã da sorte',qty:1,stat:'luck',delta:1},6:{headline:'Arma Lendária',detail:'+1 APTIDÃO.',icon:'⚔️',item:'Arma Lendária',qty:1,stat:'skill',delta:1},7:{headline:'Poção Maravilhosa',detail:'Pode restaurar o poder especial da sua classe depois que ele for usado.',icon:'✨',item:'Poção Maravilhosa',qty:1},8:{headline:'Poção da Cura',detail:'Quando usada, recupera toda a sua VIDA.',icon:'🧪',item:'Poção da Cura',qty:1},9:{headline:`${currencyName()} ×20`,detail:`20 ${currencyName()} entram no seu equipamento.`,icon:'🪙',item:'Ouro',qty:20},10:{headline:'Provisão ×2',detail:'Duas novas refeições para a jornada.',icon:'🥖',provisions:2},11:{headline:'Corda',detail:'Uma corda resistente.',icon:'🪢',item:'Corda',qty:1},12:{headline:'Tocha',detail:'Uma tocha pronta para iluminar o caminho.',icon:'🔥',item:'Tocha',qty:1}};return table[total];}
  function applyTreasureReward(reward){if(!reward)return;if(reward.provisions)addQuantity('Provisão',reward.provisions);if(reward.item)addQuantity(reward.item,reward.qty||1);if(reward.stat)appState.player[reward.stat]+=reward.delta||0;}

