    if(source==='combat')setActiveCombat(combatIndex);const combatRef=source==='combat'?appState.combat:null;const sec=appState.book.sections[appState.sectionId],key=appState.sectionId;if(source==='section'&&appState.player.openedTreasures[key])return;const before=captureState();let reward;
    if(source==='combat'&&combatRef&&(cleanText(combatRef.loot)||(combatRef.stolenLoot||[]).length)){const labels=await collectConfiguredCombatLoot(combatRef);pushHistory(before);combatRef.lootCollected=true;combatRef.lootRecord=labels.length?labels:['Espólio recuperado'];await showRewardMoment({kind:'treasure',title:'ESPÓLIO COLETADO',headline:labels.join(' · ')||'Espólio recuperado',detail:`Você recolhe o que ${combatRef.name} carregava.`,icon:'💰'});renderAll();return;}
