  function combatEventThreshold(ev){return Math.max(1,rollDiceExpression(ev.thresholdExpr||'1',{min:1,max:999}));}
  function combatEventMetricReached(trigger,ev,c,rt){const threshold=Math.max(1,Number(ev._resolvedThreshold)||combatEventThreshold(ev));if(trigger==='AFTER_HITS_DEALT')return (Number(c?.hitsDealt)||0)>=threshold;if(trigger==='AFTER_HITS_TAKEN')return (Number(c?.hitsTaken)||0)>=threshold;if(trigger==='AFTER_WINS_CONSEC')return (Number(c?.consecutiveWins)||0)>=threshold;if(trigger==='AFTER_LOSSES_CONSEC')return (Number(c?.consecutiveLosses)||0)>=threshold;if(trigger==='AT_LIFE_PERCENT'){const pct=100*Math.max(0,Number(c?.stamina)||0)/Math.max(1,Number(c?.maxStamina)||1);return pct<=Math.min(100,threshold);}if(trigger==='REMAINING_X')return multipleEnemiesAlive(c)<=threshold;return true;}
  async function triggerEncounterEvents(trigger,{combat=null,round=null,scopeMode='',silent=false}={}){const rt=appState.encounterRuntime;if(!rt?.events?.length)return false;for(const ev0 of rt.events){const ev=normalizeCombatEvent(ev0);if(ev.trigger!==trigger)continue;if(scopeMode==='ALL'&&ev.scope!=='ALL')continue;if(scopeMode==='OPPONENT'&&ev.scope!=='OPPONENT')continue;let eventCombat=combat;if(ev.scope==='OPPONENT'){if(!eventCombat||eventCombat.opponentId!==ev.opponentId){if(['FIRST_ROUND','AFTER_ROUNDS','RANDOM','AFTER_DEFEAT_TIME'].includes(trigger))eventCombat=(appState.combats||[]).find(x=>x.opponentId===ev.opponentId)||null;else continue;}if(!eventCombat)continue;}const key=encounterEventKey(ev,eventCombat);if(rt.fired[key])continue;if(!rt.schedules)rt.schedules={};if(trigger==='AFTER_ROUNDS'){if(!Number.isFinite(rt.schedules[key]))rt.schedules[key]=combatEventThreshold(ev);if((round??rt.round)<rt.schedules[key])continue;}if(trigger==='RANDOM'&&1+Math.floor(Math.random()*ev.chance)!==1)continue;if(['AFTER_HITS_DEALT','AFTER_HITS_TAKEN','AFTER_WINS_CONSEC','AFTER_LOSSES_CONSEC','AT_LIFE_PERCENT','REMAINING_X'].includes(trigger)){if(!Number.isFinite(rt.schedules[key]))rt.schedules[key]=combatEventThreshold(ev);ev._resolvedThreshold=rt.schedules[key];if(!combatEventMetricReached(trigger,ev,eventCombat,rt))continue;}if(trigger==='AFTER_DEFEAT_TIME'){const now=Number(ensureTimeState()?.gameMinutes)||0;if(!Number.isFinite(rt.schedules[key])){const amount=combatEventThreshold(ev),minutes=ev.delayUnit==='TURNS'?amount*30:amount;rt.schedules[key]=now+minutes;continue;}if(now<rt.schedules[key])continue;}rt.fired[key]=true;if(ev.message&&!silent)await showRewardMoment({kind:'special',title:'EVENTO DO COMBATE',headline:(eventCombat?.name||'O ENCONTRO').toUpperCase(),detail:ev.message,icon:'⚔️',image:eventCombat?.image||''});await applyCombatEventFx(ev,eventCombat);if(ev.result==='END'&&!ev.targetSection)resolveWholeEncounter('evento',{loot:false});if(ev.targetSection){await navigateEncounterEvent(ev);return true;}}return false;}
  async function processDelayedCombatEvents(){if(!appState.encounterRuntime)return;for(const c of appState.combats||[])if(c.won)await triggerEncounterEvents('AFTER_DEFEAT_TIME',{combat:c,silent:false});}
  function resolveWholeEncounter(outcome='evento',{loot=false}={}){if(appState.encounterRuntime){appState.encounterRuntime.status='resolved';appState.encounterRuntime.outcome=outcome;}for(const c of appState.combats||[]){if(!c.won){c.won=true;c.outcome=outcome;c.started=false;c.pendingLuck=null;c.lootCollected=!loot;restoreAgourento(c);revertCombatScopedEffects(c);}}}
  function syncEncounterResolution(){const rt=appState.encounterRuntime;if(!rt)return;if((appState.combats||[]).some(c=>c.mercyPending))return;if((appState.combats||[]).every(c=>!combatEngaged(c))){if(rt.status!=='resolved')clearHeroCombatMagic(appState.combat);rt.status='resolved';rt.outcome=rt.outcome||'resolvido';}}
  function combatGroupMembers(c){return (appState.combats||[]).filter(x=>(c?.opponentId&&x.opponentId===c.opponentId)||x===c);}
  function combatGroupDefeatedByHero(c){const g=combatGroupMembers(c);return g.length>0&&g.every(x=>x.won&&x.outcome==='vitoria_heroi');}
  async function advanceEncounterTimeIfResolved(){const rt=appState.encounterRuntime;if(!rt||rt.status!=='resolved'||rt.timeAdvanced)return;if((appState.combats||[]).some(c=>c.mercyPending||(c.rebirthPending&&!c.rebirthPrevented)))return;rt.timeAdvanced=true;await advanceAdventureTurns(2,{animate:true,countAwake:true});await waitTemporalQueue();}
  function combatNarrativeMomentKey(c,kind='intro'){return `combat-moment:${kind}:${c?.opponentId||c?.baseName||c?.name||'opponent'}`;}
  function combatHasCustomIntro(c){const text=cleanText(c?.message||'');if(!text)return false;const tpl=COMBAT_TEMPLATE_MAP.get(cleanText(c?.templateId||''));const inherited=cleanText(tpl?.message||'');return !tpl||!inherited||voiceNormalize(text)!==voiceNormalize(inherited);}
  function combatTemplateIntroFlavor(c){if(combatHasCustomIntro(c))return'';const tpl=COMBAT_TEMPLATE_MAP.get(cleanText(c?.templateId||''));return cleanText(tpl?.message||'');}
  function combatCanSpeak(c){if(!c||c.type==='ANIMAL'||String(c.intelligence||'NENHUMA').toUpperCase()==='NENHUMA')return false;return c.type==='HUMANOIDE'||['MEDIA','ALTA'].includes(String(c.intelligence||'').toUpperCase());}
  function combatLeaderAlive(c){if(!c?.leader)return false;const alive=combatAliveMembers(c);return alive.some(m=>m?.leader)||(!c.members?.some?.(m=>m?.leader)&&alive.length>0);}
  function combatVisibleSpecialtyCues(c){const set=new Set(c?.specialties||[]),cues=[];if(set.has('VOADOR'))cues.push('aéreo');if(set.has('ESPINHUDO'))cues.push('espinhos');if(set.has('CAMUFLADO'))cues.push('camuflado');if(set.has('ESCORREGADIO'))cues.push('escorregadio');if(set.has('GRUDENTO'))cues.push('grudento');return cues;}
  function combatMomentum(c){const hero=Math.max(0,Number(appState.player?.stamina)||0)/Math.max(1,Number(appState.player?.initialStamina)||1),enemy=Math.max(0,Number(c?.stamina)||0)/Math.max(1,Number(c?.maxStamina)||1),delta=hero-enemy;if(delta>.18)return'hero-ahead';if(delta<-.18)return'opponent-ahead';return'even';}
  function combatNarrativeFacts(c,moment='intro'){ensureCombatRuntime(c);const alive=Math.max(1,multipleEnemiesAlive(c)),multiple=Math.max(1,Number(c.multiple)||1);return {moment,name:cleanText(c.baseName||c.name||'Oponente')||'Oponente',displayName:combatDisplayName(c),type:String(c.type||'HUMANOIDE').toUpperCase(),reaction:String(c.reaction||'HOSTIL').toUpperCase(),intelligence:String(c.intelligence||'MEDIA').toUpperCase(),morale:String(c.morale||'NORMAL').toUpperCase(),multiple,alive,group:multiple>1,leader:combatLeaderAlive(c),speech:combatCanSpeak(c),momentum:combatMomentum(c),cues:combatVisibleSpecialtyCues(c)};}
  function combatNarrativeMomentSpec(c,kind='intro',{reason='INCAPACITATED'}={}){
    const f=combatNarrativeFacts(c,kind),name=f.name,groupName=f.group?`o grupo de ${name}`:name,cue=f.cues[0]||'',cuePhrase=cue==='aéreo'?'mantém-se acima do alcance imediato':cue==='espinhos'?'exibe uma superfície coberta de espinhos':cue==='camuflado'?'deixa os contornos se misturarem ao ambiente':cue==='escorregadio'?'se move com uma fluidez difícil de acompanhar':cue==='grudento'?'exibe uma superfície úmida que adere ao que toca':'';
    if(kind==='intro'){
      let templates=[];
      if(f.group){
        if(f.leader)templates=[`O grupo de ${name} se abre diante de você. Um deles toma a frente, e os demais acompanham seu movimento.`,`Os ${f.alive} ${name} ocupam o espaço ao redor. Um deles conduz a aproximação enquanto os outros procuram ângulos diferentes.`];
        else if(f.morale==='COVARDE')templates=[`Os ${f.alive} ${name} avançam juntos, embora alguns olhares continuem procurando espaço para recuar.`,`O grupo de ${name} cerca sua posição com coragem irregular; a formação aperta e hesita ao mesmo tempo.`];
        else templates=[`Os ${f.alive} ${name} se espalham diante de você e transformam o espaço em uma ameaça coletiva.`,`O grupo de ${name} abre a formação, cada integrante procurando um ângulo diferente para entrar na luta.`];
      }else if(f.type==='ANIMAL')templates=[`${name} baixa o corpo e mede a distância antes de avançar.`,`A postura de ${name} muda de uma vez; músculos e atenção se voltam inteiramente para você.`];
      else if(f.intelligence==='NENHUMA')templates=[`${name} abandona a imobilidade e avança com uma intenção simples e direta.`,`A presença de ${name} ganha movimento e ocupa o caminho diante de você.`];
      else if(f.intelligence==='ALTA')templates=[`${name} observa sua postura antes de se comprometer com o primeiro movimento.`,`Antes de avançar, ${name} mede sua posição com atenção e escolhe a distância do confronto.`];
      else templates=[`${name} firma a postura e transforma a tensão da cena em confronto.`,`O olhar de ${name} se fixa em você enquanto a distância entre vocês começa a desaparecer.`];
      if(cuePhrase)templates=templates.map(t=>`${t} ${name} ${cuePhrase}.`);const flavor=combatTemplateIntroFlavor(c);if(flavor){if(f.speech)templates=templates.map(t=>`${t} “${flavor}”`);else templates=[flavor,...templates.map(t=>`${t} ${flavor}`)];}
      return {family:'combat-intro',title:(f.group?`${name} ×${Math.max(1,f.alive)}`:f.displayName).toUpperCase(),headline:'',templates,italicDetail:true};
    }
    if(kind==='taunt'){
      let templates=[];
      if(f.speech){
        if(f.group&&f.leader){
          if(f.momentum==='hero-ahead')templates=[`O que conduz ${groupName} força um sorriso e provoca: “Ainda estamos aqui.”`,`O líder ergue a voz acima dos demais: “Vai precisar fazer melhor do que isso.”`];
          else if(f.momentum==='opponent-ahead')templates=[`O líder de ${groupName} percebe a vantagem e ri: “Está ficando fácil.”`,`Quem conduz o grupo avança meio passo e diz: “Você já começou a perder.”`];
          else templates=[`O líder de ${groupName} bate a arma contra a própria defesa: “Vamos ver quem cede primeiro.”`,`Uma voz se impõe sobre o grupo: “Continue. Quero ver até onde aguenta.”`];
        }else if(f.momentum==='hero-ahead')templates=[`${name} limpa o sangue da boca e força um sorriso. “Achou que isso bastaria?”`,`Mesmo pressionado, ${name} sustenta seu olhar. “Ainda estou de pé.”`];
        else if(f.momentum==='opponent-ahead')templates=[`${name} percebe sua dificuldade e provoca: “Continue assim. Está tornando isso fácil.”`,`A confiança de ${name} cresce. “Já sentiu como isso termina?”`];
        else templates=[`${name} mantém a guarda e provoca: “Vamos ver quem perde o ritmo primeiro.”`,`Entre um movimento e outro, ${name} solta um sorriso curto. “Ainda quer continuar?”`];
      }else if(f.group)templates=[`O grupo responde ao confronto com gritos e golpes contra armas e escudos, apertando novamente a formação.`,`Os ${f.alive} ${name} se reorganizam com ruídos agressivos e voltam a fechar o espaço ao redor.`];
      else if(f.type==='ANIMAL')templates=[`${name} recua meio passo, baixa o corpo e responde com um rugido ainda mais agressivo.`,`A fera sacode o corpo, mostra os dentes e volta a ocupar a distância do ataque.`];
      else templates=[`${name} responde ao confronto com um movimento brusco e retoma a pressão sem qualquer hesitação.`,`A criatura interrompe o avanço por um instante, reorganiza o corpo e volta a pressionar você.`];
      return {family:'combat-taunt',title:f.displayName.toUpperCase(),headline:'',templates,italicDetail:true};
    }
    if(kind==='mercy'){
      const retreat=reason==='RETREAT';let templates=[];
      if(f.group){
        if(retreat)templates=[`A formação de ${groupName} se desfaz. Os sobreviventes começam a recuar e deixam a decisão final em suas mãos.`,`Os integrantes restantes de ${groupName} quebram o cerco e procuram distância, abandonando a iniciativa do confronto.`];
        else if(f.speech)templates=[`As armas de ${groupName} baixam quase ao mesmo tempo. Uma voz se ergue entre os sobreviventes: “Chega. Nós nos rendemos.”`,`A formação se desfaz e os sobreviventes de ${groupName} cedem. “Acabou. Poupe quem restou.”`];
        else templates=[`A formação de ${groupName} se desfaz e os sobreviventes abandonam a agressão, esperando sua decisão.`,`Os sobreviventes de ${groupName} recuam juntos e deixam de oferecer resistência.`];
      }else if(f.type==='ANIMAL'){
        templates=retreat?[`${name} interrompe o ataque e começa a recuar, procurando distância entre vocês.`,`${name} abandona a investida e passa a buscar uma saída do confronto.`]:[`${name} encolhe o corpo, evita seu olhar e abandona a agressão.`,`${name} recua com o corpo baixo e deixa claro que a luta terminou para ele.`];
      }else if(f.speech){
        if(f.morale==='COVARDE'||f.intelligence==='BAIXA')templates=[`${name} deixa a defesa cair. “Espera! Chega! Eu desisto!”`,`${name} recua de uma vez. “Pare! Eu me rendo!”`];
        else if(f.intelligence==='ALTA')templates=[`${name} percebe antes de você que o confronto terminou e abaixa a arma. “Você venceu. Decida o que fará comigo.”`,`${name} interrompe a guarda com um gesto controlado. “Acabou. A próxima decisão é sua.”`];
        else templates=[`${name} deixa a arma baixar. “Acabou. Poupe minha vida.”`,`${name} perde a postura de combate e ergue as mãos. “Eu me rendo.”`];
      }else templates=[`${name} abandona a postura ofensiva e espera sua decisão.`,`A resistência de ${name} termina; a criatura permanece diante de você sem retomar o ataque.`];
      return {family:'combat-mercy',title:'MISERICÓRDIA',headline:retreat?'O CONFRONTO SE DESFAZ':'A DERROTA É ACEITA',templates,italicDetail:true};
    }
    return {family:`combat-${kind}`,title:f.displayName.toUpperCase(),headline:'',templates:[],italicDetail:true};
  }
  function combatNarrativeMomentText(c,kind='intro',options={}){const custom=cleanText(options.customText||''),spec=combatNarrativeMomentSpec(c,kind,options);if(custom)return custom;const seed=`combat-moment|${ensureBookIdentity(appState.book||{})}|${appState.sectionId}|${c?.opponentId||c?.baseName||c?.name||'opponent'}|${kind}`;return narrativeCompose({family:spec.family,templates:spec.templates,seed,context:{combat:c,kind,options}})||defaultCombatMessage(c?.type,c?.reaction,c?.intelligence);}
  async function presentCombatNarrativeMoment(c,kind='intro',options={}){ensureCombatRuntime(c);if(!c)return false;const key=combatNarrativeMomentKey(c,kind);if(combatBeatSeen(c,key))return false;const spec=combatNarrativeMomentSpec(c,kind,options),custom=kind==='intro'&&combatHasCustomIntro(c)?cleanText(c.message):'',text=combatNarrativeMomentText(c,kind,{...options,customText:custom});if(!text)return false;rememberCombatBeat(c,key);c.lastNarrativeEventRound=Math.max(Number(c.lastNarrativeEventRound)||-1,Number(c.round)||0);await showRewardMoment({kind:'special',title:spec.title,headline:spec.headline,detail:text,image:c.image,hideIcon:true,italicDetail:spec.italicDetail!==false});return true;}
  function combatInitialMessage(c){return combatHasCustomIntro(c)?cleanText(c?.message):combatNarrativeMomentText(c,'intro');}
  async function ensureCombatIntro(c){if(!c||c.introShown)return;const rt=appState.encounterRuntime,key=c.opponentId||`${c.name}|${c.groupIndex||1}`;if(rt){if(!rt.introsShown)rt.introsShown={};if(rt.introsShown[key]){c.introShown=true;return;}rt.introsShown[key]=true;for(const foe of appState.combats||[])if((foe.opponentId||'')===(c.opponentId||''))foe.introShown=true;}else c.introShown=true;await presentCombatNarrativeMoment(c,'intro');}
  async function maybePresentCombatTaunt(c,{beat=null}={}){ensureCombatRuntime(c);if(!c||c.won||c.mercyPending||!c.started||quickCombatEnabled()||appState.player?.stamina<=0||Number(c.round)<2)return false;const key=combatNarrativeMomentKey(c,'taunt');if(combatBeatSeen(c,key))return false;const r=ensureCombatSpecialRuntime(c);if(!Number.isFinite(Number(r.tauntLifeThreshold)))r.tauntLifeThreshold=.45+Math.random()*.25;if(!Number.isFinite(Number(r.tauntAttempts)))r.tauntAttempts=0;const lifeRatio=Math.max(0,Math.min(1,(Number(c.stamina)||0)/Math.max(1,Number(c.maxStamina)||1)));if(!r.tauntArmed&&lifeRatio<=r.tauntLifeThreshold&&lifeRatio>.15)r.tauntArmed=true;if(!r.tauntArmed)return false;if(beat&&['significant','spotlight'].includes(beat.importance))return false;if(Number(c.lastNarrativeEventRound)===Number(c.round))return false;r.tauntAttempts++;const chance=[.40,.65,.85,1][Math.min(3,r.tauntAttempts-1)];if(Math.random()>chance)return false;return presentCombatNarrativeMoment(c,'taunt');}
  async function maybeShowActionCombatTutorial(){const p=appState.player;if(!actionCombatEnabled()||!p||p.actionCombatTutorialSeen)return false;p.actionCombatTutorialSeen=true;await showRewardMoment({kind:'special',title:'Combate de Ação',headline:'',detail:'Observe seu oponente.\nQuando surgir 💥, toque para atacar.\nMovimento e velocidade variam com o oponente. A janela de abertura varia com sua APTIDÃO.',icon:'💥',actionTutorial:true,buttonLabel:'Entendi'});return true;}
  function ensureCombatSpecialRuntime(c){if(!c.specialRuntime)c.specialRuntime={};const r=c.specialRuntime;if(c.specialties?.includes('RAJADA')&&!Number.isFinite(r.burstIn))r.burstIn=secureDie();if(c.specialties?.includes('RESILIENTE')&&!Number.isFinite(r.resilientIn))r.resilientIn=secureDie();if(c.specialties?.includes('LADRAO')&&!Number.isFinite(r.thiefIn))r.thiefIn=secureDie();if(c.specialties?.includes('VAMPIRO')&&!Number.isFinite(r.vampGoal)){r.vampGoal=secureDie();r.vampWins=0;}if(c.specialties?.includes('VOADOR')&&!Number.isFinite(r.flyIn))r.flyIn=0;if(c.specialties?.includes('TELEPORTE')&&!Number.isFinite(r.teleportIn))r.teleportIn=secureDie()+3;if(c.specialties?.includes('ESCORREGADIO')&&!Number.isFinite(r.slipperyIn))r.slipperyIn=0;if(c.specialties?.includes('ESPINHUDO')&&!Number.isFinite(r.spinyIn))r.spinyIn=0;if(c.specialties?.includes('TREINADO')&&!Number.isFinite(r.trainedIn))r.trainedIn=secureDie();if(c.specialties?.includes('MULTIPLICADOR')&&!Number.isFinite(r.multiplierIn))r.multiplierIn=secureDie();return r;}
  function combatPresenceStore(c){if(appState.encounterRuntime){if(!appState.encounterRuntime.presenceEffects)appState.encounterRuntime.presenceEffects={};return appState.encounterRuntime.presenceEffects;}const r=ensureCombatSpecialRuntime(c);if(!r.presenceEffects)r.presenceEffects={};return r.presenceEffects;}
  function combatPresenceKey(c,specialty){return appState.encounterRuntime&&c?.opponentId?`${c.opponentId}|${specialty}`:`${c?.opponentId||c?.name||'op'}|${c?.groupIndex||1}|${specialty}`;}
  function combatGroupStillActive(c){return !!(appState.encounterRuntime&&c?.opponentId&&(appState.combats||[]).some(x=>x!==c&&!x.won&&x.opponentId===c.opponentId));}
  async function applyCombatPresencePenalty(c,specialty,key,label,amount,{stateName='',title='',icon='⚔️',silent=false}={}){if(!c?.specialties?.includes(specialty)||!(amount>0))return 0;const store=combatPresenceStore(c),id=combatPresenceKey(c,specialty);if(store[id])return 0;const before=Number(appState.player?.[key])||0,after=Math.max(0,before-amount),actual=before-after;if(actual<=0)return 0;appState.player[key]=after;store[id]={opponentId:c.opponentId||'',specialty,key,amount:actual,stateName};if(stateName)addState(stateName);if(!silent)await showRewardMoment({kind:'special',title:title||specialty,headline:`-${actual} ${label}`,detail:`O efeito permanece enquanto este grupo de ${c.baseName||c.name} estiver ativo no encontro.`,icon,image:c.image});return actual;}
  function restoreAgourento(c){if(!c)return;if(combatGroupStillActive(c))return;const store=combatPresenceStore(c),opponentId=c.opponentId||'',prefix=appState.encounterRuntime&&opponentId?`${opponentId}|`:null;for(const [id,rec] of Object.entries(store)){const same=prefix?id.startsWith(prefix):id.startsWith(`${opponentId||c.name}|${c.groupIndex||1}|`);if(!same)continue;if(rec?.amount&&rec?.key&&appState.player)appState.player[rec.key]=(Number(appState.player[rec.key])||0)+rec.amount;delete store[id];}if(c.agourentoApplied){appState.player.luck+=c.agourentoApplied;c.agourentoApplied=0;}const anyAgourento=(appState.encounterRuntime?Object.values(appState.encounterRuntime.presenceEffects||{}):Object.values(ensureCombatSpecialRuntime(c).presenceEffects||{})).some(rec=>rec?.specialty==='AGOURENTO');if(!anyAgourento)removeState('Agourado');}
  async function applyAgourento(c,{silent=false}={}){await applyCombatPresencePenalty(c,'AGOURENTO','luck','FORTUNA',1,{stateName:'Agourado',title:'☠️ AGOURENTO',icon:'☠️',silent});}
  function ensureCombatRecoveries(){const p=appState.player;if(!p)return[];if(!Array.isArray(p.combatRecoveries))p.combatRecoveries=[];return p.combatRecoveries;}
  async function applyRecoveringDebuff(c,key,statLabel,stateName,title,{silent=false}={}){const rolled=secureDie(),before=Number(appState.player[key])||0,after=Math.max(0,before-rolled),actual=before-after;appState.player[key]=after;if(actual<=0)return;addState(stateName);ensureCombatRecoveries().push({sourceId:`${c.opponentId||c.name}:${c.groupIndex||1}:${key}`,key,remaining:actual,stateName});if(!silent)await showRewardMoment({kind:'special',title,headline:`-${actual} ${statLabel}`,detail:`${stateName}. Você recuperará 1 ${statLabel} por turno até restaurar esta perda.`,icon:'🌀',image:c.image});}
  function tickCombatRecoveries(){const list=ensureCombatRecoveries();for(const rec of list){if(rec.remaining<=0)continue;const maxKey={magic:'initialMagic',luck:'initialLuck',skill:'initialSkill'}[rec.key],before=Number(appState.player[rec.key])||0,max=Number(appState.player[maxKey])||before+1;if(before<max){appState.player[rec.key]=Math.min(max,before+1);rec.remaining--;}}for(const rec of list)if(rec.remaining<=0&&!list.some(x=>x!==rec&&x.remaining>0&&stateKey(x.stateName)===stateKey(rec.stateName)))removeState(rec.stateName);appState.player.combatRecoveries=list.filter(x=>x.remaining>0);}
  async function processOpeningSpecialties({silent=false}={}){for(const c of (appState.combats||[]).filter(x=>!x.won&&(String(x.reaction).toUpperCase()==='HOSTIL'||x.started))){ensureCombatSpecialRuntime(c);await applyAgourento(c,{silent});await applyCombatPresencePenalty(c,'CAMUFLADO','skill','APTIDÃO',combatD3(),{title:'🌫️ CAMUFLADO',icon:'🌫️',silent});await applyCombatPresencePenalty(c,'PROVOCADOR','magic','SANIDADE',combatD3(),{title:'🗯️ PROVOCADOR',icon:'🗯️',silent});await applyCombatPresencePenalty(c,'SORTUDO','luck','FORTUNA',secureDie(),{title:'🍀 SORTUDO',icon:'🍀',silent});if(c.specialRuntime.openingDone)continue;c.specialRuntime.openingDone=true;if(c.specialties.includes('PERTURBADOR'))await applyRecoveringDebuff(c,'magic','SANIDADE','Perturbado','🌀 PERTURBADOR',{silent});if(c.specialties.includes('AMALDICOADOR'))await applyRecoveringDebuff(c,'luck','FORTUNA','Amaldiçoado','🕯️ AMALDIÇOADOR',{silent});if(c.specialties.includes('TOXICO'))await applyRecoveringDebuff(c,'skill','APTIDÃO','Intoxicado','☣️ TÓXICO',{silent});}}
  function randomStealableInventoryEntry(){const all=inventoryCounts().filter(e=>!isGoldItem(e.meta.raw));return all.length?all[Math.floor(Math.random()*all.length)]:null;}
  function normalizeCombatItemName(value=''){return cleanText(value).toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();}
  function combatInventoryEntryByName(name=''){const key=normalizeCombatItemName(name);return inventoryCounts().find(e=>normalizeCombatItemName(e.meta?.name)===key)||null;}
  function hasCombatNamedItem(name=''){return !!combatInventoryEntryByName(name);}
