  function markCombatEngagement(c,initiator='HERO'){if(!c)return;c.started=true;if(!c.reactionAtEngagement)c.reactionAtEngagement=String(c.reaction||'HOSTIL').toUpperCase();if(!c.combatInitiator)c.combatInitiator=initiator;}
