  function combatCurrentRoundText(c){const round=encounterRoundNumber(c),prefix=`Rodada ${round}:`,rows=(c.logs||[]).filter(x=>String(x).startsWith(prefix)).slice().reverse();return rows.length?rows.join(' · '):(c.logs?.[0]||'O inimigo bloqueia o caminho.');}
  function combatLoreFallback(c){const habitat=(c?.habitats||[]).map(x=>COMBAT_TERRAIN_LABELS[x]||x).join(', '),kind=c?.type==='ANIMAL'?'animal':c?.type==='CRIATURA'?'criatura':'humanoide';return `${c?.baseName||c?.name||'Este oponente'} é um ${kind} encontrado com frequência${habitat?` em ${habitat}`:''}. Suas características de combate refletem o ambiente e o comportamento definidos para este encontro.`;}
  function showCombatLog(c){
    const d=el('combatLogDialog'),box=el('combatLogContent');let entries=[],foes=[];
    if(c){c.loreViewed=true;const idx=(appState.combats||[]).indexOf(c);document.querySelector(`.combat[data-combat-index="${idx}"] .combat-lore-btn`)?.classList.remove('lore-pulse');}
    if(appState.encounterRuntime){foes=(appState.combats||[]);for(const foe of foes)for(const [order,text] of (foe.logs||[]).entries()){const mm=String(text).match(/^Rodada (\d+):/);entries.push({round:mm?+mm[1]:Number.POSITIVE_INFINITY,order,name:combatDisplayName(foe),text});}entries.sort((a,b)=>b.round-a.round||a.order-b.order||a.name.localeCompare(b.name,'pt-BR'));}
    else{foes=[c];entries=(c?.logs||[]).map((text,order)=>({round:Number.POSITIVE_INFINITY-order,order,name:combatDisplayName(c),text}));}
    el('combatLogTitle').textContent='📜 Sobre esse Encontro';
    const seen=new Set(),loreBlocks=[];
    for(const foe of foes){if(!foe)continue;const key=foe.opponentId||foe.baseName||foe.name;if(seen.has(key))continue;seen.add(key);const raw=cleanText(foe.lore)||combatLoreFallback(foe),paras=String(raw).split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean).slice(0,2),specialties=(foe.specialties||[]).map(k=>COMBAT_SPECIALTY_META[k]).filter(Boolean);const specialtyHtml=specialties.length?`<div class="combat-log-specialties">${specialties.map(s=>`<span class="combat-log-specialty" title="${esc(s.desc||'')}">${esc(s.label)}</span>`).join('')}</div>`:'';loreBlocks.push(`<div class="combat-log-lore"><strong>${esc(foe.baseName||foe.name)}</strong>${paras.map(p=>`<p>${esc(p)}</p>`).join('')}${specialtyHtml}</div>`);}
    const rounds=entries.map(x=>`<div class="combat-log-entry"><strong>${esc(x.name)}</strong> · ${esc(x.text)}</div>`).join('')||'<div class="empty-state">Suas ações no combate serão registradas aqui</div>';
    box.innerHTML=loreBlocks.join('')+rounds;if(!d.open)d.showModal();
  }
  function parseCombatLootEntries(raw=''){return String(raw||'').split(/[;\n]+/).map(x=>x.trim()).filter(Boolean);}
  async function collectConfiguredCombatLoot(c){const specs=parseCombatLootEntries(c.loot),labels=[];for(const spec of specs){if(/^TESOURO$/i.test(spec)){const reward=treasureRewardFor(secureDie()+secureDie());applyTreasureReward(reward);labels.push(reward.headline);continue;}const m=spec.match(/^(.+?)\s+(MOEDA|PROVISÃO|PROVISAO)$/i);if(m){const qty=rollDiceExpression(m[1],{min:1,max:999}),kind=m[2].toUpperCase();if(kind==='MOEDA')addQuantity('Ouro',qty,{force:true,silent:true});else addQuantity('Provisão',qty,{force:true,silent:true});labels.push(`${qty} ${kind==='MOEDA'?currencyName():'Provisão'}`);continue;}const q=spec.match(/^(\S+)\s+(.+)$/),qty=q?rollDiceExpression(q[1],{min:1,max:99}):1,item=q?q[2]:spec;addQuantity(item,qty,{force:true,silent:true});const itemName=itemMeta(item).name||item;labels.push(qty>1?`${itemName} ×${qty}`:itemName);}for(const raw of c.stolenLoot||[]){addQuantity(raw,1,{force:true,silent:true});labels.push(`${itemMeta(raw).name} (recuperado)`);}c.stolenLoot=[];return labels;}

