    knowledge:[mk('{Cultura Geral(Perícia)}','Adiciona +1 em Cultura Geral, respeitando o teto total de Perícias.'),mk('{Gramática(Perícia)}','Adiciona +1 em Gramática; conhecer Gramática reduz a leitura de Livros para 1d6 turnos.'),mk('{Roubar(Perícia)}','Adiciona +1 em Roubar; habilita roubo em comércios e soma seu valor ao teste.'),mk('{Esgueirar(Perícia)}','Adiciona +1 em Esgueirar; habilita Esgueirar-se antes do combate.'),mk('{Luta Armada(Perícia)}','Adiciona +1 em Luta Armada; habilita Ataque Surpresa e duas armas em Prontidão.'),mk('{Meditação(Perícia)}','Adiciona +1 em Meditação; cada ponto aumenta em 1 a SANIDADE recuperada ao dormir.'),mk('{Treino Mágico(Perícia)}','Adiciona +1 em Treino Mágico; habilita dois Feitiços em Prontidão e prolonga Feitiços temporários.'),mk('{Controle Arcano(Perícia)}','Adiciona +1 em Controle Arcano; falhas comuns de conjuração preservam a SANIDADE.'),mk('{Artes Ladinas(Perícia)}','Adiciona +1 em Artes Ladinas; habilita superar uma exigência de Item uma vez por jogo.'),mk('{Malabarismo(Perícia)}','Adiciona +1 em Malabarismo; habilita dois itens comuns em Prontidão.'),mk('{Espada(Perícia)}','Adiciona +1 em Espada.'),mk('{Arco e Flecha(Perícia)}','Adiciona +1 em Arco e Flecha.'),mk('{Botânica(Perícia)}','Adiciona +1 em Botânica.'),mk('{História(Perícia)}','Adiciona +1 em História.'),mk('{Matemática(Perícia)}','Adiciona +1 em Matemática e soma seu valor ao teste de Negociar com NPCs.'),mk('{Medicina(Perícia)}','Adiciona +1 em Medicina.'),mk('{Idiomas(Perícia)}','Adiciona +1 em Idiomas.'),mk('{Etiqueta(Perícia)}','Adiciona +1 em Etiqueta; revela pistas sociais no Small Talk e, em domínio maior, destaca a abordagem apropriada.'),mk('{Retórica(Perícia)}','Adiciona +1 em Retórica e em Convencer.'),mk('{Empatia(Perícia)}','Adiciona +1 em Empatia e em Comover.'),mk('{Comércio(Perícia)}','Adiciona +1 em Comércio e em Negociar.'),mk('{Jogos de Azar(Perícia)}','Adiciona +1 em Jogos de Azar e em Apostar.'),mk('{Intimidação(Perícia)}','Adiciona +1 em Intimidação e habilita Intimidar.'),mk('{Mentalismo(Perícia)}','Adiciona +1 em Mentalismo e habilita Encantar.'),mk('{Malandragem(Perícia)}','Adiciona +1 em Malandragem e habilita Ludibriar.'),mk('{Colapso Mental(Perícia)}','Zera permanentemente todas as Perícias do herói.'),mk('{Amnésia(Perícia)}','Concede +2 temporário às Perícias conhecidas por 1d6 turnos.'),mk('{Livro de Botânica(Livro)|{Botânica(Perícia)}}','Livro: ao ser lido, concede Botânica.'),mk('{Grimório(Livro)|+1 SANIDADE}','Livro: ao ser lido, concede +1 SANIDADE.'),mk('{Códice Legal(Livro)|{Legislação(Perícia)}}','Livro: ao ser lido, concede Legislação.'),mk('{Necronomicon(Livro)|{ESTADO:Enloquecido}}','Livro: ao ser lido, adiciona o estado Enloquecido.'),mk('{Mapa Anotado(Livro)|{Cultura Geral(Perícia)}}','Livro produzido: ao ser estudado, concede Cultura Geral.')],
