  function createTestForChoice(){const s=appState.book.sections[appState.sectionId],c=s.choices[appState.editingChoiceIndex];if(!c)return;const old=[c.target,c.success,c.failure].filter(Boolean),type=el('testType').value,difficulty=document.querySelector('input[name="testDifficulty"]:checked')?.value||'normal',existingTest=(c.type==='test'||c.type==='answer')&&c.success&&c.failure,knowledge=normalizeKnowledgeName(el('testKnowledgeInput')?.value),isKnowledge=type==='PERICIA';if(isKnowledge&&!knowledge){toast('Informe a Perícia que será testada.');el('testKnowledgeInput')?.focus();return;}c.type='test';c.test=isKnowledge?'SABER':type;c.knowledge=isKnowledge?knowledge:null;c.testDifficulty=difficulty;c.magicCost=type==='SANIDADE'?Math.max(1,Math.min(12,parseInt(el('testMagicCost').value)||2)):null;c.question='';c.expectedAnswer='';c.exactAnswer=false;if(!existingTest){c.success=createSection('Sucesso');c.failure=createSection('Fracasso');c.target=null;c.successLabel='Sucesso';c.failureLabel='Fracasso';old.forEach(t=>cleanupOldTarget(c,t));}if(!c.text.trim())c.text=isKnowledge?`Testar ${knowledge}`:`Testar ${c.test}`;invalidateAdventureGraphAnalysis();el('testDialog').close();renderAlternativesEditor(appState.editingChoiceIndex);}
