  function saveAnswerChoice(){const s=appState.book.sections[appState.sectionId],c=s.choices[appState.editingChoiceIndex];if(!c)return;const question=cleanText(el('answerQuestionInput').value),expected=cleanText(el('answerExpectedInput').value);if(!question){toast('Informe a pergunta.');el('answerQuestionInput').focus();return;}if(!expected){toast('Informe a resposta correta.');el('answerExpectedInput').focus();return;}const old=[c.target,c.success,c.failure].filter(Boolean),existingAnswer=(c.type==='answer'||c.type==='test')&&c.success&&c.failure;c.type='answer';c.question=question;c.expectedAnswer=expected;c.exactAnswer=!!el('answerExactCheck').checked;c.test=null;c.knowledge=null;c.testDifficulty='normal';c.magicCost=null;if(!existingAnswer){c.success=createSection('Sucesso');c.failure=createSection('Fracasso');c.target=null;c.successLabel='Sucesso';c.failureLabel='Fracasso';old.forEach(t=>cleanupOldTarget(c,t));}if(!c.text.trim())c.text='Responder';invalidateAdventureGraphAnalysis();el('answerEditorDialog').close();renderAlternativesEditor(appState.editingChoiceIndex);}
