  const FX_OPS=[['APTIDÃO','APTIDÃO'],['VIDA','VIDA'],['SANIDADE','SANIDADE'],['FORTUNA','FORTUNA'],['MOEDA','MOEDA'],['ITEM','ITEM'],['ESTADO','ESTADO']];
  function parseFxEditorEffect(raw=''){const t=String(raw||'').trim();let m=t.match(/^([+-])\s*([\d.]+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA|MOEDA)$/i);if(m){const token=String(m[3]).toUpperCase()==='MOEDA'?'MOEDA':normalizeStatToken(m[3]);return {op:token,amount:String((m[1]==='-'?-1:1)*Number(m[2])),value:''};}m=t.match(/^ESTADO:(.+)$/i);if(m)return {op:'ESTADO',amount:'1',value:m[1].trim()};m=t.match(/^SEM_ESTADO:(.+)$/i);if(m)return {op:'ESTADO',amount:'-1',value:m[1].trim()};m=t.match(/^([+-])\s*(.+)$/);if(m){const qi=parseQtyItem(m[2]);if(qi.item)return {op:'ITEM',amount:String((m[1]==='-'?-1:1)*(qi.qty||1)),value:qi.item};}return {op:'ITEM',amount:'1',value:''};}
  function fxRowValue(row){const op=row.querySelector('[data-fx=op]').value,amount=Number(row.querySelector('[data-fx=amount]').value),value=cleanText(row.querySelector('[data-fx=value]').value);if(!Number.isFinite(amount)||amount===0)return '';const signed=`${amount>0?'+':''}${amount}`;if(['APTIDÃO','VIDA','SANIDADE','FORTUNA','MOEDA'].includes(op))return `${signed} ${op}`;if(op==='ITEM')return value?`${signed} ${value}`:'';if(op==='ESTADO')return value?(amount<0?`SEM_ESTADO:${value}`:`ESTADO:${value}`):'';return '';}
  function addFxEditorRow(boxId,effect=''){const box=el(boxId),data=parseFxEditorEffect(effect),row=document.createElement('div');row.className='fx-row';const op=document.createElement('select');op.dataset.fx='op';for(const [v,l] of FX_OPS){const o=document.createElement('option');o.value=v;o.textContent=l;op.appendChild(o);}op.value=FX_OPS.some(x=>x[0]===data.op)?data.op:'ITEM';const amount=document.createElement('input');amount.dataset.fx='amount';amount.type='number';amount.step='1';amount.value=data.amount||'1';amount.title='Valor positivo adiciona; valor negativo remove ou reduz';const amountStepper=makeNumberStepper(amount,{step:1});const value=document.createElement('input');value.dataset.fx='value';value.value=data.value||'';const remove=document.createElement('button');remove.type='button';remove.className='fx-remove';remove.textContent='✕';remove.onclick=()=>row.remove();const changed=()=>{};const sync=()=>{const v=op.value,needsName=v==='ITEM'||v==='ESTADO';value.classList.toggle('hidden',!needsName);value.classList.toggle('fx-value-wide',needsName);value.placeholder=v==='ESTADO'?'Nome do Estado':v==='ITEM'?'Nome do item':'';if(v==='ESTADO'&&!Number(amount.value))amount.value='1';changed();};op.onchange=sync;amount.oninput=changed;value.oninput=changed;row.append(op,amountStepper,value,remove);box.appendChild(row);const v=op.value,needsName=v==='ITEM'||v==='ESTADO';value.classList.toggle('hidden',!needsName);value.classList.toggle('fx-value-wide',needsName);value.placeholder=v==='ESTADO'?'Nome do Estado':v==='ITEM'?'Nome do item':'';}
  function fillFxEditor(boxId,raw=''){const box=el(boxId);box.innerHTML='';const list=effectList(raw);(list.length?list:['']).forEach(x=>addFxEditorRow(boxId,x));}
  function collectFxEditor(boxId){return [...el(boxId).querySelectorAll('.fx-row')].map(fxRowValue).filter(Boolean).join('; ');}
  function fxScopeEditorLabel(scope){return scope.kind==='SECTION'?'até sair da seção':scope.kind==='NEXT_TEST'?'até fim do próximo teste':scope.kind==='NEXT_COMBAT'?'até fim do próximo combate':scope.kind==='TURNS'?`${scope.value} turno(s)`:scope.kind==='HOURS'?`${scope.value} hora(s)`:'permanente';}
  function syncFxScopeControls(scopeId,durationId,wrapId){const timed=['TURNS','HOURS'].includes(el(scopeId).value),hours=el(scopeId).value==='HOURS';el(wrapId).classList.toggle('hidden',!timed);el(durationId).step=hours?'0.5':'1';el(durationId).min=hours?'0.5':'1';}
  function serializeFxScopeControl(scopeId,durationId){const scope=el(scopeId).value,dur=Math.max(scope==='HOURS'?.5:1,Number(el(durationId).value)||1);return scope==='TURNS'?`TURNS:${Math.max(1,Math.round(dur))}`:scope==='HOURS'?`HOURS:${Math.round(dur*2)/2}`:scope;}
  function setFxScopeControls(scopeId,durationId,wrapId,raw=''){const scope=parseFxScopeValue(raw);el(scopeId).value=['SECTION','NEXT_TEST','NEXT_COMBAT','TURNS','HOURS'].includes(scope.kind)?scope.kind:'';el(durationId).value=scope.value||1;syncFxScopeControls(scopeId,durationId,wrapId);}
