  function branchSides(source='1d6'){const m=String(source||'').match(/^1d(2|4|6|8|10|12|20)$/i);return m?Number(m[1]):6;}
  function openBranchDialog(i){appState.editingChoiceIndex=i;const c=appState.book.sections[appState.sectionId].choices[i];if(!c)return;const allowed=['1d2','1d4','1d6','1d8','1d10','1d12','1d20'],spec=String(c.branchDice||'1d6');el('branchSource').value=allowed.includes(spec)?spec:(allowed.find(x=>branchSides(x)===(c.branches||[]).length)||'1d6');el('branchSilent').checked=!!c.branchSilent;el('branchDialog').showModal();}
